//! Scene controller: opens a Reach cache, decodes structure BSPs, decorators, decals, sky and
//! placed objects into GPU meshes (materials, baked lighting, particles, screen FX), and keeps
//! them in sync with the object table each tick. Objects sharing a render model are batched
//! into ONE instanced mesh; decoded geometry is cached per model tag so only instance
//! transforms rebuild when objects move.

use std::collections::HashMap;
use std::sync::Arc;

use bytemuck::{Pod, Zeroable}; // Disk cache: Pod/Zeroable derives + zeroed for byte (de)serialize
use eframe::wgpu;
use glam::{Mat4, Vec3, Vec4};
use hms_ipc::ObjectInfo;
use hms_native::{BspHandle, CacheHandle, NativeDll};
use hms_render::{GpuMesh, LightmapInputs, MeshRenderer, MeshVertex};

/// Bimodal-alpha ("is this a cutout mask?") test on a decoded RGBA diffuse.
///
/// Reach authors a lot of foliage as opaque-blend with NO `alpha_test_map`, so the
/// material flag alone misses it and the canopy renders as solid black leaf cards.
/// A diffuse whose alpha is mostly fully-transparent or fully-opaque (and not a
/// smooth gradient) is a cutout mask. Shared by the model-level classifier and the
/// per-submesh one so single-part and multi-part objects classify identically.
fn alpha_hist_cutout(tex: Option<&(Vec<u8>, u32, u32)>) -> bool {
    tex.map_or(false, |(rgba, _, _)| {
        let (mut n, mut tp, mut op) = (0usize, 0usize, 0usize);
        for px in rgba.chunks_exact(4).step_by(16) {
            n += 1;
            if px[3] < 32 { tp += 1; } else if px[3] > 224 { op += 1; }
        }
        // Bimodal cutout OR >=45% fully-transparent (sparse foliage).
        n > 0 && ((tp * 100 / n >= 30 && op * 100 / n >= 20) || tp * 100 / n >= 45)
    })
}

/// A decoded (bgra bytes, w, h) texture shared by reference. Object parts used to OWN a copy
/// of every texture they referenced (2711 copies of 412 unique bitmaps on Forge World = 4.6 GB of
/// resident heap, the single largest consumer); the final per-part bytes are now interned by
/// render_method (`share_part_textures`) so identical textures are one allocation. Deref gives the old tuple.
pub type SharedTex = std::sync::Arc<(Vec<u8>, u32, u32)>;

/// Models decoded per parallel batch before the allocator is asked to return the batch's
/// freed decode temporaries (see `predecode_tags` / `start_background_predecode`).
const PREDECODE_BATCH: usize = 48;
/// BSP texture-prewarm tags uploaded between two queue submits (bounds the staging in flight).
const PREWARM_CHUNK: usize = 24;

/// GPU-texture KIND, part of the by-source key of `obj_tex_ensure` (the same CPU bytes
/// uploaded two ways are two GPU textures). 0/1 are formats; 2/3/4/7 name the inner texture of a
/// shared `FfExtra` / `GlassOp` (whose identity is the outer Arc), all uploaded as BGRA + mips.
const OBJ_TEX_BGRA_MIPS: u8 = 0;
const OBJ_TEX_RGBA16F: u8 = 1;

/// Make sure `key` (mode tag, part, slot) has its GPU texture, uploading `tex` only if no
/// earlier (tag, part, slot) already uploaded the SAME source (`ident` = the Arc pointer of the
/// decoded bytes, stable for the life of geom_cache). Parts/models that intern one decoded texture
/// (`share_part_textures`) now share ONE GPU texture instead of a copy per (tag, part, slot).
fn obj_tex_ensure(
    cache: &mut HashMap<(u32, usize, u8), (wgpu::TextureView, wgpu::Texture)>,
    by_src: &mut HashMap<(usize, u8), (wgpu::TextureView, wgpu::Texture)>,
    device: &wgpu::Device,
    queue: &wgpu::Queue,
    key: (u32, usize, u8),
    ident: usize,
    kind: u8,
    tex: &(Vec<u8>, u32, u32),
) {
    if cache.contains_key(&key) {
        return;
    }
    let sk = (ident, kind);
    if let Some((v, t)) = by_src.get(&sk) {
        cache.insert(key, (v.clone(), t.clone()));
        return;
    }
    if tex.0.is_empty() {
        return; // bytes already released: only possible once every user of them was uploaded
    }
    let up = if kind == OBJ_TEX_RGBA16F {
        hms_render::upload_texture_rgba16f_nomip(device, queue, &tex.0, tex.1, tex.2)
    } else {
        hms_render::upload_texture_bgra(device, queue, &tex.0, tex.1, tex.2)
    };
    by_src.insert(sk, (up.0.clone(), up.1.clone()));
    cache.insert(key, up);
}

/// Free the CPU bytes of a shared texture once nothing else shares it (`Arc::get_mut` fails
/// while another part/model or an in-flight decode still holds the Arc -- those retry later). The
/// Arc itself stays (same pointer, so `obj_tex_by_src` keys stay valid and `is_some()` routing is
/// unchanged); only the byte Vec is emptied.
fn release_shared_tex(t: &mut Option<SharedTex>) {
    if let Some(a) = t.as_mut() {
        if let Some(inner) = std::sync::Arc::get_mut(a) {
            if !inner.0.is_empty() { inner.0 = Vec::new(); }
        }
    }
}

/// Drop the CPU texture bytes of a model whose textures are all on the GPU (every slot the
/// object rebuild uploads from: diffuse / emissive / emissive_hdr / change-colour mask / glass detail /
/// glass opacity + specular mask / forcefield palette + overlay). Geometry (verts, indices) is kept:
/// picking, selection wireframes and GPU buffer creation still read it.
fn release_model_texture_bytes(d: &mut DecodedModel) {
    release_shared_tex(&mut d.tex);
    release_shared_tex(&mut d.emissive);
    release_shared_tex(&mut d.emissive_hdr);
    release_shared_tex(&mut d.cc_map);
    if let Some(g) = d.glass_op.as_mut() {
        if let Some(g) = std::sync::Arc::get_mut(g) {
            if let Some(t) = g.tex.as_mut() { t.0 = Vec::new(); }
            release_shared_tex(&mut g.smask_tex);
        }
    }
    if let Some(x) = d.ff_extra.as_mut() {
        if let Some(x) = std::sync::Arc::get_mut(x) {
            x.palette.0 = Vec::new();
            if let Some(o) = x.overlay.as_mut() { o.0 = Vec::new(); }
        }
    }
    for p in d.obj_parts.iter_mut() {
        release_shared_tex(&mut p.tex);
        release_shared_tex(&mut p.emissive);
        release_shared_tex(&mut p.emissive_hdr);
        release_shared_tex(&mut p.glass_detail);
        if let Some(g) = p.glass_op.as_mut() {
            if let Some(g) = std::sync::Arc::get_mut(g) {
                if let Some(t) = g.tex.as_mut() { t.0 = Vec::new(); }
                release_shared_tex(&mut g.smask_tex);
            }
        }
        if let Some(x) = p.ff_extra.as_mut() {
            if let Some(x) = std::sync::Arc::get_mut(x) {
                x.palette.0 = Vec::new();
                if let Some(o) = x.overlay.as_mut() { o.0 = Vec::new(); }
            }
        }
    }
}

/// One per-shader draw part of an OBJECT render model (forge/scenery/vehicle). Reach
/// object models split a section's index range into submeshes, each with its OWN shader
/// (diffuse/blend/emissive) — e.g. the coliseum wall's face vs its trim. We group submeshes
/// by shader into parts so each renders with its correct material (matching the C# path).
/// Indices point into the shared `DecodedModel.verts`. Empty on the BSP path.
struct ObjPart {
    indices: Vec<u32>,
    /// hlmt VARIANT membership of this part's sections (bit v = shown by variant v of
    /// `DecodedModel::variant_sids`; all ones = every variant / no variants). The rebuild draws a part
    /// only for the placements whose variant bit is set (Spartan vs Elite armor-ability pickups).
    vbits: u64,
    tex: Option<SharedTex>,
    /// This submesh's diffuse bitmap tag — lets `classify_diffuse` (the same
    /// foliage/spec-mask classifier the BSP path uses) run per submesh.
    diffuse_tag: u32,
    emissive: Option<SharedTex>,
    blend: u32,
    alpha_test: bool,
    /// This part's authored `base_map` UV xform SCALE (rmt2 real constant.xy), the
    /// engine's calc_albedo_*_ps `transform_texcoord(texcoord, base_map_xform)`. Uploaded as the
    /// mesh `tile` for opaque/cutout rmsh parts. Object parts always uploaded [1,1] before, so a
    /// base map authored as a tiled detail (ff_race_stunt_ramp: burned_detail 0.4x30, truck paint
    /// 25x25) stretched ONCE across the whole panel -> a flat grey smear. (1,1) = untiled.
    base_tile: [f32; 2],
    /// This submesh's shader is an rmgl (glass) tag → route to the alpha-blend
    /// pass. The blend-mode resolver reads the rmsh layout and returns the 0xFF
    /// "unresolved" sentinel for rmgl, which is indistinguishable from other
    /// unresolved shaders, so the tag class is the reliable glass signal.
    is_glass: bool,
    /// This submesh's shader is an rmgh (shader_halogram) — a translucent additive hologram
    /// (e.g. the armor-ability equipment holder pedestal). Its blend resolves to the 0xFF sentinel
    /// like rmgl, so the tag class is the reliable signal; route it to the additive holo pass
    /// instead of the opaque pass (which rendered it as a solid BLACK cone).
    is_halo: bool,
    /// Glass material (RE docs/hrek_re/09_re_glass.md): the REAL rmgl constants.
    /// Forge forerunner glass is authored with albedo_color≈[0,0,0] (BLACK diffuse body)
    /// — its visible colour is entirely REFLECTION, tinted by env_tint_color (dominant)
    /// and glancing_specular_tint (grazing rim). Read by name from the model rmt2 (the
    /// name-indexed reader works for rmgl). None for non-glass parts. Fields:
    /// (albedo_color.rgb, env_tint_color.rgb, glancing_specular_tint.rgb, fresnel_steepness).
    glass_mat: Option<([f32; 3], [f32; 3], [f32; 3], f32, f32, f32)>,
    /// rmsh glass opacity map + fresnel triplet (None → base alpha).
    glass_op: Option<std::sync::Arc<GlassOp>>,
    /// rmgl glass DETAIL map (keep-alpha) + xform + albedo_color.a — engine albedo_default:
    /// opacity = base.a × detail.a × albedo_color.a (the forge window's tech pattern lives in detail.a).
    glass_detail: Option<std::sync::Arc<(Vec<u8>, u32, u32)>>,
    glass_detail_xform: [f32; 4],
    glass_albedo_a: f32,
    /// Authored environment_map cube tag + environment_map_specular_contribution (engine per_pixel
    /// envmap: cube.rgb·cube.a × contribution × 0.25(dom+fill) × env_tint_color). (0, 0) = none.
    glass_env: (u32, f32),
    /// (objects): rmsh template environment_mapping digit (2 = dynamic → neutral stand-in).
    glass_env_opt: u8,
    /// (rmgl): env DYNAMIC lod = (analytical_roughness + (env_roughness_offset-0.5)*2)*4, >= 0
    /// (environment_mapping.hlsl_include:129) for the per-cluster cube; rmsh parts carry theirs in GlassOp.
    glass_dyn_lod: f32,
    /// This emissive part uses a CHANGE_COLOR self-illum (recolours by the object's placed
    /// team/colour — only ff_init_spawn_point). False = FIXED-colour self-illum (hill beacon, flag,
    /// circle, mp_spawn): its authored colour is baked into `emissive` at decode and it must NOT be
    /// team-tinted. Determines whether the holo pass multiplies by the per-instance change-colour.
    emis_change_color: bool,
    /// This part is a shader_halogram `palettized_plasma` forcefield (shield door/wall, laser
    /// wall — rmhg self_illum option 10/11/12). Routed to the animated fs_forcefield pass: two
    /// scrolling samples of the noise map (`tex`) are differenced and indexed into the colour
    /// `palette` (carried in `emissive`), reproducing the churning plasma energy field.
    is_forcefield: bool,
    /// Forcefield noise scroll rate/sec (model_shader_scroll — the real engine animation).
    ff_scroll: [f32; 2],
    /// Forcefield self_illum_color (the palette is multiplied by this × intensity).
    ff_color: [f32; 3],
    /// The full engine material (None → legacy grayscale-noise glow).
    ff_extra: Option<std::sync::Arc<FfExtra>>,
    /// This OPAQUE part's FIXED self-illum baked in FLOAT (Rgba16Float, packed as
    /// f16 little-endian bytes, 8/px) — same treatment as DecodedMesh.emissive_hdr on the BSP path.
    /// Built only in the `!emis_change_color` fixed-colour bake from the ORIGINAL emissive texels ×
    /// self_illum_color × self_illum_intensity with NO upper clamp (floor 0), so an authored
    /// intensity>1 (ammo_box 6-8, forge platforms 14, seraph 26, …) survives to the exposed-space
    /// bloom instead of clipping to flat white in the u8 `emissive`. None for holo/marker/change_
    /// color/glass/forcefield parts (they keep the u8 `emissive`). When Some AND the part routes to
    /// the OPAQUE pass, the object upload prefers it as the mesh_shade emis_tex.
    emissive_hdr: Option<SharedTex>,
    /// This PART's rmsh two/four_change_color albedo mask (change_color_map, r = primary,
    /// g = secondary) + UV xform. Multi-material vehicles (Mongoose body, Shade turret) carry their
    /// change-colour albedo on individual parts; DecodedModel.cc_map only covered single-material
    /// objects (Forge pallets). Bound in the MAT-30 slot exactly like the single-material lane.
    cc_map: Option<std::sync::Arc<(Vec<u8>, u32, u32)>>,
    cc_map_xform: [f32; 4],
    /// LIT-SI-3 (object side): this submesh's `self_illumination` MODE enum (0..12), resolved from
    /// the render-model rmsh via ZH_MMP_GetShaderSelfIllumMode. Mirrors DecodedModel.self_illum_mode.
    /// Only from_albedo (4) is routed specially in mesh_shade (emit albedo×cmul, zero the lit albedo);
    /// every other mode keeps the current object path. Default 1 (simple = single-composite emissive).
    self_illum_mode: u8,
    /// LIT-SI-3: `self_illum_color.rgb × self_illum_intensity` (unclamped HDR), used only by the
    /// from_albedo route to synthesize emission from the sampled albedo. [0;3] when not authored.
    self_illum_cmul: [f32; 3],
    /// This part's engine material lanes (detail/bump/env/specular); `valid`=false = legacy lane.
    mat: ObjMat,
    /// This part is an rmfl (foliage.render_method_definition) material →
    /// `[material_model digit (0 flat / 1 specular / 2 translucent), foliage_translucency]`, uploaded as
    /// si_ctl = [FOLIAGE_SI_MODE, translucency, type, 0] so mesh_shade runs the engine foliage lighting
    /// (front+back dual-vMF, |N·L| sun, no specular). None = not foliage.
    foliage: Option<[f32; 2]>,
    /// This part is an rmtr (terrain_templates) material of a MULTI-material model → its
    /// terrain layers (blend map + up to 4 base/detail/bump layers), rendered through the same
    /// Lane single-material rmtr objects (Forge rocks) already use. Without it the part fell to
    /// the generic diffuse pick = layer 0's base map alone (the Tree of Life root mass drew as flat khaki
    /// `ca_bcreek_grass` instead of the blend-mapped rock/grass). None = not terrain.
    terrain: Option<TerrainTags>,
}

/// si_ctl.x sentinel for an rmfl object part (mesh_shade `rmfl` lane). Outside the
/// self_illumination enum range (0..12, which the BSP path uploads verbatim) so it can never collide
/// with a real self-illum mode. Must match `FOLIAGE_SI_MODE` in hms-render mesh.rs.
const FOLIAGE_SI_MODE: f32 = 20.0;

/// rmfl material lane of a render-model shader (None unless the shader class is rmfl).
/// foliage_templates `_A_B_C_D`: C = material_model (foliage.render_method_definition: 0 flat,
/// 1 specular, 2 translucent); `foliage_translucency` is the authored real constant (0 when absent —
/// the flat model doesn't read it).
fn model_shader_foliage(native: &NativeDll, cache: CacheHandle, model: hms_native::ModelHandle, sh: i32) -> Option<[f32; 2]> {
    if native.model_shader_class(model, sh) != "rmfl" { return None; }
    let tm = native.model_shader_template_tag(model, sh);
    let mt = if tm >= 0 { native.tag_name(cache, tm as u32).and_then(|n| rm_template_digits(&n).get(2).copied()).unwrap_or(0) } else { 0 };
    let t = native.model_shader_constants(model, sh)
        .and_then(|c| c.real("foliage_translucency").map(|v| v[0]).or_else(|| c.scalar("foliage_translucency")))
        .filter(|v| v.is_finite() && *v >= 0.0).unwrap_or(0.0);
    Some([mt.clamp(0, 2) as f32, t.min(1.0)])
}

/// MeshVertex.tangent.w sentinel for an rmfl BSP/instance vertex whose tangent.xyz
/// carries the engine BACK-face per-vertex lighting (`dual_vmf_diffuse(-N)`). A real stored tangent
/// frame has w = ±1 and the derivative fallback w = 0, so the value can never collide. Must match
/// `BSP_FOLIAGE_TAN_SENTINEL` in hms-render mesh.rs.
const BSP_FOLIAGE_TAN_SENTINEL: f32 = -4.0;

/// rmfl material lane of a BSP material (None unless the shader class is rmfl) —
/// `[material_type digit (0 flat / 1 specular / 2 translucent), foliage_translucency (RAW, the
/// translucent type evaluates saturate((1 - alpha) * 2 * foliage_translucency) per pixel),
/// alpha_test digit (0 none / 1 from_albedo_alpha / 2 from_texture)]` (foliage.render_method_definition
/// category order: albedo, alpha_test, material_model, wetness).
fn bsp_shader_foliage(native: &NativeDll, cache: CacheHandle, bsp: hms_native::BspHandle, mat: i32) -> Option<[f32; 3]> {
    if mat < 0 || native.bsp_material_shader_class(bsp, mat) != "rmfl" { return None; }
    let digits = native.bsp_material_shader_tag(bsp, mat)
        .and_then(|sh| native.rm_template_name(cache, sh))
        .map(|n| rm_template_digits(&n))
        .unwrap_or_default();
    let mt = digits.get(2).copied().unwrap_or(0);
    let at = digits.get(1).copied().unwrap_or(0);
    let t = native.bsp_material_shader_constants(bsp, mat)
        .and_then(|c| c.real("foliage_translucency").map(|v| v[0]).or_else(|| c.scalar("foliage_translucency")))
        .filter(|v| v.is_finite() && *v >= 0.0).unwrap_or(0.0);
    Some([mt.clamp(0, 2) as f32, t, at.clamp(0, 2) as f32])
}

/// Parse a render_method_template (rmt2) tag NAME → (self_illum option index, is_halogram).
/// Template names encode the per-category option digits, e.g.
/// `shaders\halogram_templates\_2_8_3_0_1_1_0` — halogram self_illum = the 2nd number; opaque
/// `shader_templates\_a_b_c_d_e_f_g…` self_illum = the 7th number (RE_marker_color.md).
/// (objects): rmsh alpha_blend glass with an authored `opacity_texture` + opacity-fresnel
/// triplet (blend.hlsl_include): final_opacity = 1-(1-opacity)(1-fresnel). Forge window pieces
/// (for_forge_glass: base near-black, opacity in for_forge_glass_gen_02_opacity) need this — without it
/// the pane's coverage came from the base alpha × albedo_color.a and read far too pale/flat.
#[derive(Clone)]
struct GlassOp {
    /// None when the template's alpha_blend_source is albedo-alpha (digits 0/1, e.g. the
    /// man-cannon / teleporter `stunt_ramp_glass`) -- the lanes below still apply, opacity = albedo.w.
    tex: Option<(Vec<u8>, u32, u32)>,
    xform: [f32; 4],
    /// albedo_color (calc_albedo_default_ps: albedo = base x detail x 4.59 x albedo_color.rgb,
    /// albedo.w = base.a x detail.a x albedo_color.a) -> mat_spec2 = [rgb, 2 + a] (the BSP glass lane).
    albedo: [f32; 4],
    /// [roughness (LUT z / env lod for per_pixel), analytical_roughness (cook-torrance m),
    /// specular_mask_texture xform sx, sy] -> spec_rgb.w / fres_rgb.w / bump_detail_xform.xy.
    rough: [f32; 4],
    /// Env DYNAMIC lod = (analytical_roughness + (env_roughness_offset - 0.5) * 2) * 4
    /// (environment_mapping.hlsl_include:44-45,129), >= 0; used when the cluster cube is bound.
    dyn_lod: f32,
    /// 1 = opacity map alpha, 2 = opacity map RGB luminance.
    mode: f32,
    /// [coefficient, steepness, bias, 2.0] (w=2 flags the lane); [0;4] when not authored.
    fres: [f32; 4],
    /// 1 = the opacity bitmap's curve is gamma-encoded (decode before the luma), 0 = linear.
    gamma: f32,
    /// Env lanes for blend_shade's rmsh path: [env_tint_color.rgb, specular_coefficient]
    /// (env_ctl), environment_map_specular_contribution (bump_detail_xform.w), per_pixel base LOD
    /// (environment_mapping.hlsl_include offset_env_reflection_lod(0) = (env_roughness_offset-0.5)*8, xctl.w).
    env_ctl: [f32; 4],
    env_contrib: f32,
    env_lod: f32,
    /// (object rmsh glass): [albedo_blend, diffuse_coefficient, 1 + rmt2 specular_mask digit
    /// (0 none, 1 from_diffuse = albedo.w, 2 albedo.w x mask_tex.a, 3 mask_tex.a; the mask texture is not
    /// bound on the object path -> digits 2/3 use tex.a = 1), 0] -> the xbump lane blend_shade reads.
    ctl: [f32; 4],
    /// [specular_tint.rgb, fresnel_curve_steepness] -> si_ctl; cook_torrance_core:80-83
    /// final_tint = lerp(lerp(specular_tint, albedo, albedo_blend), fresnel_color, (1-NoV)^steepness).
    spec_tint: [f32; 4],
    /// fresnel_color.rgb (w = 1) -> the fres_rgb instance lane.
    fres_color: [f32; 4],
    /// The `specular_mask_texture` (keep-alpha) for spec-mask digits 2/3; rides the object
    /// material_texture slot (obj_tex_cache slot 7) and sets ctl.z += 4 at upload.
    smask_tex: Option<std::sync::Arc<(Vec<u8>, u32, u32)>>,
}

fn decode_glass_op(native: &NativeDll, cache: CacheHandle, bmp: Option<&BitmapCache>, model: hms_native::ModelHandle, sh: i32) -> Option<GlassOp> {
    if ev("HMS_NO_OPACITY_MAP").is_ok() { return None; }
    let t = native.model_shader_bitmap_by_usage(model, sh, "opacity_texture");
    // An object rmsh glass WITHOUT an opacity map (alpha_blend_source albedo-alpha, e.g. the
    // man-cannon / teleporter stunt_ramp_glass) still gets every other engine lane; opacity = albedo.w.
    let op_tex = if t == 0 || t == 0x20 || t == 0x2f || t == 0xFFFF_FFFF { None } else { native.decode_bitmap_keep_alpha(cache, t, 0, 0).or_else(|| cached_bitmap(bmp, native, cache, t)) };
    let (mut amin, mut amax) = (255u8, 0u8);
    if let Some((px, _, _)) = op_tex.as_ref() { for p in px.chunks_exact(4) { amin = amin.min(p[3]); amax = amax.max(p[3]); } }
    // rmt2 digit 11 (alpha_blend_source: 2 opacity_map_alpha, 3 opacity_map_rgb, 4 alpha_and_albedo), heuristic fallback
    let abs_digit = { let tm = native.model_shader_template_tag(model, sh); if tm >= 0 { native.tag_name(cache, tm as u32).and_then(|n| rm_template_digits(&n).get(11).copied()) } else { None } };
    let mode = if op_tex.is_none() { 0.0 } else { match abs_digit { Some(2) => 1.0, Some(3) => 2.0, Some(4) => 3.0, _ => if amax > amin + 8 && amin < 250 { 1.0 } else { 2.0 } } };
    let sc = native.model_shader_constants(model, sh);
    let xform = sc.as_ref().and_then(|c| c.real("opacity_texture")).filter(|v| v.iter().all(|x| x.is_finite()) && v[0].abs() > 1e-6).unwrap_or([1.0, 1.0, 0.0, 0.0]);
    let g = |n: &str| sc.as_ref().and_then(|c| c.real(n).map(|v| v[0]).or_else(|| c.scalar(n))).filter(|v| v.is_finite());
    // blend.hlsl_include:128: alpha_blend_source 0 (albedo_alpha_without_fresnel) skips the opacity fresnel.
    let fres = match (g("opacity_fresnel_coefficient"), g("opacity_fresnel_curve_steepness")) {
        (Some(c), Some(st)) if c > 0.01 && st > 0.01 && abs_digit != Some(0) => [c, st, g("opacity_fresnel_curve_bias").unwrap_or(0.0).max(0.0), 2.0],
        _ => [0.0; 4],
    };
    let gamma = if op_tex.is_none() || curve_is_linear(native, cache, t) { 0.0 } else { 1.0 };
    let alb = sc.as_ref().and_then(|c| c.real("albedo_color")).filter(|v| v.iter().all(|x| x.is_finite())).map(|v| [v[0].max(0.0), v[1].max(0.0), v[2].max(0.0), v[3].max(0.0)]).unwrap_or([1.0; 4]);
    let rough_lut = g("roughness").filter(|v| *v >= 0.0).unwrap_or(0.04).clamp(0.0, 1.0);
    let arough = g("analytical_roughness").filter(|v| *v > 0.0).unwrap_or(0.25).clamp(0.0, 1.0);
    let smx = sc.as_ref().and_then(|c| c.real("specular_mask_texture")).filter(|v| v.iter().all(|x| x.is_finite()) && v[0].abs() > 1e-6).map(|v| [v[0], v[1]]).unwrap_or([1.0, 1.0]);
    let dyn_lod = ((arough + (g("env_roughness_offset").unwrap_or(0.0) - 0.5) * 2.0) * 4.0).clamp(0.0, 6.0);
    let et = sc.as_ref().and_then(|c| c.real("env_tint_color")).filter(|v| v.iter().all(|x| x.is_finite())).unwrap_or([1.0, 1.0, 1.0, 1.0]);
    let scoef = g("specular_coefficient").filter(|v| *v > 0.0).unwrap_or(1.0);
    let env_contrib = g("environment_map_specular_contribution").filter(|v| *v >= 0.0).unwrap_or(1.0);
    let env_lod = g("env_roughness_offset").map_or(0.0, |o| ((o - 0.5) * 8.0).clamp(0.0, 6.0));
    // The cook_torrance tint pair + albedo_blend / diffuse_coefficient / specular_mask digit (rmsh digit 3).
    let san3 = |v: Option<[f32; 4]>, d: f32| -> [f32; 3] { match v { Some(c) if c[..3].iter().all(|x| x.is_finite()) => [c[0].max(0.0), c[1].max(0.0), c[2].max(0.0)], _ => [d; 3] } };
    let st = san3(sc.as_ref().and_then(|c| c.real("specular_tint")), 1.0);
    let fc = san3(sc.as_ref().and_then(|c| c.real("fresnel_color")), 1.0);
    let steep = g("fresnel_curve_steepness").filter(|v| *v > 0.0).unwrap_or(3.0);
    let ablend = g("albedo_blend").unwrap_or(0.0).clamp(0.0, 1.0);
    let dcoef = g("diffuse_coefficient").filter(|v| *v >= 0.0).unwrap_or(1.0);
    let smask_digit = { let tm = native.model_shader_template_tag(model, sh); if tm >= 0 { native.tag_name(cache, tm as u32).and_then(|n| rm_template_digits(&n).get(3).copied()).filter(|d| (0..=3).contains(d)).unwrap_or(0) } else { 0 } };
    if ev("HMS_GLASSDIAG").is_ok() {
        let mt = native.model_shader_bitmap_by_usage(model, sh, "specular_mask_texture");
        eprintln!("GLASSCTL sh={sh} albedo_blend={ablend:.3} diffuse_coefficient={dcoef:.3} spec_mask_digit={smask_digit} mask_tex={mt:#x} spec_tint={st:?} fres_color={fc:?} steep={steep:.2} contrib={env_contrib:.3}");
    }
    // specular_mask.hlsl_include digits 2/3 read specular_mask_texture.a (the coliseum window: 0x214d).
    let smask_tex = if smask_digit >= 2 {
        let mt = native.model_shader_bitmap_by_usage(model, sh, "specular_mask_texture");
        if mt != 0 && mt != 0x20 && mt != 0x2f && mt != 0xFFFF_FFFF { native.decode_bitmap_keep_alpha(cache, mt, 0, 0).or_else(|| cached_bitmap(bmp, native, cache, mt)).map(std::sync::Arc::new) } else { None }
    } else { None };
    Some(GlassOp { tex: op_tex, xform, albedo: alb, rough: [rough_lut, arough, smx[0], smx[1]], dyn_lod, mode, fres, gamma, env_ctl: [et[0].max(0.0), et[1].max(0.0), et[2].max(0.0), scoef], env_contrib, env_lod,
        ctl: [ablend, dcoef, 1.0 + smask_digit as f32, 0.0], spec_tint: [st[0], st[1], st[2], steep], fres_color: [fc[0], fc[1], fc[2], 1.0], smask_tex })
}

/// The ENGINE material of one OPAQUE/cutout rmsh object part (unit/item objects: bipeds,
/// vehicles, weapons, equipment), read per PART from its own rmsh/rmt2 instead of shader 0's constants.
/// Vehicles (Ghost/Banshee/Warthog/Mongoose) rendered ROUGH/matte because the dynamic-object lane took
/// shader 0's constants for every part (the Ghost's shader 0 is a DAMAGE decal shader), bound no
/// detail_map (x4.59), no bump_map / bump_detail_map, and `obj_matte` zeroed the env reflection even
/// though every Covenant/UNSC paint authors env DYNAMIC (per-cluster cube) with contribution 0.5-1.0.
/// Fields follow cook_torrance_core.hlsl_include / environment_mapping.hlsl_include (see mesh_shade).
#[derive(Clone, Default)]
struct ObjMat {
    /// The lane is live for this part (rmsh, opaque/alpha-test blend, a lit material_model).
    valid: bool,
    /// rmt2 material_model digit (0 diffuse_only, 1 cook_torrance, 2 two_lobe_phong, 3 foliage, 4 none, ...).
    mm: u8,
    /// `mm` was read from the part's rmt2 (EVERY object type, opaque/alpha-test rmsh only), even when
    /// `valid` is false (scenery/crates keep the legacy lanes). The upload dispatches it as MAT-1 `matmodel` so a
    /// diffuse_only part (engine diffuse_only.hlsl_include: specular_radiance = 0, no analytic lobe) draws no
    /// Cook-Torrance glint / env / area lobe -- the Tree of Life trunk (oldwood_bark / pine_bark_new,
    /// `_0_2_0_0_0_0...`) was getting the generic object gloss because scenery never set matmodel (0 = unset).
    mm_set: bool,
    /// [specular_coefficient x analytical_specular_contribution, analytical_roughness] (mat_spec / mat_rough).
    spec: f32,
    rough: f32,
    /// `roughness` (the area/env LUT z, cook_torrance_core:233).
    rough_lut: f32,
    /// Lanes [albedo_blend, fresnel_curve_steepness, lum(specular_tint), lum(fresnel_color)].
    spec2: [f32; 4],
    spec_rgb: [f32; 4],
    fres_rgb: [f32; 4],
    /// [env_tint_color.rgb, specular_coefficient] (env_ctl).
    env_ctl: [f32; 4],
    /// environment_map_specular_contribution; 0 = no env lane.
    menv: f32,
    /// area_specular_contribution (cook_torrance_core:241 sh_glossy weight).
    area: f32,
    /// rmt2 environment_mapping digit (0 none, 1 per_pixel, 2 dynamic = the cluster cube).
    env_opt: u8,
    /// Authored environment_map cube tag for per_pixel (0 when none / not a cube).
    env_cube: u32,
    /// Cube LOD: dynamic = (analytical_roughness + (env_roughness_offset-0.5)*2)*4; per_pixel = (offset-0.5)*8.
    env_lod: f32,
    /// (tag, [tile.xy, off.xy]) for detail_map / bump_map / bump_detail_map (None = not authored / default).
    detail: Option<(u32, [f32; 4])>,
    bump: Option<(u32, [f32; 4])>,
    bump_detail: Option<(u32, [f32; 4])>,
    /// specular_mask digit 1/2 (from diffuse): the base map's alpha is the per-texel specular mask.
    spec_mask_diffuse: bool,
    /// An alpha_blend part whose authored opacity is 0 at rest (albedo_alpha source x albedo_color.a = 0):
    /// the Warthog/Mongoose `*_tire_blur` motion-blur wheel skins. The engine animates albedo_color.a
    /// from wheel speed; a parked vehicle never shows them -- HMS drew them OPAQUE over the treads.
    hidden_at_rest: bool,
}

/// Decode `ObjMat` for shader `sh` of an open render model. `obj_type` = obje +0 type
/// (the lane is enabled for 0 biped / 1 vehicle / 2 weapon / 3 equipment; Forge scenery/crates keep the
/// existing object lane untouched).
fn decode_obj_mat(native: &NativeDll, cache: CacheHandle, model: hms_native::ModelHandle, sh: i32, obj_type: u32) -> ObjMat {
    let mut m = ObjMat::default();
    if native.model_shader_class(model, sh) != "rmsh" { return m; }
    let tm = native.model_shader_template_tag(model, sh);
    let tname = if tm >= 0 { native.tag_name(cache, tm as u32).unwrap_or_default() } else { return m };
    if !tname.contains("shader_templates") { return m; }
    let digits = rm_template_digits(&tname);
    let dg = |i: usize| digits.get(i).copied().unwrap_or(0);
    // The material_model digit is the engine rule for EVERY object class (one calc_material_<m>_ps
    // per template): record it for the opaque / alpha-test blend modes of any rmsh part, then keep the full
    // lane (constants, maps, env) for unit/item objects only.
    if dg(7) == 0 { m.mm_set = true; m.mm = dg(4).clamp(0, 15) as u8; }
    // blend_mode digit 7: 3 alpha_blend / 5 pre_multiplied with albedo-alpha opacity 0 at rest -> hidden.
    // The engine rule holds for EVERY object class, so it is read before the unit/item
    // gate below: the `fx\fx_anchor\shaders\invisible` effect-scenery anchors (constant_color albedo,
    // albedo_color.a = 0, alpha_blend) drew as small opaque grey pegs at every ambient-effect spawn
    // point (Condemned's sparks / steam vents / glass clouds) instead of nothing.
    let blend = dg(7);
    if matches!(blend, 3 | 5) && matches!(dg(11), 0 | 1) {
        let a = native.model_shader_constants(model, sh).and_then(|sc| sc.real("albedo_color").map(|v| v[3])).filter(|v| v.is_finite()).unwrap_or(1.0);
        m.hidden_at_rest = a <= 1e-4;
        return m;
    }
    if !matches!(obj_type, 0 | 1 | 2 | 3) { return m; }
    let Some(sc) = native.model_shader_constants(model, sh) else { return m };
    let g = |n: &str| sc.real(n).map(|v| v[0]).or_else(|| sc.scalar(n)).filter(|v| v.is_finite());
    let xf = |n: &str| sc.real(n).filter(|v| v.iter().all(|x| x.is_finite()) && v[0].abs() > 1e-6 && v[1].abs() > 1e-6);
    let bm = |u: &str| { let t = native.model_shader_bitmap_by_usage(model, sh, u); if t == 0 || t == 0xFFFF_FFFF || t == 0x1c || t == 0x1d || t == 0x20 || t == 0x2f { 0 } else { t } };
    if blend != 0 { return m; }
    // material_model digit 4: 1 cook_torrance / 2 two_lobe_phong / 5 organism carry the specular lanes;
    // 0 diffuse_only / 4 none get albedo + bump only.
    let mm = dg(4);
    m.valid = true;
    m.mm = mm.clamp(0, 15) as u8;
    m.spec_mask_diffuse = matches!(dg(3), 1 | 2);
    m.detail = { let t = bm("detail_map"); (t != 0).then(|| (t, xf("detail_map").unwrap_or([1.0, 1.0, 0.0, 0.0]))) };
    if dg(1) != 0 {
        m.bump = { let t = bm("bump_map"); (t != 0).then(|| (t, xf("bump_map").unwrap_or([1.0, 1.0, 0.0, 0.0]))) };
        if matches!(dg(1), 2 | 3 | 4 | 6) {
            m.bump_detail = { let t = bm("bump_detail_map"); (t != 0).then(|| (t, xf("bump_detail_map").unwrap_or([1.0, 1.0, 0.0, 0.0]))) };
        }
    }
    if matches!(mm, 1 | 2 | 5 | 6) {
        let coef = g("specular_coefficient").filter(|v| *v > 0.0).unwrap_or(0.0);
        let acon = g("analytical_specular_contribution").filter(|v| *v >= 0.0).unwrap_or(1.0);
        m.spec = (coef * acon).clamp(0.0, 4.0);
        // two_lobe_phong (shared_specular.hlsl_include) names its lanes normal_specular_tint / glancing_specular_tint /
        // albedo_specular_tint_blend and drives its analytic lobe by analytical_power (Phong) -- same fresnel shape.
        let phong_m = || g("analytical_power").filter(|v| *v > 0.0).map(|p| 0.553773 * p.clamp(0.01, 2000.0).powf(-0.4551));
        m.rough = (if mm == 2 { phong_m() } else { None })
            .or_else(|| g("analytical_roughness").filter(|v| *v > 0.0))
            .or_else(|| g("roughness").filter(|v| *v > 0.0))
            .or_else(|| g("specular_power").filter(|v| *v > 0.0).map(|p| 0.553773 * p.clamp(0.01, 2000.0).powf(-0.4551)))
            .unwrap_or(0.5).clamp(0.04, 1.0);
        m.rough_lut = g("roughness").filter(|v| *v >= 0.0).unwrap_or(m.rough).clamp(0.0, 1.0);
        let lum = |c: [f32; 4]| (0.299 * c[0] + 0.587 * c[1] + 0.114 * c[2]).clamp(0.0, 1.0);
        let col = |n: &str| sc.real(n).filter(|c| c.iter().all(|x| x.is_finite()) && c[0] + c[1] + c[2] > 0.0);
        let st = col("specular_tint").or_else(|| col("normal_specular_tint"));
        let fc = col("fresnel_color").or_else(|| col("glancing_specular_tint"));
        let ablend = g("albedo_blend").or_else(|| g("albedo_specular_tint_blend")).unwrap_or(0.0).clamp(0.0, 1.0);
        m.spec2 = [ablend, g("fresnel_curve_steepness").unwrap_or(0.0).clamp(0.0, 12.0), st.map(lum).unwrap_or(0.0), fc.map(lum).unwrap_or(0.0)];
        if let Some(c) = st { m.spec_rgb = [c[0].max(0.0), c[1].max(0.0), c[2].max(0.0), 1.0]; }
        if let Some(c) = fc { m.fres_rgb = [c[0].max(0.0), c[1].max(0.0), c[2].max(0.0), 1.0]; }
        m.area = g("area_specular_contribution").filter(|v| *v >= 0.0).unwrap_or(0.0).clamp(0.0, 4.0);
        m.env_opt = dg(5) as u8;
        if m.env_opt != 0 {
            m.menv = g("environment_map_specular_contribution").filter(|v| *v >= 0.0).unwrap_or(0.0).clamp(0.0, 4.0);
            let et = sc.real("env_tint_color").filter(|v| v.iter().all(|x| x.is_finite())).unwrap_or([1.0; 4]);
            m.env_ctl = [et[0].max(0.0), et[1].max(0.0), et[2].max(0.0), coef];
            let off = g("env_roughness_offset").unwrap_or(0.5);
            m.env_lod = if m.env_opt == 2 { ((m.rough + (off - 0.5) * 2.0) * 4.0).clamp(0.0, 6.0) } else { ((off - 0.5) * 8.0).clamp(0.0, 6.0) };
            if m.env_opt == 1 {
                let et = native.model_shader_bitmap_by_usage(model, sh, "environment_map");
                if et != 0 && et != 0xFFFF_FFFF && native.find_bitmap(cache, et, 0).map_or(false, |i| i.bitmap_type == 2) { m.env_cube = et; }
            }
        }
    }
    m
}

/// Full shader_halogram `palettized_plasma` material, straight from the engine's
/// self_illumination_halogram.hlsl_include + overlays.hlsl_include:
///   index   = |noise_a(uv·xform_a + scroll_a·t) − noise_b(uv·xform_b + scroll_b·t)|
///   index   = saturate(index + (1 − alpha_mask·depth_fade) · alpha_modulation_factor)
///   illum   = palette(index, v_coordinate).rgb × self_illum_color × self_illum_intensity
///   overlay = overlay_map × overlay_detail_map × 4.59479 × overlay_tint × overlay_intensity   (additive_detail)
/// material_type none → no lighting: out = illum + overlay, blended additively. Scroll rates are the
/// PER-PARAMETER TranslationX/Y animation overlays (noise_a and noise_b scroll differently — with one
/// summed rate two samples of the same map cancel to a static field).
#[derive(Clone)]
struct FfExtra {
    noise_a: (Vec<u8>, u32, u32),
    noise_b: (Vec<u8>, u32, u32),
    palette: (Vec<u8>, u32, u32),
    overlay: Option<(Vec<u8>, u32, u32)>,
    /// [0]=noise_a xform, [1]=noise_b xform, [2]=[nb_scroll.xy, 1(lanes present)/2(change-colour: × instance
    /// change colour = halogram self_illum option 11), 2(ff flag)],
    /// [3]=[self_illum_color.rgb, intensity], [4]=[v_coordinate, alpha_const, amf, overlay mode (0 none,
    /// 1 additive_detail, 2 additive)],
    /// [5]=overlay_map xform, [6]=overlay_detail_map xform, [7]=[overlay_tint.rgb, overlay_intensity],
    /// [8]=[na_scroll.xy, overlay_scroll.xy], [9]=[depth_fade_range, overlay_detail mode (0 =
    /// the overlay map doubles as its own detail, 1 = `overlay_detail` bound in mat_tex, linear, 2 = bound,
    /// gamma-encoded; +4 = palette has no mips -> LOD 0), overlay_detail_scroll.xy] (xbump lane)
    lanes: [[f32; 4]; 10],
    /// [palette, overlay, noise_a, noise_b] gamma flags (1 = bitmap curve is gamma-encoded → decode in shader).
    gamma: [f32; 4],
    /// The AUTHORED alpha_mask_map texels (keep-alpha decode) + its UV xform. The engine
    /// samples `alpha_mask_map.a` per texel (index += (1 - a * depth_fade) * alpha_modulation_factor):
    /// Spire's dome mask (cov_forcefield_survival_mask, A 0..255) is the honeycomb cell pattern, so
    /// the mean-alpha stand-in in lanes[4].y erases the cells. Consumed by the BSP upload (MAT-30
    /// at_tex slot + mattex_xform, lanes[4].y = -1 flags it) and by the OBJECT
    /// upload the same way: the Forge grid's mask is its own 512x512 grid texture (lines a=1, cells
    /// a=0.05/0.16), so the mean (0.17) made every texel a dim cell and no line ever lit.
    alpha_mask: Option<((Vec<u8>, u32, u32), [f32; 4])>,
    /// The authored `overlay_detail_map` texels when it is a DIFFERENT bitmap from the
    /// overlay_map (additive_detail: overlay.rgb * overlay_detail.rgb * DETAIL_MULTIPLIER). fs_holo
    /// used to sample the overlay map at the detail xform for both factors, which is exact only when
    /// the two usages bind the same bitmap (the shield doors do; the Forge grid binds the 1x1 default
    /// alpha_grey50 = a flat 0.498 and got its own 10x-tiled grid lines instead). Bound in mat_tex
    /// (MAT-31 slot) on both the object and BSP uploads, flagged by lanes[9].y.
    overlay_detail: Option<(Vec<u8>, u32, u32)>,
    /// (mode 5 only): overlay_tint x overlay_intensity, the tint taken from the object-
    /// function-driven colour ramp at rest when the shader animates it (the drop_holo: `color` =
    /// per-ability hue index into red/blue/green/yellow), else the constants block. Rides the instance
    /// colour into fs_holo (lane [7] is the edge-fade record there).
    overlay_premul: [f32; 3],
    /// The overlay_tint colour animation record when an OBJECT FUNCTION drives it: (export
    /// sid, colour blob, mapping function) + overlay_intensity, so the upload can re-evaluate the tint
    /// per placed OBJECT (the seven armor abilities share one render model / decode but each exports its
    /// own `color` constant). None = the tint is static.
    overlay_ramp: Option<(u32, Vec<u8>, MapFn)>,
    overlay_intensity: f32,
    /// (modes 6 / 7 only): the edge_fade_simple record, ([edge_tint.rgb, power],
    /// [center_tint.rgb, 1]) — those modes keep si_ctl / xbump for the overlay lanes, so the record
    /// rides the (holo-unused) spec_rgb / fres_rgb instance lanes instead (set_spec_tints at upload).
    /// None = no edge fade (the category's `none` option).
    edge_fade: Option<([f32; 4], [f32; 4])>,
    /// (modes 6 / 7, overlay option 4 multiply_and_additive_detail): the `overlay_multiply_map`
    /// texels + UV xform + gamma flag (1 = sRGB-curve bitmap). The engine multiplies the self-illum colour by
    /// it BEFORE the additive overlay (overlays.hlsl_include): Sword Base's coastal_subsurface plane is masked
    /// by `ice_floating` this way. Rides the bump_detail_tex slot + mattex_xform; xctl.w = 1 + gamma flags it.
    overlay_multiply: Option<((Vec<u8>, u32, u32), [f32; 4], f32)>,
}

/// One animated parameter ("overlay") record of a render_method tag: (type, driven
/// real-constant name, period in seconds, mapping function). Type 5/6 = TranslationX/Y.
/// `input` = the record's input string id (@4; 0 = time -- the only input the lanes animate).
struct AnimParam { ty: i32, arg: String, period: f32, f: MapFn, colors: Option<([f32; 3], [f32; 3])>, input: u32, blob: Vec<u8> }

/// A PERIODIC animated parameter reduced to what fs_holo evaluates per frame:
/// value(t) = mix(lo, hi, g(frac(frac(t / period) * freq + phase))) with g = the periodic function
/// `kind` (function.hlsl evaluate_periodic_internal: 2/3 cosine, 4/5 diagonal wave, 6/7 slide; the
/// amplitude min/max of the record are folded into lo/hi). Colour records carry the c0 -> c3 ramp
/// ends in lo3/hi3. Only single-sub periodic records reduce; anything else stays static.
#[derive(Clone, Copy, Debug, PartialEq)]
struct AnimPeriodic { kind: i32, period: f32, freq: f32, phase: f32, lo: f32, hi: f32, lo3: [f32; 3], hi3: [f32; 3] }

/// Reduce the animated parameter of type `ty` (0 = value, 1 = colour) driving `param`
/// to its periodic spec (see AnimPeriodic). The Forge flashing lights animate self_illum_color (red ->
/// black) and self_illum_intensity (8 -> 2) with a 4 s cosine, both with input = time (period), so a
/// flashing light is OFF at t = 0 (the constants block snapshots exactly that: black, 2.0) and fully
/// lit at t = 2 s.
fn anim_periodic(params: &[AnimParam], param: &str, ty: i32) -> Option<AnimPeriodic> {
    let p = params.iter().find(|p| p.ty == ty && p.arg == param)?;
    if !(p.period.is_finite() && p.period > 1e-3) { return None; }
    let MapFn::Multi { subs, subs_b, lo, hi, .. } = &p.f else { return None };
    if subs.len() != 1 || !subs_b.is_empty() { return None; }
    let s = &subs[0];
    if s.ty != 3 { return None; }
    let kind = s.inn[0] as i32;
    if !matches!(kind, 2 | 3 | 4 | 5 | 6 | 7) { return None; }
    let (freq, phase, amin, amax) = (s.inn[1], s.inn[2], s.inn[3], s.inn[4]);
    if ![freq, phase, amin, amax].iter().all(|v| v.is_finite()) { return None; }
    let (lo3, hi3) = p.colors.unwrap_or(([0.0; 3], [1.0; 3]));
    let mixf = |a: f32, b: f32, t: f32| a + (b - a) * t;
    let mix3 = |a: [f32; 3], b: [f32; 3], t: f32| [mixf(a[0], b[0], t), mixf(a[1], b[1], t), mixf(a[2], b[2], t)];
    Some(AnimPeriodic {
        kind, period: p.period, freq, phase,
        lo: mixf(*lo, *hi, amin), hi: mixf(*lo, *hi, amax),
        lo3: mix3(lo3, hi3, amin), hi3: mix3(lo3, hi3, amax),
    })
}

/// The render_method's animated-parameter records with their mapping functions DECODED
/// (postprocess[0] +0x5C overlays, 0x24 B each: type @0, input/range sids @4/@8, period @0xC,
/// function dataref {size @0x10, addr @0x1C}; the +0x50 routing block {reg, 0x8f, overlay idx,
/// arg idx} names the driven rmt2 real constant, `arg_names` = the material's real-constant list
/// in order). Engine (c_function_definition::evaluate, reach_tag_test 0x1403F2C50 + 0x1403F27F0,
/// RE): value = range_min + (range_max - range_min) * f(input), input = frac(time /
/// period), the value is written straight into the xform's offset (transform_texcoord = uv * xy +
/// zw) -- NO sign flip. The DLL's OverlayWalker only baked a linear ramp from a header field that is
/// always 0 for scalars, so every TranslationX/Y read as +-1/period whatever the authored function:
/// the Forge grid's X noise scrolls are periodic slides with a 0..0 range (= static), its two Y
/// scrolls run in OPPOSITE directions (identity 0->1 vs linear 1->0 over 25 s).
fn shader_animated_params(native: &NativeDll, cache: CacheHandle, shader_tag: u32, arg_names: &[String]) -> Vec<AnimParam> {
    let mut out = Vec::new();
    if shader_tag == 0 || shader_tag == 0xFFFF_FFFF { return out; }
    let rd32 = |b: &[u8], o: usize| u32::from_le_bytes([b[o], b[o + 1], b[o + 2], b[o + 3]]);
    let rdf = |b: &[u8], o: usize| f32::from_le_bytes([b[o], b[o + 1], b[o + 2], b[o + 3]]);
    let Some(m) = native.tag_meta(cache, shader_tag, 0x38, 8) else { return out };
    let (cnt, ptr) = (rd32(&m, 0), rd32(&m, 4));
    if cnt == 0 { return out; }
    let Some(pp) = native.tag_ptr_bytes(cache, ptr, 0xAC) else { return out };
    let (rc, rp) = (rd32(&pp, 0x50), rd32(&pp, 0x54));
    let routing: Vec<[u8; 4]> = if rc > 0 && rc <= 4096 {
        native.tag_ptr_bytes(cache, rp, rc * 4).map(|b| b.chunks_exact(4).map(|c| [c[0], c[1], c[2], c[3]]).collect()).unwrap_or_default()
    } else { Vec::new() };
    let (oc, op) = (rd32(&pp, 0x5c), rd32(&pp, 0x60));
    if oc == 0 || oc > 256 { return out; }
    let Some(ob) = native.tag_ptr_bytes(cache, op, oc * 0x24) else { return out };
    for i in 0..oc as usize {
        let e = &ob[i * 0x24..i * 0x24 + 0x24];
        let ty = rd32(e, 0) as i32;
        let period = rdf(e, 0x0c);
        let (size, addr) = (rd32(e, 0x10), rd32(e, 0x1c));
        let blob = if size >= 0x0c && size <= 0x400 && addr != 0 { native.tag_ptr_bytes(cache, addr, size) } else { None };
        let f = blob.as_ref().and_then(|b| MapFn::decode(b)).unwrap_or(MapFn::Identity { lo: 0.0, hi: 1.0 });
        // Colour records keep their c0 -> c3 ramp ends (argb8 = the linear value x 255).
        let colors = blob.as_ref().and_then(|b| MapFn::decode_color_ramp(b));
        let arg_idx = routing.iter().find(|r| r[2] as usize == i).map(|r| r[3] as usize);
        let arg = arg_idx.and_then(|a| arg_names.get(a).cloned()).unwrap_or_else(|| format!("arg{}", arg_idx.map_or(-1, |a| a as i64)));
        let input = rd32(e, 4);
        let raw = blob.clone().unwrap_or_default();
        if ev("HMS_FFDIAG_RAW").is_ok() {
            // Raw animated-parameter record + function blob (print-only).
            let hex = |b: &[u8]| b.iter().map(|x| format!("{x:02x}")).collect::<Vec<_>>().join(" ");
            eprintln!("FFDIAG_RAW shader={shader_tag:#x} rec[{i}] arg={arg} type={ty} input={input:#x} range={:#x} period={period} fn_size={size} fn_addr={addr:#x} rec=[{}] blob=[{}]", rd32(e, 8), hex(e), blob.as_ref().map(|b| hex(b)).unwrap_or_default());
        }
        out.push(AnimParam { ty, arg, period, f, colors, input, blob: raw });
    }
    out
}

/// per-parameter UV scroll rate (uv/s) of the TranslationX/Y animated parameters driving
/// `param`, from the DECODED mapping functions: rate = (value(1-e) - value(0)) / ((1-e) * period),
/// sampled just short of the wrap so a periodic SLIDE (sawtooth frac(u), which the shipped shield
/// doors use: value(1) == value(0)) reads as the +-1/period ramp it is. Exact for the identity /
/// linear / slide ramps every shipped halogram uses; an oscillating function has no constant rate
/// and contributes ~0. No sign flip (see shader_animated_params).
fn anim_scroll_rate(params: &[AnimParam], param: &str) -> [f32; 2] {
    let mut scroll = [0.0f32, 0.0f32];
    const U1: f32 = 0.999;
    for p in params {
        if p.ty != 5 && p.ty != 6 { continue; }
        if p.arg != param { continue; }
        if !(p.period.is_finite() && p.period > 1e-3) { continue; }
        // A periodic function other than the slide (cosine / diagonal wave / noise / jitter / wander /
        // spark) oscillates or jitters in place: no constant drift, and its endpoints are not a slope.
        if let MapFn::Multi { subs, .. } = &p.f {
            if subs.iter().any(|s| s.ty == 3 && !matches!(s.inn[0] as i32, 6 | 7)) { continue; }
        }
        let rate = (p.f.eval(U1) - p.f.eval(0.0)) / (U1 * p.period);
        if !rate.is_finite() { continue; }
        if p.ty == 5 { scroll[0] += rate; } else { scroll[1] += rate; }
    }
    [scroll[0].clamp(-4.0, 4.0), scroll[1].clamp(-4.0, 4.0)]
}

#[cfg(test)]
mod grid_fx_tests {
    // The scroll rates the Forge grid / shield-door animated parameters must decode to,
    // built from the exact function blobs dumped out of forge_halo (HMS_PTRDUMP).
    use super::*;
    fn blob(hex: &str) -> Vec<u8> { hex.split_whitespace().map(|b| u8::from_str_radix(b, 16).unwrap()).collect() }
    const IDENTITY_0_1: &str = "00 34 00 00 00 00 00 00 00 00 80 3f 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00";
    const IDENTITY_0_NEG1: &str = "00 34 00 00 00 00 00 00 00 00 80 bf 00 00 00 00 00 00 00 00 6f 12 83 3a 6f 12 03 3b 00 00 00 00";
    const SLIDE_RANGE_0_0: &str = "03 34 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 6f 12 83 3a 6f 12 03 3b 14 00 00 00 06 cd cd cd 00 00 80 3f 00 00 00 00 00 00 00 00 00 00 80 3f";
    const LINEAR_1_TO_0: &str = "08 34 00 00 00 00 00 00 00 00 80 3f 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 14 00 00 00 01 00 00 00 04 00 00 3f ff ff 7f 7f 00 00 80 bf 00 00 80 3f";
    fn ap(ty: i32, arg: &str, period: f32, hex: &str) -> AnimParam { let b = blob(hex); AnimParam { ty, arg: arg.into(), period, f: MapFn::decode(&b).unwrap(), colors: MapFn::decode_color_ramp(&b), input: 0, blob: b.clone() } }

    #[test]
    fn grid_noise_scrolls_are_counter_running_in_v_only() {
        // ff_grid_object_depth: noise_a Y identity 0->1 / 25 s, X periodic slide with a 0..0 range;
        // noise_b Y linear 1->0 / 25 s, X the same static slide.
        let params = vec![
            ap(6, "noise_map_a", 25.0, IDENTITY_0_1), ap(5, "noise_map_a", 5.0, SLIDE_RANGE_0_0),
            ap(6, "noise_map_b", 25.0, LINEAR_1_TO_0), ap(5, "noise_map_b", 5.0, SLIDE_RANGE_0_0),
        ];
        let a = anim_scroll_rate(&params, "noise_map_a");
        let b = anim_scroll_rate(&params, "noise_map_b");
        assert!((a[0]).abs() < 1e-6 && (a[1] - 0.04).abs() < 1e-4, "noise_a {a:?}");
        assert!((b[0]).abs() < 1e-6 && (b[1] + 0.04).abs() < 1e-4, "noise_b {b:?}");
        assert_eq!(anim_scroll_rate(&params, "overlay_map"), [0.0, 0.0]);
    }

    #[test]
    fn waterfall_identity_to_minus_one_flows_negative() {
        // forge_halo_waterfall_lower_small: TranslationY identity 0 -> -1 over 30 s = -1/30 uv/s
        // (the sign HMS verified visually: the sheet flows DOWN). No extra negation.
        let params = vec![ap(6, "base_map", 30.0, IDENTITY_0_NEG1)];
        let r = anim_scroll_rate(&params, "base_map");
        assert!((r[1] + 1.0 / 30.0).abs() < 1e-4, "{r:?}");
    }

    #[test]
    fn periodic_slide_reads_as_a_ramp_despite_the_wrap() {
        // two-way door sh1 noise_map_a X: slide (frac) with range 0..1 over 2 s = +0.5 uv/s.
        let slide_0_1 = "03 34 00 00 00 00 00 00 00 00 80 3f 00 00 00 00 00 00 00 00 6f 12 83 3a 6f 12 03 3b 14 00 00 00 06 cd cd cd 00 00 80 3f 00 00 00 00 00 00 00 00 00 00 80 3f";
        let f = MapFn::decode(&blob(slide_0_1)).unwrap();
        assert!((f.eval(0.5) - 0.5).abs() < 1e-5 && f.eval(1.0).abs() < 1e-5, "slide wraps at 1: {f:?}");
        let params = vec![ap(5, "noise_map_a", 2.0, slide_0_1)];
        let r = anim_scroll_rate(&params, "noise_map_a");
        assert!((r[0] - 0.5).abs() < 1e-3, "{r:?}");
    }

    // ff_light_flash_red (shader 0x1dd0) animated parameters, exact blobs from forge_halo
    // (HMS_PTRDUMP 0x5f42d99f / 0x5f42d9ac): self_illum_color = periodic COSINE colour ramp
    // red (1, .204, .055) -> black, period 4 s; self_illum_intensity = periodic cosine 8 -> 2, period 4 s.
    const FLASH_COLOR: &str = "03 34 02 00 0e 34 ff 00 00 00 00 00 00 00 00 00 00 00 00 ff 6f 12 83 3a 6f 12 03 3b 14 00 00 00 02 cd cd cd 00 00 80 3f 00 00 00 00 00 00 00 00 00 00 80 3f";
    const FLASH_INTEN: &str = "03 34 00 00 00 00 00 41 00 00 00 40 00 00 00 00 00 00 00 00 6f 12 83 3a 6f 12 03 3b 14 00 00 00 02 00 00 00 00 00 80 3f 00 00 00 00 00 00 00 00 00 00 80 3f";

    #[test]
    fn flash_light_blink_reduces_to_a_cosine_ramp() {
        let params = vec![ap(1, "self_illum_color", 4.0, FLASH_COLOR), ap(0, "self_illum_intensity", 4.0, FLASH_INTEN)];
        let c = anim_periodic(&params, "self_illum_color", 1).expect("colour record");
        let i = anim_periodic(&params, "self_illum_intensity", 0).expect("intensity record");
        assert_eq!(c.kind, 2); assert_eq!(i.kind, 2);
        assert!((c.period - 4.0).abs() < 1e-6 && (i.period - 4.0).abs() < 1e-6);
        assert!((c.freq - 1.0).abs() < 1e-6 && c.phase.abs() < 1e-6);
        // f = 0 end = the lit state (red x 8), f = 1 end = off (black x 2): the constants block of the
        // shader (black, 2.0) is the t = 0 snapshot, where the cosine sits at f = 1.
        assert!((c.lo3[0] - 1.0).abs() < 1e-3 && (c.lo3[1] - 0.204).abs() < 2e-3 && (c.lo3[2] - 0.055).abs() < 2e-3, "{c:?}");
        assert!(c.hi3.iter().all(|v| v.abs() < 1e-6), "{c:?}");
        assert!((i.lo - 8.0).abs() < 1e-6 && (i.hi - 2.0).abs() < 1e-6, "{i:?}");
        // a plain scroll record (slide) is not a colour/intensity animation
        assert!(anim_periodic(&params, "noise_map_a", 5).is_none());
        // and the scroll reader ignores the cosine records (no constant drift)
        assert_eq!(anim_scroll_rate(&params, "self_illum_color"), [0.0, 0.0]);
    }

    #[test]
    fn static_lights_have_no_periodic_record() {
        // ff_light_red authors no animated parameters at all: lanes fall back to the constants.
        let params: Vec<AnimParam> = Vec::new();
        assert!(anim_periodic(&params, "self_illum_color", 1).is_none());
        assert!(anim_periodic(&params, "self_illum_intensity", 0).is_none());
    }
}

/// Does this model shader animate its self_illum colour / intensity from an OBJECT
/// FUNCTION (animated-parameter input sid != 0 = not time)? The engine lanes only evaluate time-driven
/// (periodic) records, so a from_diffuse halogram whose glow is switched by an object function (the
/// energy sword's blade flare, the portable shield rim, the armor-lock pack parts: constants 0, lit by
/// `sword_on`-style functions) is left on its previous rendering rather than pinned to the constants.
fn halogram_function_driven(native: &NativeDll, cache: CacheHandle, model: hms_native::ModelHandle, sh: i32) -> bool {
    let Some(sc) = native.model_shader_constants(model, sh) else { return false };
    let names: Vec<String> = sc.dump_args().into_iter().map(|a| a.1).collect();
    let shader_tag = native.model_shader_tag(model, sh);
    let params = shader_animated_params(native, cache, if shader_tag >= 0 { shader_tag as u32 } else { 0 }, &names);
    params.iter().any(|p| p.input != 0 && matches!(p.ty, 0 | 1) && (p.arg == "self_illum_intensity" || p.arg == "self_illum_color"))
}

/// The RESTING value of an object's exported function `export_sid` (obje +0xEC functions
/// block, 0x40 B each: flags @0, import name sid @4, export name sid @8, default mapping function
/// dataref {size @0x18, addr @0x24}): value = default_function(import). Only the constant imports are
/// evaluable offline -- `one` (sid 0x221) = 1.0 and `zero` (0x222) = 0.0; a game-state import
/// (blade_activate, energy, fx_camo, ...) returns None. The armor-ability pickups export `color` =
/// constant(one) = a per-ability 0..1 hue index (active_camouflage 0.45) that the drop_holo's
/// overlay_tint 4-colour ramp is driven by.
fn object_function_rest_value(native: &NativeDll, cache: CacheHandle, obj_tag: u32, export_sid: u32) -> Option<f32> {
    if obj_tag == 0 || obj_tag == 0xFFFF_FFFF || export_sid == 0 { return None; }
    let rd32 = |b: &[u8], o: usize| u32::from_le_bytes([b[o], b[o + 1], b[o + 2], b[o + 3]]);
    let h = native.tag_meta(cache, obj_tag, 0xEC, 8)?;
    let (cnt, ptr) = (rd32(&h, 0), rd32(&h, 4));
    if cnt == 0 || cnt > 64 { return None; }
    let fb = native.tag_ptr_bytes(cache, ptr, cnt * 0x40)?;
    for i in 0..cnt as usize {
        let e = &fb[i * 0x40..i * 0x40 + 0x40];
        if rd32(e, 8) != export_sid { continue; }
        let import = match rd32(e, 4) { 0x221 => 1.0f32, 0x222 => 0.0, _ => return None };
        let (size, addr) = (rd32(e, 0x18), rd32(e, 0x24));
        let f = if size >= 0x0c && size <= 0x400 && addr != 0 { native.tag_ptr_bytes(cache, addr, size).and_then(|b| MapFn::decode(&b)) } else { None };
        return Some(f.map_or(import, |f| f.eval(import)));
    }
    None
}

fn decode_forcefield_extra(native: &NativeDll, cache: CacheHandle, bmp: Option<&BitmapCache>, model: hms_native::ModelHandle, sh: i32, tname: &str, obj_tag: u32) -> Option<FfExtra> {
    let sc = native.model_shader_constants(model, sh)?;
    let usage_tag = |u: &str| native.model_shader_bitmap_by_usage(model, sh, u);
    // Scroll rates from the decoded mapping functions of the shader tag's animated parameters.
    let names: Vec<String> = sc.dump_args().into_iter().map(|a| a.1).collect();
    let shader_tag = native.model_shader_tag(model, sh);
    let params = shader_animated_params(native, cache, if shader_tag >= 0 { shader_tag as u32 } else { 0 }, &names);
    let scroll = |p: &str| anim_scroll_rate(&params, p);
    let periodic = |p: &str, ty: i32| anim_periodic(&params, p, ty);
    // HMS_FFDIAG prints the raw animated-parameter records + constants for EVERY object
    // halogram (the single-material path had no dump; the Forge grid is single-material).
    if ev("HMS_FFDIAG").is_ok() {
        eprintln!("FFDIAG object sh={sh} shader={shader_tag:#x} tmpl='{tname}'");
        for p in &params { eprintln!("FFDIAG   anim type={} arg={} input={:#x} period={:.3} f(0)={:.4} f(.25)={:.4} f(.5)={:.4} f(.75)={:.4} f(1)={:.4} -> {:?}", p.ty, p.arg, p.input, p.period, p.f.eval(0.0), p.f.eval(0.25), p.f.eval(0.5), p.f.eval(0.75), p.f.eval(1.0), p.f); }
        for (i, n, r, sv) in sc.dump_args() { eprintln!("FFDIAG   arg[{i}] {n} real={r:?} scalar={sv}"); }
        for u in ["base_map", "noise_map_a", "noise_map_b", "alpha_mask_map", "palette", "warp_map", "overlay_map", "overlay_detail_map", "detail_map"] {
            let b = usage_tag(u);
            if b != 0 && b != 0xFFFF_FFFF { eprintln!("FFDIAG   bitmap {u} = {b:#x} '{}'", native.tag_name(cache, b).unwrap_or_default()); }
        }
    }
    // A COLOUR animated parameter driven by an object function that is constant at rest
    // (input sid = the function's export name) evaluates to its ramp colour at that value.
    let color_anim = |p: &str| -> Option<(u32, Vec<u8>, MapFn)> {
        let r = params.iter().find(|r| r.ty == 1 && r.arg == p && r.input != 0 && r.blob.len() >= 0x14 && r.blob[2] != 0)?;
        Some((r.input, r.blob.clone(), r.f.clone()))
    };
    let usage_sampler = |u: &str| native.model_shader_sampler_by_usage(model, sh, u);
    decode_forcefield_extra_core(native, cache, bmp, &usage_tag, &usage_sampler, &sc, &scroll, &periodic, &color_anim, obj_tag, &format!("sh{sh}"), tname)
}

/// The same engine material for a BSP (structure/instance) material — Spire's
/// `cov_shield_dome_*` shells are sbsp materials on the identical `halogram_templates\_2_10_1_0_0_2_1`
/// template as the Forge shield-door objects, so they take the same lane. Bitmaps/constants come
/// from the sbsp material record; the per-parameter noise scroll from the render_method tag's
/// TranslationX/Y overlays (arg names = the material's real-constant list, in order).
fn decode_forcefield_extra_bsp(native: &NativeDll, cache: CacheHandle, bsp: BspHandle, mat: i32, shader_tag: u32, tname: &str) -> Option<FfExtra> {
    let sc = native.bsp_material_shader_constants(bsp, mat)?;
    let names: Vec<String> = sc.dump_args().into_iter().map(|a| a.1).collect();
    let usage_tag = |u: &str| native.bsp_material_bitmap_by_usage(bsp, mat, u);
    // Scroll rates from the decoded mapping functions (same reader as the object path).
    let params = shader_animated_params(native, cache, shader_tag, &names);
    let scroll = |p: &str| anim_scroll_rate(&params, p);
    let periodic = |p: &str, ty: i32| anim_periodic(&params, p, ty);
    if ev("HMS_FFDIAG").is_ok() {
        eprintln!("FFDIAG BSP mat={mat} shader={shader_tag:#x} tmpl='{tname}'");
        for p in &params { eprintln!("FFDIAG   anim type={} arg={} period={:.3} f(0)={:.4} f(.5)={:.4} f(1)={:.4}", p.ty, p.arg, p.period, p.f.eval(0.0), p.f.eval(0.5), p.f.eval(1.0)); }
    }
    let color_anim = |_: &str| -> Option<(u32, Vec<u8>, MapFn)> { None }; // BSP materials have no object functions
    let usage_sampler = |u: &str| native.bsp_material_sampler_by_usage(bsp, mat, u);
    decode_forcefield_extra_core(native, cache, None, &usage_tag, &usage_sampler, &sc, &scroll, &periodic, &color_anim, 0, &format!("mat{mat}"), tname)
}

/// Source-agnostic body of the shield/forcefield material decode (object render-model shaders and
/// BSP materials differ only in how a usage resolves to a bitmap tag, where the constants come
/// from and how the scroll overlays are looked up). `label` names the HMS_FF_DUMP files.
fn decode_forcefield_extra_core(native: &NativeDll, cache: CacheHandle, bmp: Option<&BitmapCache>, usage_tag: &dyn Fn(&str) -> u32, usage_sampler: &dyn Fn(&str) -> u32, sc: &hms_native::ZhShaderConstants, scroll: &dyn Fn(&str) -> [f32; 2], periodic: &dyn Fn(&str, i32) -> Option<AnimPeriodic>, color_anim: &dyn Fn(&str) -> Option<(u32, Vec<u8>, MapFn)>, obj_tag: u32, label: &str, tname: &str) -> Option<FfExtra> {
    let bm = |u: &str| {
        let t = usage_tag(u);
        if t != 0 && t != 0xFFFF_FFFF { cached_bitmap(bmp, native, cache, t) } else { None }
    };
    // The halogram self_illumination option decides the lane MODE fs_holo evaluates
    // (lanes[2].z): 1 = palettized_plasma (10 / 12), 2 = palettized_plasma_change_color (11), 3 = simple
    // (1: Forge lights, killball core, covenant weapon glows), 4 = plasma (3: powerup fields, phantom).
    // Modes 3/4 have no palette; the noise_a slot carries the self_illum_map for mode 3.
    let digits0 = rm_template_digits(tname);
    // 5 = from_diffuse (4, `calc_self_illumination_from_albedo_ps`: self_illum = albedo x
    // self_illum_color x self_illum_intensity, albedo = saturate(base x detail x DETAIL_MULTIPLIER x change
    // colours) -- the armor-ability pickup's drop_holo field, halogram _3_4_1_0_2_1_1). base_map rides the
    // noise_a slot, detail_map the noise_b slot.
    // 6 = self_illumination OFF (0: the material is ONLY its overlay + edge fade — Condemned's
    // ship-hologram projector lamp, halogram _0_0_1_0_0_4_1, drew as an opaque white slab through the
    // solid-marker stand-in), 7 = multilayer_additive (8: the parallax-layered self_illum_map — the
    // cpu_readouts monitors / the reactor core ring, halogram _0_8_1_0_x_2_x — rode the generic fs_holo
    // stand-in: rim + vignette + pulse, no overlay, no edge fade).
    let mode = match digits0.get(1).copied().unwrap_or(0) { 10 | 12 => 1.0f32, 11 => 2.0, 1 => 3.0, 3 => 4.0, 4 => 5.0, 0 => 6.0, 8 => 7.0, _ => return None };
    let white1 = || (vec![255u8, 255, 255, 255], 1u32, 1u32);
    let (noise_a, noise_b, palette) = if mode > 6.5 {
        // Multilayer: the self_illum_map rides the noise_a slot (sampled N times along the
        // tangent-space view offset in fs_holo); noise_b / palette unused.
        (bm("self_illum_map")?, white1(), white1())
    } else if mode > 5.5 {
        // self-illum off: no self-illum texture at all (white stand-ins keep the slots bound).
        (white1(), white1(), white1())
    } else if mode > 4.5 {
        // engine default detail_map = default_detail (sRGB 0.5 -> x DETAIL_MULTIPLIER = 1.0): gray50 stand-in.
        (bm("base_map")?, bm("detail_map").unwrap_or_else(|| (vec![128u8, 128, 128, 255], 1u32, 1u32)), white1())
    } else if mode > 2.5 {
        let na = if mode > 3.5 { bm("noise_map_a")? } else { bm("self_illum_map").unwrap_or_else(white1) };
        let nb = if mode > 3.5 { bm("noise_map_b").unwrap_or_else(|| na.clone()) } else { na.clone() };
        (na, nb, white1())
    } else {
        let na = bm("noise_map_a")?;
        let nb = bm("noise_map_b").unwrap_or_else(|| na.clone());
        (na, nb, bm("palette")?)
    };
    let xf = |n: &str| sc.real(n).filter(|v| v.iter().all(|x| x.is_finite())).unwrap_or([1.0, 1.0, 0.0, 0.0]);
    let sca = |n: &str, d: f32| sc.real(n).map(|v| v[0]).or_else(|| sc.scalar(n)).filter(|v| v.is_finite()).unwrap_or(d);
    // alpha_mask_map: shipped shields use the flat default bitmaps (alpha_white / alpha_grey50) —
    // the mean alpha reproduces them exactly and approximates any authored mask.
    let alpha_const = bm("alpha_mask_map").map(|(px, _, _)| {
        let n = (px.len() / 4).max(1);
        px.chunks_exact(4).map(|p| p[3] as f32 / 255.0).sum::<f32>() / n as f32
    }).unwrap_or(1.0);
    // Keep the authored mask texels too (keep-alpha decode so the.a channel the engine
    // reads survives). 1x1 default bitmaps (alpha_white / alpha_grey50) are exactly their mean, so
    // they are not kept; a real mask (w*h > 1) is.
    let alpha_mask = {
        let t = usage_tag("alpha_mask_map");
        if t != 0 && t != 0xFFFF_FFFF {
            native.decode_bitmap_keep_alpha(cache, t, 0, 0).filter(|b| b.1 * b.2 > 1).map(|b| (b, xf("alpha_mask_map")))
        } else { None }
    };
    // halogram template digits: albedo, self_illumination, blend_mode, misc, warp, OVERLAY, edge_fade
    // (order verified from halogram.render_method_definition's category list).
    let digits = rm_template_digits(tname);
    let si_opt = digits.get(1).copied().unwrap_or(0);
    let overlay_opt = digits.get(5).copied().unwrap_or(0);
    // overlays.hlsl_include: 1 = additive (overlay_map.rgb × overlay_tint × overlay_intensity — no
    // detail map, no DETAIL_MULTIPLIER), 2 = additive_detail, 4 = multiply_and_additive_detail (the
    // multiply part is dropped). Lane [4].w carries the mode (1 = additive_detail, 2 = additive).
    // Modes 3/4 carry their edge-fade / animation records in the overlay lanes, so the
    // overlay stays off there (the one shipped case, cov_portable_shield _0_3_1_0_0_2_1, is open).
    // Mode 5 carries the ADDITIVE overlay too (drop_holo: overlay_map `..drop_holo_pixels`, tint
    // red x 0.12, scrolled); its tint x intensity rides the instance colour (ff_color) since lane [7] is
    // the edge-fade record there. additive_detail is not routed for mode 5 (no shipped case).
    // Modes 6 / 7 carry the full overlay lane set (additive / additive_detail /
    // multiply_and_additive_detail) exactly like the palettized modes; their edge-fade record moves to
    // the spec_rgb / fres_rgb instance lanes (FfExtra::edge_fade) so the overlay lanes stay free.
    let overlay = if ((mode < 2.5 || mode > 5.5) && matches!(overlay_opt, 1 | 2 | 4)) || (mode > 4.5 && mode < 5.5 && overlay_opt == 1) { bm("overlay_map") } else { None };
    let overlay_mode = match (overlay.is_some(), overlay_opt) { (false, _) => 0.0, (true, 1) => 2.0, _ => 1.0 };
    // self_illumination option 11 = palettized_plasma_change_color (same pixel function as
    // 10; its option tag `screen_options\illum_palettized_plasma_change_color` binds self_illum_color
    // from the "change color primary" extern = the object's PRIMARY change colour). No self_illum_color
    // constant is authored (→ white here); the per-instance change colour is multiplied in fs_holo.
    let change_color = si_opt == 11;
    let color = sc.real("self_illum_color").unwrap_or([1.0, 1.0, 1.0, 1.0]);
    let inten = sca("self_illum_intensity", 1.0).max(0.0);
    let otint = sc.real("overlay_tint").unwrap_or([1.0, 1.0, 1.0, 1.0]);
    // The resting ramp colour when an object function drives the tint (see FfExtra::overlay_premul).
    let overlay_ramp = if mode > 4.5 { color_anim("overlay_tint") } else { None };
    let overlay_intensity = sca("overlay_intensity", 1.0);
    let otint_rest = overlay_ramp.as_ref().and_then(|(sid, blob, f)| object_function_rest_value(native, cache, obj_tag, *sid).and_then(|v| MapFn::decode_color_at(blob, f.eval(v))));
    let overlay_premul = {
        let t = otint_rest.unwrap_or([otint[0], otint[1], otint[2]]);
        [t[0] * overlay_intensity, t[1] * overlay_intensity, t[2] * overlay_intensity]
    };
    if mode > 4.5 && ev("HMS_FFDIAG").is_ok() { eprintln!("FFDIAG   {label} overlay_tint constants={:?} at_rest={otint_rest:?} x intensity {} -> {overlay_premul:?}", &otint[..3], sca("overlay_intensity", 1.0)); }
    let na_s = scroll("noise_map_a");
    let nb_s = scroll("noise_map_b");
    let ov_s = scroll("overlay_map");
    let od_s = scroll("overlay_detail_map");
    // additive_detail's second factor. Kept only when it differs from the overlay map (same
    // bitmap = byte-identical to the legacy "overlay map at the detail xform" sampling).
    let gflag = |u: &str| {
        let t = usage_tag(u);
        if t == 0 || t == 0xFFFF_FFFF { 0.0 } else if curve_is_linear(native, cache, t) { 0.0 } else { 1.0 }
    };
    let overlay_detail = if overlay.is_some() && matches!(overlay_opt, 2 | 4) && usage_tag("overlay_detail_map") != usage_tag("overlay_map") { bm("overlay_detail_map") } else { None };
    // +4 flags a palette bitmap authored WITHOUT mips (mip_count 0 -> the engine samples its
    // base level only; the grid's palette_simple_gradient_b1) so fs_holo takes LOD 0 for it.
    let pal_nomip = mode < 2.5 && native.find_bitmap(cache, usage_tag("palette"), 0).map_or(false, |b| b.mip_count == 0);
    // Od mode 3 = additive_detail / multiply_and_additive_detail with NO overlay_detail_map
    // bound at all (null tag ref: Condemned's projector lamp, cpu_readouts): fs_holo uses the engine's
    // default_detail (x DETAIL_MULTIPLIER = 1) instead of re-sampling the overlay map at the detail xform.
    let od_null = overlay.is_some() && matches!(overlay_opt, 2 | 4) && { let t = usage_tag("overlay_detail_map"); t == 0 || t == 0xFFFF_FFFF };
    let od_mode = if overlay_detail.is_some() { 1.0 + gflag("overlay_detail_map") } else if od_null { 3.0 } else { 0.0 } + if pal_nomip { 4.0 } else { 0.0 };
    // edge_fade (halogram category 6, option 1 `edge_fade_simple`; RE'd from the compiled
    // _2_1_1_0_0_0_1 / _0_3_1_0_0_0_1 pixel shaders, HREK ships no HLSL for it): the additive output is
    // multiplied by lerp(edge_fade_edge_tint, edge_fade_center_tint, pow(|dot(N, V)|, edge_fade_power)),
    // N = interpolated vertex normal, V = normalized fragment-to-camera. The Forge lights author
    // black -> white with power 4 (a soft orb: full colour facing the camera, fading to nothing at the
    // silhouette); the powerup fields (0,0,0.016) -> (0.59,0.85,1.0) power 3. Modes 3/4 only: the
    // palettized lanes ([7] overlay tint, [9] depth fade) are occupied, so a palettized halogram that
    // authors edge_fade (the killball's _2_10_1_0_0_0_1 parts) still renders without it (open).
    let edge_authored = digits.get(6).copied().unwrap_or(0) == 1;
    let edge_on = mode > 2.5 && mode < 5.5 && edge_authored;
    let etint = sc.real("edge_fade_edge_tint").unwrap_or([0.0, 0.0, 0.0, 1.0]);
    let ctint = sc.real("edge_fade_center_tint").unwrap_or([1.0, 1.0, 1.0, 1.0]);
    let epow = sca("edge_fade_power", 1.0);
    let edge_lane = if edge_on { [etint[0], etint[1], etint[2], epow] } else { [0.0; 4] };
    let center_lane = if edge_on { [ctint[0], ctint[1], ctint[2], 1.0] } else { [0.0; 4] };
    // Modes 6 / 7 keep the same record on the spec_rgb / fres_rgb lanes (fres_rgb.w = 1 flags it).
    let edge_fade = if mode > 5.5 && edge_authored { Some(([etint[0], etint[1], etint[2], epow], [ctint[0], ctint[1], ctint[2], 1.0])) } else { None };
    // Overlay option 4's multiply map (modes 6 / 7 only; a null ref = white, i.e. no multiply).
    let overlay_multiply = if mode > 5.5 && overlay_opt == 4 { bm("overlay_multiply_map").map(|b| (b, xf("overlay_multiply_map"), gflag("overlay_multiply_map"))) } else { None };
    let lanes = if mode > 5.5 {
        // Modes 6 (self-illum off) / 7 (multilayer_additive, self_illumination_halogram.hlsl_include
        // calc_self_illumination_multilayer_ps): the overlay lanes are the palettized layout ([4].w overlay mode,
        // [5]/[6] overlay / overlay_detail xforms, [7] tint + intensity, [8].zw / [9].zw scrolls, [9].y detail
        // mode); the edge fade rides FfExtra::edge_fade. Mode 7: [0] = self_illum_map xform (+ [8].xy scroll),
        // [1] = [layer_depth, layer_contrast, texcoord_aspect_ratio, depth_darken], [3] = [self_illum_color.rgb,
        // intensity at f = 0], [9].x = intensity at f = 1, [2].xy = [period, freq] and [4].yz = [phase, kind] of
        // the intensity's periodic record (kind 0 = static), [4].x = layers_of_4. Mode 6 carries no self-illum.
        let pi = if mode > 6.5 { periodic("self_illum_intensity", 0) } else { None };
        let i0 = pi.map_or(inten, |p| p.lo.max(0.0));
        let i1 = pi.map_or(inten, |p| p.hi.max(0.0));
        let rec = pi.map_or([0.0; 4], |p| [p.period, p.freq, p.phase, p.kind as f32]);
        let ml = if mode > 6.5 { [sca("layer_depth", 0.0), sca("layer_contrast", 1.0), sca("texcoord_aspect_ratio", 1.0), sca("depth_darken", 1.0)] } else { [0.0; 4] };
        // The engine binds the self_illum_map with the shader's authored sampler address mode
        // (texture-constant byte: u low nibble, v high; 1 = clamp). Sword Base's coastal_subsurface (black-
        // bordered blob, layer offsets up to 0.3 UV) is CLAMPED there -- with repeat addressing the parallax
        // samples wrap into the bright centre at the quad's edges = a hard bright rectangle. [4].x = layers_of_4
        // + 8 (clamp u) + 16 (clamp v).
        let smp = if mode > 6.5 { usage_sampler("self_illum_map") } else { 0xFF };
        let clamp_flags = if smp == 0xFF { 0.0 } else { (if smp & 0xF == 1 { 8.0 } else { 0.0 }) + (if (smp >> 4) & 0xF == 1 { 16.0 } else { 0.0 }) };
        let layers = if mode > 6.5 { sca("layers_of_4", 1.0).max(1.0) + clamp_flags } else { 0.0 };
        let si_s = if mode > 6.5 { scroll("self_illum_map") } else { [0.0, 0.0] };
        [
            if mode > 6.5 { xf("self_illum_map") } else { [1.0, 1.0, 0.0, 0.0] },
            ml,
            [rec[0], rec[1], mode, 2.0],
            if mode > 6.5 { [color[0], color[1], color[2], i0] } else { [0.0; 4] },
            [layers, rec[2], rec[3], overlay_mode],
            xf("overlay_map"),
            xf("overlay_detail_map"),
            [otint[0], otint[1], otint[2], overlay_intensity],
            [si_s[0], si_s[1], ov_s[0], ov_s[1]],
            [i1, od_mode, od_s[0], od_s[1]],
        ]
    } else if mode > 4.5 {
        // from_albedo (verified against the compiled _3_4_1_0_2_1_1 pixel shader, forge_halo
        // DXBC @0x10588358): out = (saturate(base(uv') x detail(uv') x 4.59479 x change_color) x
        // self_illum_color x self_illum_intensity x ILLUM_SCALE + overlay(uv') x overlay_tint x
        // overlay_intensity) x lerp(edge_tint, center_tint, |N.V|^power) x fog x g_exposure. The
        // intensity may be a PERIODIC animated parameter (the drop_holo pulses 0.25..1 x 1.4706 on a 2 s
        // cosine): [3].w = f=0 value, [4].x = f=1 value, [6] = its record (kind 0 = static). The
        // parallax_simple warp (height_map, height_scale 0.1) is NOT applied (a <=0.05 uv wobble).
        let pi = periodic("self_illum_intensity", 0);
        let i0 = pi.map_or(inten, |p| p.lo.max(0.0));
        let i1 = pi.map_or(inten, |p| p.hi.max(0.0));
        let rec = |p: Option<AnimPeriodic>| p.map_or([0.0; 4], |p| [p.period, p.freq, p.phase, p.kind as f32]);
        [
            xf("base_map"),
            xf("detail_map"),
            [scroll("detail_map")[0], scroll("detail_map")[1], mode, 2.0],
            [color[0], color[1], color[2], i0],
            [i1, 1.0, 0.0, overlay_mode],
            xf("overlay_map"),
            rec(pi),
            edge_lane,
            [scroll("base_map")[0], scroll("base_map")[1], ov_s[0], ov_s[1]],
            center_lane,
        ]
    } else if mode > 3.5 {
        // plasma (self_illumination.hlsl_include calc_self_illumination_plasma_ps): diff = max(0, 1 -
        // |noise_a.r - noise_b.r|); medium = diff^thinness_medium, sharp = diff^thinness_sharp, wide =
        // diff^thinness_wide; wide -= medium; medium -= sharp; colour = sum(color_x.rgb * color_x.a *
        // x); out = colour * alpha_mask.a * self_illum_intensity. The three premultiplied colours
        // (x intensity) ride [3]/[5]/[6] with their thinness in .w; edge fade in [7]/[9].
        let cm = sc.real("color_medium").unwrap_or([0.0; 4]);
        let cs = sc.real("color_sharp").unwrap_or([0.0; 4]);
        let cw = sc.real("color_wide").unwrap_or([0.0; 4]);
        let pre = |c: [f32; 4], th: &str| [c[0] * c[3] * inten, c[1] * c[3] * inten, c[2] * c[3] * inten, sca(th, 1.0)];
        [
            xf("noise_map_a"),
            xf("noise_map_b"),
            [nb_s[0], nb_s[1], mode, 2.0],
            pre(cm, "thinness_medium"),
            [0.0, alpha_const, 0.0, 0.0],
            pre(cs, "thinness_sharp"),
            pre(cw, "thinness_wide"),
            edge_lane,
            [na_s[0], na_s[1], 0.0, 0.0],
            center_lane,
        ]
    } else if mode > 2.5 {
        // simple (calc_self_illumination_simple_ps): self_illum_map(uv * xform) * self_illum_color *
        // self_illum_intensity. [3] = colour + intensity at f = 0 (the authored constants when static),
        // [1] = the same at f = 1, [5]/[6] = the periodic records (period, freq, phase, kind; kind 0 =
        // static) of the colour / intensity animations -- the flashing lights' 4 s cosine blink.
        let pc = periodic("self_illum_color", 1);
        let pi = periodic("self_illum_intensity", 0);
        let c0 = pc.map_or([color[0], color[1], color[2]], |p| p.lo3);
        let c1 = pc.map_or([color[0], color[1], color[2]], |p| p.hi3);
        let i0 = pi.map_or(inten, |p| p.lo.max(0.0));
        let i1 = pi.map_or(inten, |p| p.hi.max(0.0));
        let rec = |p: Option<AnimPeriodic>| p.map_or([0.0; 4], |p| [p.period, p.freq, p.phase, p.kind as f32]);
        [
            xf("self_illum_map"),
            [c1[0], c1[1], c1[2], i1],
            [0.0, 0.0, mode, 2.0],
            [c0[0], c0[1], c0[2], i0],
            [0.0, 1.0, 0.0, 0.0],
            rec(pc),
            rec(pi),
            edge_lane,
            [scroll("self_illum_map")[0], scroll("self_illum_map")[1], 0.0, 0.0],
            center_lane,
        ]
    } else { [
        xf("noise_map_a"),
        xf("noise_map_b"),
        [nb_s[0], nb_s[1], if change_color { 2.0 } else { 1.0 }, 2.0],
        // Option 11 binds self_illum_color from the change-colour extern, so [3].rgb is
        // never a colour there. Carry the self_illum_intensity PERIODIC record instead — [lo, hi,
        // period, kind] (freq 1 / phase 0, which is what every shipped marker authors; anything else
        // keeps the static constant). The Forge spawn/respawn markers pulse 0.25 -> 1.0 on a 2 s
        // diagonal wave: the constants block snapshots the trough (0.25), so the TEAM-coloured term
        // read at a quarter of its mean and the fixed blue overlay_tint out-glowed it (purple team
        // rendered blue, red rendered mauve). fs_holo evaluates it per frame like mode 3.
        if change_color {
            match periodic("self_illum_intensity", 0) {
                Some(p) if (p.freq - 1.0).abs() < 1e-3 && p.phase.abs() < 1e-3 => [p.lo.max(0.0), p.hi.max(0.0), p.period, p.kind as f32],
                _ => [inten, inten, 0.0, 0.0],
            }
        } else {
            [color[0], color[1], color[2], inten]
        },
        [sca("v_coordinate", 0.5), alpha_const, sca("alpha_modulation_factor", 0.0), overlay_mode],
        xf("overlay_map"),
        xf("overlay_detail_map"),
        [otint[0], otint[1], otint[2], sca("overlay_intensity", 1.0)],
        [na_s[0], na_s[1], ov_s[0], ov_s[1]],
        [sca("depth_fade_range", 0.0).max(0.0), od_mode, od_s[0], od_s[1]],
    ] };
    if ev("HMS_FF_DUMP").is_ok() {
        let tbase = tname.rsplit(['\\', '/']).next().unwrap_or("").to_string();
        let ptag = usage_tag("palette");
        let dump = |nm: &str, b: &(Vec<u8>, u32, u32)| {
            let mut rgba = b.0.clone(); for p in rgba.chunks_exact_mut(4) { p.swap(0, 2); }
            let path = format!("{}/ff_{}_{}_{}_{:#x}.png", diag_dump_dir(), nm, label, tbase, ptag);
            let _ = crate::headless::write_png(&path, &rgba, b.1, b.2);
            eprintln!("FF_DUMP {nm} {label} {}x{} -> {path}", b.1, b.2);
        };
        dump("noise_a", &noise_a); dump("noise_b", &noise_b); dump("palette", &palette);
        if let Some((m, mx)) = alpha_mask.as_ref() { dump("alpha_mask", m); eprintln!("FF_DUMP alpha_mask {label} xform={mx:?}"); }
        // Per-usage keep_alpha channel ranges (+ HMS_FF_DUMP_TAGS=<hex,hex,..>: arbitrary extra bitmap tags).
        let range_line = |label: String, t: u32| {
            if let Some((px, w, h)) = native.decode_bitmap_keep_alpha(cache, t, 0, 0) {
                let (mut amin, mut amax, mut rmin, mut rmax) = (255u8, 0u8, 255u8, 0u8);
                for p in px.chunks_exact(4) { amin = amin.min(p[3]); amax = amax.max(p[3]); rmin = rmin.min(p[2]); rmax = rmax.max(p[2]); }
                eprintln!("FF_DUMP {label} tag={t:#x} '{}' {w}x{h} keep_alpha: R {rmin}..{rmax} A {amin}..{amax}", native.tag_name(cache, t).unwrap_or_default());
            }
        };
        for u in ["noise_map_a", "noise_map_b", "alpha_mask_map", "palette"] {
            let t = usage_tag(u);
            range_line(format!("{u} {label} shader='{}'", tname.rsplit(['\\', '/']).next().unwrap_or("")), t);
        }
        if let Ok(extra) = ev("HMS_FF_DUMP_TAGS") {
            for t in extra.split(',').filter_map(|v| u32::from_str_radix(v.trim().trim_start_matches("0x"), 16).ok()) { range_line("extra".into(), t); }
        }
        if let Some(o) = overlay.as_ref() { dump("overlay", o); }
    }
    // Mode 3 samples the self_illum_map in the noise_a slot (bitmap curve -> view rule:
    // xRGB/sRGB curves are sRGB views in the engine = pow 2.2 decode here; linear curves raw).
    let gamma = if mode > 4.5 {
        // [_, overlay, base_map, detail_map] (gray50 stand-in detail = sRGB-encoded -> decode)
        [0.0, gflag("overlay_map"), gflag("base_map"), if bm("detail_map").is_some() { gflag("detail_map") } else { 1.0 }]
    } else if mode > 6.5 {
        // Multilayer: [_, overlay, self_illum_map, multiply map 1 + gamma (0 = none)]
        [0.0, gflag("overlay_map"), gflag("self_illum_map"), overlay_multiply.as_ref().map_or(0.0, |m| 1.0 + m.2)]
    } else if mode > 5.5 {
        [0.0, gflag("overlay_map"), 0.0, overlay_multiply.as_ref().map_or(0.0, |m| 1.0 + m.2)]
    } else if mode > 2.5 && mode < 3.5 {
        let g = gflag("self_illum_map");
        [0.0, 0.0, g, g]
    } else {
        [gflag("palette"), gflag("overlay_map"), gflag("noise_map_a"), if bm("noise_map_b").is_some() { gflag("noise_map_b") } else { gflag("noise_map_a") }]
    };
    if ev("HMS_FFDIAG").is_ok() { eprintln!("FFDIAG   gamma flags [pal, ov, na, nb] = {gamma:?} scroll na={na_s:?} nb={nb_s:?} ov={ov_s:?} od={od_s:?} od_mode={od_mode} mask_texels={}", alpha_mask.is_some()); }
    Some(FfExtra { noise_a, noise_b, palette, overlay, lanes, gamma, alpha_mask, overlay_detail, overlay_premul, overlay_ramp, overlay_intensity, edge_fade, overlay_multiply })
}

/// rmt2 template basename digits (`_0_2_0_2_1_2_0_3_0_0_0_1` → [0,2,0,2,1,2,0,3,0,0,0,1]).
fn rm_template_digits(template_name: &str) -> Vec<i32> {
    let base = template_name.rsplit(['\\', '/']).next().unwrap_or("");
    base.split('_').filter_map(|s| s.parse::<i32>().ok()).collect()
}

/// The 9 category options of a water rmt2 (`shaders\water_templates\_a_b_c_d_e_f_g_h_i`),
/// in the category order of HREK `shaders\water.render_method_definition`:
///   [0] waveshape    0 default (wave_slope_array), 1 none (flat), 2 bump (bump_map + bump_detail_map)
///   [1] watercolor   0 pure (water_color_pure),     1 texture (watercolor_texture * watercolor_coefficient)
///   [2] reflection   0 none, 1 static (environment_map cube * 256), 2 dynamic
///   [3] refraction   0 none (opaque water_color),   1 dynamic (screen-space refraction + Beer-Lambert)
///   [4] bankalpha    0 none, 1 paint (watercolor_texture.a), 2 from_shape_texture_alpha (global_shape.a)
///   [5] appearance   0 default
///   [6] global_shape 0 none, 1 paint (global_shape_texture height/choppy/foam-paint/bank)
///   [7] foam         0 none, 1 auto, 2 paint (global_shape.b), 3 both
///   [8] detail       0 none, 1 repeat (compute_detail_slope third wave layer)
/// These are the `TEST_CATEGORY_OPTION` switches of water_shading.hlsl_include. None when the name
/// is not a water template (or has fewer than 9 digits).
fn water_template_categories(template_name: &str) -> Option<[u8; 9]> {
    if !template_name.contains("water_templates") { return None; }
    let d = rm_template_digits(template_name);
    if d.len() < 9 { return None; }
    let mut out = [0u8; 9];
    for (k, v) in d.iter().take(9).enumerate() { out[k] = (*v).clamp(0, 9) as u8; }
    Some(out)
}

#[cfg(test)]
mod water_template_tests {
    use super::*;
    #[test]
    fn ridgeline_and_forge_templates_decode_to_their_hlsl_categories() {
        // cex_timberland spawn stream: pure watercolor, static reflection, dynamic refraction,
        // bankalpha from_shape, global_shape paint, foam both, detail repeat.
        let c = water_template_categories("shaders\\water_templates\\_0_0_1_1_2_0_1_3_1").unwrap();
        assert_eq!(c, [0, 0, 1, 1, 2, 0, 1, 3, 1]);
        // Forge World / Ridgeline puddles: pure + bankalpha paint + no foam.
        let p = water_template_categories("shaders\\water_templates\\_0_0_1_1_1_0_1_0_1").unwrap();
        assert_eq!((p[1], p[4], p[7]), (0, 1, 0));
        // Ridgeline lake: texture watercolor, from_shape, foam paint.
        let l = water_template_categories("shaders\\water_templates\\_0_1_1_1_2_0_1_2_1").unwrap();
        assert_eq!((l[1], l[4], l[7]), (1, 2, 2));
        assert!(water_template_categories("shaders\\shader_templates\\_0_0_1_0_0_0_1_0_0_0_0_0").is_none());
        assert!(water_template_categories("shaders\\water_templates\\_0_0_1").is_none());
    }
}

/// The ENGINE's alpha-test decision for one material, derived from the shader's
/// own data (tag class + rmt2 template option digits + the `alpha_test_map` usage) instead of
/// bitmap-name lists. Sources (HREK/tags/shaders):
///   * foliage.render_method_definition (class `rmfl`, `foliage_templates\_A_B_C_D`): category 1
///     = alpha_test: 0 off, 1 from_albedo_alpha (calc_alpha_test_from_albedo_ps: clip(albedo.a-0.5)),
///     2 on (calc_alpha_test_texture_ps: clip(alpha_test_map.a-0.5)). foliage.hlsl_include calls
///     calc_alpha_test_ps in EVERY entry point, so an rmfl leaf card never needs an alpha_test_map
///     to be a cutout — its base alpha IS the coverage. This is what the old name-list heuristic
///     missed on cex_ff_halo (`ca_halo_seedler_foliage`: rmfl _0_1_0_0, bitmap `seedler_veg_diff`).
///   * shader/custom.render_method_definition (`rmsh`/`rmcs`): category 2 = alpha_test: 0 none,
///     1 simple (calc_alpha_test_on_ps: clip(alpha_test_map.a-0.5)), rmcs 2 multiply_map. With the
///     option on but NO alpha_test_map bound the engine samples `default_alpha_test` (no holes), so
///     the authored usage slot stays the signal for these classes (unchanged behaviour).
///   * every other class (rmtr terrain, rmgl glass, rmw water, rmhg, rmd ...) has no alpha_test
///     category: only an authored `alpha_test_map` usage can make it a cutout (unchanged).
/// `template` = the rmt2 tag NAME (None when unresolved). A template-less rmfl is treated as
/// from_albedo_alpha: every shipped foliage template alpha-tests (_0_1_*, _0_2_*, _1_1_*).
fn engine_alpha_tests(shader_class: &str, template: Option<&str>, has_alpha_test_map: bool) -> bool {
    match shader_class {
        "rmfl" => match template.map(rm_template_digits).and_then(|d| d.get(1).copied()) {
            Some(0) => false,
            // 1 = from_albedo_alpha (base.a), 2 = on (alpha_test_map; MAT-30 binds it when distinct,
            // else base.a), unresolved template = assume the shipped default (from_albedo_alpha).
            _ => true,
        },
        _ => has_alpha_test_map,
    }
}

/// rmsh/rmcs template alpha_test option digit (category 2) is 0 = `none`, i.e. the
/// engine NEVER alpha-tests this material whatever its base alpha holds (Forge pallets `_3_2_0_...`).
/// Used to suppress the pixel-histogram cutout fallback. Non-rmsh classes return false.
fn rmsh_template_alpha_test_off(shader_class: &str, template: Option<&str>) -> bool {
    (shader_class == "rmsh" || shader_class == "rmcs")
        && template.map_or(false, |n| (n.contains("shader_templates") || n.contains("custom_templates")) && rm_template_digits(n).get(2) == Some(&0))
}

#[cfg(test)]
mod foliage_alpha_tests {
    // The engine alpha-test rule on the real template names seen in the caches.
    use super::*;
    const FOL_FROM_ALBEDO: &str = "shaders\\foliage_templates\\_0_1_0_0"; // cex_ff_halo seedler / birch
    const FOL_ON: &str = "shaders\\foliage_templates\\_1_1_2_0";
    const FOL_OFF: &str = "shaders\\foliage_templates\\_0_0_0_0";
    const SH_TREE_CARDS_AT: &str = "shaders\\shader_templates\\_0_0_1_0_0_0_1_0_0_0_0_0"; // alpha_test on
    const SH_TREEOFWOE: &str = "shaders\\shader_templates\\_0_1_0_1_2_1_0_0_0_0_0_0"; // alpha_test none
    const SH_PALLET: &str = "shaders\\shader_templates\\_3_2_0_1_2_1_0_0_0_0_0_0";

    #[test]
    fn rmfl_from_albedo_alpha_is_cutout_without_alpha_test_map() {
        assert!(engine_alpha_tests("rmfl", Some(FOL_FROM_ALBEDO), false));
        assert!(engine_alpha_tests("rmfl", Some(FOL_ON), false));
        assert!(engine_alpha_tests("rmfl", None, false), "template-less rmfl defaults to from_albedo_alpha");
        assert!(!engine_alpha_tests("rmfl", Some(FOL_OFF), false));
    }

    #[test]
    fn rmsh_follows_the_authored_alpha_test_map() {
        assert!(engine_alpha_tests("rmsh", Some(SH_TREE_CARDS_AT), true));
        assert!(!engine_alpha_tests("rmsh", Some(SH_TREE_CARDS_AT), false), "option on but no map bound = default_alpha_test (no holes)");
        assert!(!engine_alpha_tests("rmsh", Some(SH_TREEOFWOE), false));
        assert!(engine_alpha_tests("rmsh", Some(SH_TREEOFWOE), true), "an authored usage slot keeps its #133 meaning");
        assert!(!engine_alpha_tests("rmtr", None, false));
        assert!(!engine_alpha_tests("rmgl", Some("shaders\\glass_templates\\_0_0_0_0_0_0"), false));
    }

    #[test]
    fn rmsh_digit_zero_suppresses_the_histogram_fallback() {
        assert!(rmsh_template_alpha_test_off("rmsh", Some(SH_PALLET)));
        assert!(rmsh_template_alpha_test_off("rmsh", Some(SH_TREEOFWOE)));
        assert!(!rmsh_template_alpha_test_off("rmsh", Some(SH_TREE_CARDS_AT)));
        assert!(!rmsh_template_alpha_test_off("rmfl", Some(FOL_OFF)), "rmfl is decided by engine_alpha_tests, never by the rmsh digit");
        assert!(!rmsh_template_alpha_test_off("rmsh", None));
    }
}

/// Engine albedo_default/simple/detail = base × (detail) × albedo_color — bake the CONSTANT tint
/// into the gamma-encoded base texels (a^(1/2.2)·c^(1/2.2) == (a·c)^(1/2.2)). Used for OBJECT parts, whose
/// albedo_color was previously dropped (Condemned's red/blue reactor doors are a white base × albedo_color).
fn apply_albedo_color(tex: &mut (Vec<u8>, u32, u32), color: [f32; 4]) {
    if ev("HMS_NO_ALBEDO_COLOR").is_ok() { return; }
    let c = [color[0], color[1], color[2]];
    if c.iter().all(|v| (*v - 1.0).abs() < 1e-3) || c.iter().any(|v| !v.is_finite() || *v < 0.0) { return; }
    let g: [f32; 3] = [c[0].powf(1.0 / 2.2), c[1].powf(1.0 / 2.2), c[2].powf(1.0 / 2.2)];
    for px in tex.0.chunks_exact_mut(4) {
        // decoded bitmaps are BGRA
        px[2] = (px[2] as f32 * g[0]).min(255.0) as u8;
        px[1] = (px[1] as f32 * g[1]).min(255.0) as u8;
        px[0] = (px[0] as f32 * g[2]).min(255.0) as u8;
    }
}

/// The authored `base_map` UV xform SCALE of an rmsh object shader (engine
/// transform_texcoord(texcoord, base_map_xform) in every calc_albedo_*_ps). [1,1] when the shader is
/// not rmsh, authors no finite/non-zero scale, or -- because mesh_shade samples the emissive at the
/// SAME tiled UV as the base -- when the part also carries a self_illum_map whose own xform differs
/// (the engine tiles that map by self_illum_map_xform; keep the untiled legacy sampling there rather
/// than tile the emissive wrongly). The xform OFFSET (.zw) has no mesh lane yet (BSP ignores it too).
fn object_base_tile(native: &NativeDll, model: hms_native::ModelHandle, shader: i32, has_emissive: bool) -> [f32; 2] {
    if native.model_shader_class(model, shader) != "rmsh" { return [1.0, 1.0]; }
    let Some(sc) = native.model_shader_constants(model, shader) else { return [1.0, 1.0] };
    let Some(b) = sc.real("base_map") else { return [1.0, 1.0] };
    if !b.iter().all(|v| v.is_finite()) || b[0].abs() < 1e-4 || b[1].abs() < 1e-4 { return [1.0, 1.0]; }
    if has_emissive {
        let si = sc.real("self_illum_map").unwrap_or([1.0, 1.0, 0.0, 0.0]);
        if (si[0] - b[0]).abs() > 1e-4 || (si[1] - b[1]).abs() > 1e-4 { return [1.0, 1.0]; }
    }
    [b[0], b[1]]
}

fn self_illum_option(template_name: &str) -> (i32, bool) {
    let halogram = template_name.contains("halogram");
    let base = template_name.rsplit(['\\', '/']).next().unwrap_or("");
    let digits: Vec<i32> = base.split('_').filter_map(|s| s.parse::<i32>().ok()).collect();
    let opt = if halogram { digits.get(1).copied() } else { digits.get(6).copied() };
    (opt.unwrap_or(-1), halogram)
}

/// LIT-SI-3 OBJECT CENSUS (HMS_SIMODE_DIAG). Accumulate the OBJECT self_illum_mode distribution
/// across the decode. Deduped per (mode_tag, shader) so each distinct object-shader is counted
/// once (decode is parallel across objects, so a Mutex guards the shared state). Prints the
/// per-hit line + a running histogram so a headless render of a map reports which modes objects
/// actually use — the evidence for whether three_channel(2)/meter(6)/times_diffuse(7) infra is
/// worth building. Zero cost when HMS_SIMODE_DIAG is unset (caller gates the call).
fn si_object_census(mode_tag: u32, shader: i32, si_mode: u8, name: &str) {
    use std::sync::{Mutex, OnceLock};
    #[allow(clippy::type_complexity)]
    static STATE: OnceLock<Mutex<(std::collections::HashSet<(u32, i32)>, [usize; 14])>> = OnceLock::new();
    let st = STATE.get_or_init(|| Mutex::new((std::collections::HashSet::new(), [0usize; 14])));
    let mut g = st.lock().unwrap();
    if !g.0.insert((mode_tag, shader)) {
        return;
    }
    let bin = if (si_mode as usize) < 13 { si_mode as usize } else { 13 };
    g.1[bin] += 1;
    let h = g.1;
    eprintln!("HMS_SIMODE_DIAG OBJ mode_tag={:#x} sh={} si_mode={} ({}) name={}",
        mode_tag, shader, si_mode, si_name(si_mode), name);
    eprintln!("HMS_SIMODE_DIAG OBJ census: off={} simple={} 3channel={} plasma={} from_albedo={} detail={} meter={} times_diffuse={} alpha_mask={} multilayer={} palette={} change_color={} cc_detail={} unknown={}",
        h[0], h[1], h[2], h[3], h[4], h[5], h[6], h[7], h[8], h[9], h[10], h[11], h[12], h[13]);
}

/// CPU-side decoded geometry for one render model (positions + normals + uv) plus its
/// resolved materials.
struct DecodedModel {
    verts: Vec<MeshVertex>,
    indices: Vec<u32>,
    /// Per-shader object draw parts (see ObjPart). Non-empty only for multi-material object
    /// models; when empty the whole model uses the single `tex` (BSP + single-material objects).
    obj_parts: Vec<ObjPart>,
    /// The object's hlmt model-variant Name sids in block order (index = the bit in
    /// `ObjPart::vbits`; [0] = the engine default). Empty for models without hlmt variants.
    variant_sids: Vec<u32>,
    /// whole-model shader_halogram flag (single-material holograms — e.g. the armor-ability
    /// equipment holo funnel). Routes the single `tex` path to the translucent additive holo pass.
    is_halo: bool,
    /// whole-model FORCEFIELD (single-material shield wall/door: rmhg palettized_plasma). The
    /// per-part forcefield detection only runs for MULTI-material models; a single-material shield
    /// needs these dec-level fields or it renders as an opaque, static, wrongly-textured surface.
    /// When true, `tex`/`emissive` hold the GRAYSCALE noise and the single path tints by `ff_color`.
    is_forcefield: bool,
    ff_color: [f32; 3],
    ff_scroll: [f32; 2],
    /// single-material shield's full engine material.
    ff_extra: Option<std::sync::Arc<FfExtra>>,
    /// Shader 0's authored `self_illum_color` (objects only; None when unauthored/black).
    si_color: Option<[f32; 3]>,
    /// single-material rmsh glass opacity map (objects).
    glass_op: Option<std::sync::Arc<GlassOp>>,
    /// LOAD SPEED: GPU vertex/index buffers created in PARALLEL inside decode_bsp_mesh (the
    /// rayon decode phase), so the serial finalize skips the two big `create_buffer_init` calls
    /// (~2/3 of the per-mesh upload cost). Taken by the finalize → `upload_mesh_prebuilt`. None →
    /// the finalize falls back to `upload_mesh` (builds them serially), e.g. the cold-decode path.
    vbuf: Option<wgpu::Buffer>,
    ibuf: Option<wgpu::Buffer>,
    min: Vec3,
    max: Vec3,
    /// Base-colour texture (rgba, w, h) resolved from the render model's first
    /// shader, or None → default white.
    tex: Option<SharedTex>,
    /// Self-illum / emissive texture (rgba, w, h), or None → no glow.
    emissive: Option<SharedTex>,
    /// This material's AVERAGE self-illum radiance as unclamped HDR RGB
    /// (mean(self_illum_map texel) × self_illum_color × self_illum_intensity), or None when the
    /// surface doesn't self-illuminate. This is the emitter radiance the path-tracer treats each
    /// self-illum triangle as an AREA LIGHT with (light fixtures = the real interior emitters).
    emissive_avg: Option<[f32; 3]>,
    /// (HDR self-illum): the opaque/BSP emissive baked in FLOAT (Rgba16Float, packed
    /// as f16 little-endian bytes, 8/px). Engine keeps self_illum_color × self_illum_intensity in
    /// float so authored intensity>1 survives unclamped-above into `max(0,…)` and drives bloom
    /// (entry_points.hlsl_include:512). HMS's 8-bit `emissive` clips it to [0,1]; this parallel
    /// buffer carries the true HDR magnitude. When Some, load_step uploads THIS as the mesh_shade
    /// emis_tex instead of the u8 `emissive`. None → fall back to the u8 texture (unchanged).
    emissive_hdr: Option<SharedTex>,
    /// True when this is a shader_water surface (rendered via the water pass).
    is_water: bool,
    /// True when the BSP material's shader tag class is `rmgl` (glass). The authoritative
    /// glass signal — routes to the transparent pass regardless of blend enum / diffuse name, and
    /// forbids alpha-test discard (glass diffuse alpha is a spec mask that would erase the pane).
    is_glass_shader: bool,
    /// Terrain-blend layers (4 base map tags + blend mask tag + tiles), when this
    /// is a shader_terrain material — rendered via the terrain pass.
    terrain: Option<TerrainTags>,
    /// two/four_change_color albedo mask (change_color_map: r = primary, g = secondary) + its UV xform,
    /// for single-material rmsh objects (Forge pallets etc.); tinted per instance in mesh_shade via the cc sentinel.
    cc_map: Option<std::sync::Arc<(Vec<u8>, u32, u32)>>,
    cc_map_xform: [f32; 4],
    /// The object's AUTHORED default change colours [primary, secondary] (obje "change
    /// colors" block, the permutation matching the default variant), linear RGB, white when unauthored.
    /// The engine applies these through the change_color_map masks when no team/object colour is set.
    cc_default: [[f32; 3]; 2],
    /// BSP material diffuse bitmap tag + blend mode (0 for render models).
    diffuse_tag: u32,
    blend: u32,
    /// Opaque `.shader` detail-map tag (rmsh rock/cliff texture), 0 if none.
    detail_tag: u32,
    /// Opaque `.shader` bump/normal-map tag (rmsh relief), 0 if none.
    bump_tag: u32,
    /// Authored `bump_map` UV xform [tile.x, tile.y, off.x, off.y]. The engine samples the
    /// normal map at ITS OWN scale (near unit), independent of the base_map tile — HMS was sampling
    /// it at the base tile, so stretched-base materials (concrete_a_diff tile 0.10) smoothed the
    /// normal to flat (no 3D relief). [0;4] → shader keeps the base-auv sample (byte-identical).
    bump_xform: [f32; 4],
    /// Opaque `.shader` detail-map UV xform: [tile.x, tile.y, off.x, off.y]
    /// from the authored `detail_map` rmt2 constant. [0;4] → shader uses the 6.0
    /// fallback (the default tiling when a material authors no xform).
    detail_xform: [f32; 4],
    /// Opacity fresnel triplet [coef, steepness, bias, 2.0] for alpha_blend parts (w=2 flag); zeros otherwise.
    fres_xform: [f32; 4],
    /// SECONDARY + TERTIARY detail maps (`detail_map2` / `detail_map3`). Reach floor/
    /// wall shaders layer detail_map (large grain) × detail_map2 (panel/insert detail) × detail_map3
    /// — the engine's calc_albedo_three_detail_blend. Baking only detail_map dropped these layers,
    /// so multi-detail materials rendered with WRONG blending/color (the persistent texture).
    /// 0 = absent. xform = [tile.x, tile.y, off.x, off.y].
    detail2_tag: u32,
    detail2_xform: [f32; 4],
    detail3_tag: u32,
    detail3_xform: [f32; 4],
    /// Owning SBSP cluster (0xFFFFFFFF = instanced geometry, which has no
    /// per-cluster PVL — lit via the airprobe grid instead).
    cluster: u32,
    /// BSP material index (for shader-constant lookup, e.g. water params).
    material_index: i32,
    /// shader-kind classification (ZH_BSP_GetMaterialShaderKind). 0 =
    /// normal/unknown, 1 = `...\black` (textureless, renders black), 2 =
    /// `shaders\invalid` (broken placeholder). Selects the no-diffuse fallback
    /// colour: textureless occluder shells must render dark, not pale gray, or
    /// they read as see-through panels (Countdown material 50).
    shader_kind: u32,
    /// True if per-vertex baked lighting (cluster or per-instance PVL) was applied
    /// to the vertex colours — suppresses the airprobe flat-tint fallback.
    has_pvl: bool,
    /// For instances baked with the engine `single_probe` lighting
    /// policy (~18% of Forge instances), their OWN baked dual-VMF ambient (linear HDR).
    /// Used in the airprobe fallback INSTEAD of the generic airprobe-centroid sample,
    /// so single-probe rocks/cliffs get their real baked light (not a flat region guess).
    /// None = not single-probe (per-vertex has_pvl, or true airprobe fallback).
    probe_tint: Option<[f32; 3]>,
    /// The instance single probe's RAW dual-vMF (Lbsp+0x6C probes[instances[ord].probe_index],
    /// 16 halves -> floats: dir0 xyz, mask0, col0 rgb, bw0, dir1 xyz, mask1, col1 rgb, bw1). An object whose
    /// lighting ray hits such an instance copies THIS into its sample (engine `sub_1406B7690` -> +12 of the
    /// 212-B sample), not an isotropic re-expression of the up-facing irradiance. Set with `probe_tint`.
    probe_raw: Option<[f32; 16]>,
    /// The RAW per-vertex PVL lobe SOURCE (covers `verts`; empty when not PVL-lit or when
    /// the mesh came from the map cache). An object's lighting ray that hits this mesh samples the
    /// nearest vertex's lobes (doc 16 §1.4). Moved into `LmSampleMesh` at load; never uploaded.
    /// Runs of (start, count, Arc<ClusterPvl>, scale) decoded on lookup instead of 40 B of
    /// decoded lobes per vertex (Boardwalk: 148 MB -> the shared 6 B/vertex PVL buffers).
    pvl_src: Vec<PvlLobeSrc>,
    /// Every texture slot of this model has been uploaded by the object rebuild, so its CPU
    /// texture bytes may be released (`release_model_texture_bytes`) whenever nothing else shares them.
    tex_uploaded: bool,
    /// UV scroll rate/sec for animated surfaces (waterfalls); [0,0] = static.
    scroll: [f32; 2],
    /// Per-material base-map UV tile (engine `base_map` xform scale from
    /// ZH_BSP_GetMaterialDiffuseTiling). (1,1) = untiled. Applied on the opaque
    /// path so tiled surfaces (boardwalk floor) don't stretch to one sample.
    diffuse_tile: [f32; 2],
    /// UV density (uv-units per world-unit) — mesh UV extent / world extent. Feeds the
    /// world-space-footprint LOD floor that fixes minification aliasing on heavily-
    /// tiled surfaces (Countdown floor) where the UV derivatives under-report. 0 = off.
    uv_density: f32,
    /// True when the material authors an `alpha_test_map` — the definitive cutout signal
    /// the C# reference uses (NativeBspMeshAdapter). Forces the alpha-test path so dense
    /// tree/foliage canopy cards don't render with a solid card background, which
    /// the pixel-histogram heuristic alone misses (canopy isn't ≥55% transparent).
    alpha_test: bool,
    /// MAT-30: the DEDICATED `alpha_test_map` bitmap tag (usage "alpha_test_map"), when the
    /// material authors one DISTINCT from the base_map. 0 / 0xFFFFFFFF = none or same-as-base →
    /// the shader clips on base.a exactly as before. When distinct + decoded, its view is bound
    /// at material_bgl binding 13 and fs_alphatest clips on ITS alpha at 0.5 (engine
    /// calc_alpha_test_ps samples a map distinct from the base).
    alpha_test_tag: u32,
    /// rmsh alpha_blend `opacity_texture` (blend_source_from_opacity_map) — the engine's
    /// final_opacity = 1-(1-luma(opacity.rgb))(1-fresnel) (blend.hlsl_include); 0 = none (use albedo alpha).
    opacity_tag: u32,
    opacity_xform: [f32; 4],
    /// 0 = none, 1 = opacity map ALPHA, 2 = opacity map RGB luminance.
    opacity_mode: f32,
    /// 1 = opacity bitmap curve is gamma-encoded (decode), 0 = linear.
    opacity_gamma: f32,
    /// environment_mapping option (rmt2 digit: rmsh 5 / rmgl 3): 0 none, 1 per_pixel, 2 dynamic, 3 flat.
    env_option: u8,
    /// BSP glass (rmsh alpha_blend / rmgl) decoded lanes. glass_abs = the rmt2 alpha_blend_source
    /// digit (rmsh 11 / rmgl 5): 0 albedo_alpha_without_fresnel, 1 albedo_alpha, 2 opacity_map_alpha,
    /// 3 opacity_map_rgb, 4 opacity_map_alpha_and_albedo_alpha (blend.hlsl_include:25-29); 255 = unresolved.
    glass_abs: u8,
    /// V.color carries the PER-VERTEX light-probe AREA term [0.25·(dom+fill).rgb,
    /// lum(dual_vmf_diffuse(n))/lum(area)] (xbump.w = 2) instead of albedo_color, which then rides mat_spec2
    /// ([rgb, 2+a]); glass_spec = [specular_tint.rgb, fresnel_curve_steepness] (si_ctl), glass_fres =
    /// [fresnel_color.rgb, 1 = rmsh cook_torrance/two_lobe: area × final_specular_tint, 0 = rmgl untinted].
    glass_pv: bool,
    glass_albedo: [f32; 4],
    glass_spec: [f32; 4],
    glass_fres: [f32; 4],
    /// [albedo_blend (cook_torrance F0 = lerp(specular_tint, albedo, albedo_blend)),
    /// diffuse_coefficient (multiplies the lit body: rmsh cook_torrance_core:248, rmgl glass.hlsl:131),
    /// rmt2 specular_mask digit (0 none/1, 1 from_diffuse = albedo.w, 2 albedo.w x mask_tex.a, 3 mask_tex.a;
    /// rmgl = 0), 1.0 when a `specular_mask_texture` resolved (bound in the material_texture slot)].
    /// Rides xbump.xyz (+ w = 2 flags the per-vertex probe lanes) into blend_shade.
    glass_ctl: [f32; 4],
    /// The `specular_mask_texture` bitmap tag for spec-mask digits 2/3 (0 = none).
    glass_spec_mask_tag: u32,
    /// per-parameter TranslationX/Y scroll (uv/s) for [base_map, detail_map, detail_map2, self_illum_map]
    /// from the shader's animation overlays (routing-resolved). Alpha-blend layered materials (waterfalls) use these.
    layer_scroll: [[f32; 2]; 4],
    /// rmt2 template albedo digit (rmsh category 0): 7 = two_detail (base × detail × detail2 × 4.59²).
    albedo_tmpl: u8,
    /// per-material SPECULAR strength from the rmt2 REAL constants (RE: Reach opaque
    /// shaders have NO spec/gloss bitmap — specular is driven by `specular_coefficient` ×
    /// `analytical_specular_contribution`, applied REGARDLESS of diffuse alpha). 0.0 = the
    /// material authored no spec constant → shader uses the legacy diffuse-alpha gate (no
    /// regression). >0 drives an analytical + env lobe even on alpha-less (BC1) diffuse —
    /// the fix for "metal/tile/floors look flat".
    mat_spec: f32,
    /// per-material ROUGHNESS (`roughness`/`analytical_roughness`, else derived from
    /// `specular_power`). -1.0 = not authored → shader keeps its legacy roughness curve.
    mat_rough: f32,
    /// env-cubemap reflection weight (`environment_map_specular_contribution`). 0 = none.
    mat_env: f32,
    /// MAT-31: the `material_texture` bitmap tag (usage "material_texture") when the material's rmt2
    /// binds one (= `use_material_texture` compiled for that variant). 0 / 0xFFFFFFFF = none → no
    /// per-texel override. When resolved, its view binds at material_bgl binding 14 and mesh_shade
    /// applies `roughness = lerp(black_roughness, roughness, material_texture.a)` +
    /// `specular_coefficient *= lerp(black_specmult, 1, material_texture.a)` (cook_torrance_core
    /// .hlsl_include:112-118). A default-bound (1×1, a=1) texture no-ops naturally.
    mattex_tag: u32,
    /// MAT-31: `material_texture_black_roughness` (roughness where material_texture.a==0). Default 0.
    mattex_black_rough: f32,
    /// MAT-31: `material_texture_black_specular_multiplier` (spec scale where material_texture.a==0). Default 0.
    mattex_black_specmult: f32,
    /// MAT-31: authored `material_texture_xform` [tile.x, tile.y, off.x, off.y]. [0;4] → base auv.
    mattex_xform: [f32; 4],
    /// MAT-1: per-shader `material_model` enum (0..9) that selects which engine
    /// calc_material_<m>_ps the surface compiled. 0=diffuse_only 1=cook_torrance
    /// 2=two_lobe_phong 3=foliage 4=none 5=glass 6=organism 7=single_lobe_phong 8=hair
    /// 9=custom_specular. Default 1 (cook_torrance = HMS's current unconditional path).
    /// SAFE dispatch (mesh.rs mesh_shade): models 0/3/4 zero the specular contribution
    /// the engine never computes; all others keep the current specular path unchanged.
    material_model: u8,
    /// ALBEDO-VARIANT: per-shader `albedo` category (0 default / 1 two_detail / 2 black_point /
    /// 3 overlay / 4 detail_blend / 5 three_detail / 6 color_mask / 7 constant_color). Selects
    /// the base×detail composite; multi-detail variants (1/2/4/5) multiply a SECOND live detail
    /// map (base×DM²×detail×detail2) — the contrast HMS's single-detail path was missing.
    albedo_option: u8,
    /// LIT-SI-3: per-shader `self_illumination` MODE (0..12) that selects which engine
    /// calc_self_illumination_<m>_ps the surface compiled. 0 off / 1 simple / 2 three_channel /
    /// 3 plasma / 4 from_albedo / 5 detail / 6 meter / 7 times_diffuse / 8 simple_with_alpha_mask /
    /// 9 multilayer / 10 palette / 11 change_color / 12 change_color_detail. Default 1 (simple =
    /// HMS's single-composite emissive path). Only mode 4 (from_albedo) is ROUTED specially in
    /// mesh_shade (emit albedo×color×intensity, then zero the lit albedo term — engine zeros albedo
    /// at self_illumination.hlsl_include:115-116); all other modes keep the current path.
    self_illum_mode: u8,
    /// LIT-SI-3: `self_illum_color.rgb × self_illum_intensity` for this material (unclamped HDR),
    /// used only by the from_albedo route to synthesize the emission from the sampled albedo. [0;3]
    /// when not authored (from_albedo then emits white×albedo). Ignored by every other mode.
    self_illum_cmul: [f32; 3],
    /// single-material object engine material lanes (shader 0); Default = legacy lane. Not persisted.
    obj_mat: ObjMat,
    /// single-material rmfl object lane (see ObjPart::foliage). Not persisted.
    foliage: Option<[f32; 2]>,
    /// artist-Fresnel constants [metalness(albedo_blend), fresnel_curve_steepness,
    /// specular_tint luma (dielectric F0 base), fresnel_color luma (edge)]. [0;4] = unauthored →
    /// shader keeps the fixed-dielectric Schlick path (no regression). metalness>0 makes metals
    /// reflect their albedo (RE: artist-Fresnel constants).
    mat_spec2: [f32; 4],
    /// specular_tint.rgb (w=1 when authored) / fresnel_color.rgb (w=1) for the artist-Fresnel colour.
    spec_rgb: [f32; 4],
    fres_rgb: [f32; 4],
    /// GPU lightmap: when true, the DM/SDM atlas submaps below are uploaded as raw-BC
    /// GPU textures in `load_step` (deduped per (tag,submap) via lm_tex_cache) and sampled +
    /// dual-VMF-decoded in the fragment shader (HMS_GPU_LIGHTMAP), replacing the CPU bake.
    lm_gpu: bool,
    lm_dm_tag: u32,
    lm_dm_sub: u32,
    lm_sdm_tag: u32,
    lm_sdm_sub: u32,
    /// entry.hdr_scale and the atlas compression K (HMS_ATLAS_K2), passed to the shader.
    lm_hdr: f32,
    lm_k: f32,
}

/// A pickable BSP surface for the material inspector (world AABB + material).
#[derive(Clone, Copy)]
struct BspPick {
    min: Vec3,
    max: Vec3,
    diffuse: u32,
    blend: u32,
}

/// Retained per-BSP-mesh lightmap geometry, captured during load so the path-traced
/// lightmapper can rasterize each mesh's triangles into its lightmap-UV atlas WITHOUT re-decoding
/// the whole BSP. World-space (BSP verts carry no instance transform). Only meshes with a real GPU
/// lightmap atlas (`lm_gpu`) are retained — those are the surfaces we re-light. Compact: pos+normal
/// +uv2 per vert (~32B) + indices.
/// MAT-1: human-readable name for a material_model enum value (diagnostics only).
fn mm_name(m: u8) -> &'static str {
    match m {
        0 => "diffuse_only", 1 => "cook_torrance", 2 => "two_lobe_phong", 3 => "foliage",
        4 => "none", 5 => "glass", 6 => "organism", 7 => "single_lobe_phong", 8 => "hair",
        9 => "custom_specular", _ => "UNKNOWN",
    }
}

/// LIT-SI-3: human-readable name for a self_illumination mode enum value (diagnostics only).
fn si_name(m: u8) -> &'static str {
    match m {
        0 => "off", 1 => "simple", 2 => "three_channel", 3 => "plasma", 4 => "from_albedo",
        5 => "detail", 6 => "meter", 7 => "times_diffuse", 8 => "simple_with_alpha_mask",
        9 => "multilayer", 10 => "palette", 11 => "change_color", 12 => "change_color_detail",
        _ => "UNKNOWN",
    }
}

/// 2D edge function (signed area ×2 of triangle a,b,p) for the lightmap-texel rasterizer.
#[inline]
fn edge(a: glam::Vec2, b: glam::Vec2, p: glam::Vec2) -> f32 {
    (b.x - a.x) * (p.y - a.y) - (b.y - a.y) * (p.x - a.x)
}

/// DENOISE: edge-aware à-trous filter over a submap's baked dual-VMF grid, the standard
/// finishing step for a path-traced bake. Blends each covered texel with atlas neighbours weighted by
/// surface-normal + world-position similarity (from the G-buffer), so noise/fireflies smooth out
/// WITHOUT bleeding across geometry edges or onto differently-facing surfaces. Also does a firefly
/// pre-pass: any covered texel far brighter than its covered neighbours' median is pulled down to it
/// (kills the salt-and-pepper bright dots on dark surfaces). Operates on ambient/dom_color/dom_dir.
fn denoise_atlas(
    grid: &mut [hms_render::lightbake_gpu::GpuTexelOut],
    gbuf: &[hms_render::lightbake_gpu::GpuTexel],
    w: usize,
    h: usize,
    iterations: u32,
) {
    if w == 0 || h == 0 || grid.len() != w * h { return; }
    let lum = |c: &[f32; 4]| 0.2126 * c[0] + 0.7152 * c[1] + 0.0722 * c[2];
    let covered = |i: usize| gbuf[i].normal[3] >= 0.5;

    // --- firefly pre-pass: clamp outliers to the 3×3 covered-neighbour median luminance ---
    let orig_lum: Vec<f32> = grid.iter().map(|o| lum(&o.ambient)).collect();
    let mut fixed = grid.to_vec();
    for y in 0..h {
        for x in 0..w {
            let i = y * w + x;
            if !covered(i) { continue; }
            let mut nb: Vec<f32> = Vec::with_capacity(8);
            for dy in -1i32..=1 {
                for dx in -1i32..=1 {
                    if dx == 0 && dy == 0 { continue; }
                    let (xx, yy) = (x as i32 + dx, y as i32 + dy);
                    if xx < 0 || yy < 0 || xx >= w as i32 || yy >= h as i32 { continue; }
                    let j = yy as usize * w + xx as usize;
                    if covered(j) { nb.push(orig_lum[j]); }
                }
            }
            if nb.len() < 3 { continue; }
            nb.sort_by(|a, b| a.partial_cmp(b).unwrap_or(std::cmp::Ordering::Equal));
            let med = nb[nb.len() / 2];
            let l = orig_lum[i];
            // only pull DOWN clear outliers (a texel >3× its neighbourhood median is a firefly)
            if l > med * 3.0 + 0.05 && l > 1e-4 {
                let s = (med * 3.0 + 0.05) / l;
                for k in 0..3 {
                    fixed[i].ambient[k] *= s;
                    fixed[i].dom_color[k] *= s;
                }
            }
        }
    }

    // --- edge-aware à-trous: increasing step (1,2,4,…), 5-tap binomial per axis ---
    let kernel = [1.0f32, 4.0, 6.0, 4.0, 1.0];
    let mut src = fixed;
    let mut dst = src.clone();
    for it in 0..iterations {
        let step = 1i32 << it;
        for y in 0..h {
            for x in 0..w {
                let i = y * w + x;
                if !covered(i) {
                    dst[i] = src[i];
                    continue;
                }
                let n0 = glam::Vec3::new(gbuf[i].normal[0], gbuf[i].normal[1], gbuf[i].normal[2]);
                let p0 = glam::Vec3::new(gbuf[i].pos[0], gbuf[i].pos[1], gbuf[i].pos[2]);
                // world footprint scale: distance to the +x covered neighbour (fallback 1 unit)
                let mut pscale = 1.0f32;
                if x + 1 < w && covered(i + 1) {
                    let pn = glam::Vec3::new(gbuf[i + 1].pos[0], gbuf[i + 1].pos[1], gbuf[i + 1].pos[2]);
                    pscale = (pn - p0).length().max(0.01);
                }
                let sigma_p = (pscale * step as f32 * 3.0).max(0.05);
                let (mut amb, mut dom, mut dir) = ([0.0f32; 3], [0.0f32; 3], [0.0f32; 4]);
                let mut wsum = 0.0f32;
                for (ky, dy) in (-2i32..=2).enumerate() {
                    for (kx, dx) in (-2i32..=2).enumerate() {
                        let (xx, yy) = (x as i32 + dx * step, y as i32 + dy * step);
                        if xx < 0 || yy < 0 || xx >= w as i32 || yy >= h as i32 { continue; }
                        let j = yy as usize * w + xx as usize;
                        if !covered(j) { continue; }
                        let nj = glam::Vec3::new(gbuf[j].normal[0], gbuf[j].normal[1], gbuf[j].normal[2]);
                        let pj = glam::Vec3::new(gbuf[j].pos[0], gbuf[j].pos[1], gbuf[j].pos[2]);
                        let wn = n0.dot(nj).max(0.0).powi(32);
                        let wp = (-(pj - p0).length_squared() / (sigma_p * sigma_p)).exp();
                        let wt = kernel[kx] * kernel[ky] * wn * wp;
                        if wt <= 0.0 { continue; }
                        for k in 0..3 {
                            amb[k] += src[j].ambient[k] * wt;
                            dom[k] += src[j].dom_color[k] * wt;
                        }
                        for k in 0..4 { dir[k] += src[j].dom[k] * wt; }
                        wsum += wt;
                    }
                }
                if wsum > 1e-6 {
                    let inv = 1.0 / wsum;
                    for k in 0..3 {
                        dst[i].ambient[k] = amb[k] * inv;
                        dst[i].dom_color[k] = dom[k] * inv;
                    }
                    dst[i].ambient[3] = src[i].ambient[3];
                    dst[i].dom_color[3] = src[i].dom_color[3];
                    let dv = glam::Vec3::new(dir[0] * inv, dir[1] * inv, dir[2] * inv);
                    let dl = dv.length();
                    if dl > 1e-4 {
                        let dn = dv / dl;
                        dst[i].dom = [dn.x, dn.y, dn.z, (dir[3] * inv).clamp(0.0, 1.0)];
                    } else {
                        dst[i].dom = src[i].dom;
                    }
                } else {
                    dst[i] = src[i];
                }
            }
        }
        std::mem::swap(&mut src, &mut dst);
    }
    grid.copy_from_slice(&src);
}

/// SWAP: one submap's baked dual-VMF atlas — the four encoded RGBA8 planes the shader
/// samples (DM + 3 SDM slices), same resolution as the shipped atlas.
pub struct BakedAtlas {
    pub dm: Vec<u8>,
    pub sdm0: Vec<u8>,
    pub sdm1: Vec<u8>,
    pub sdm2: Vec<u8>,
    pub w: u32,
    pub h: u32,
    pub k: f32,
}

pub struct BspLmMesh {
    /// (world_pos, world_normal, uv2) per vertex. uv2 is the submap-LOCAL [0,1] lightmap UV.
    pub verts: Vec<([f32; 3], [f32; 3], [f32; 2])>,
    pub indices: Vec<u32>,
    /// DM atlas the mesh samples (tag, submap) — the target atlas dims/region to bake into.
    pub dm: (u32, u32),
    /// DM atlas resolution (texels) — captured at load from the decoded shipped atlas.
    pub dm_w: u32,
    pub dm_h: u32,
    /// SDM atlas (tag, submap).
    pub sdm: (u32, u32),
    pub hdr: f32,
    pub k: f32,
    /// diffuse bitmap tag — bounce-albedo source for GI colour bleed.
    pub diffuse: u32,
}

/// In-flight state for a chunked BSP load. Each `load_step` decodes a bounded
/// number of meshes so the UI thread never stalls on a big map. Persists the
/// open BSP + the tag-keyed texture cache across frames.
struct LoadJob {
    sbsps: Vec<u32>,
    sbsp_i: usize,
    bsp: Option<BspHandle>,
    mesh_i: u32,
    mesh_n: u32,
    tex_cache: HashMap<u32, (wgpu::TextureView, wgpu::Texture)>,
    /// BSP forcefield (rmhg palettized_plasma) material textures, keyed by
    /// (material index, slot 0 noise_a / 1 noise_b / 2 palette / 3 overlay). Uploaded once per
    /// material from the decoded FfExtra (raw, gamma flags ride xctl like the object lane).
    ff_tex_cache: HashMap<(i32, u8), (wgpu::TextureView, wgpu::Texture)>,
    /// Detail maps decoded with a COMPLETE CPU mip chain (down to 1×1), kept
    /// SEPARATE from tex_cache. The shared tex_cache may hold a BC-uploaded copy of the same
    /// tag (bitmaps double as base on one material and detail on another) whose mip chain is
    /// capped at 4×4 by the block-copy constraint. A 100×-tiled grain detail sampled off that
    /// capped chain can't minify to flat → per-pixel red/green "rainbow" aliasing (Countdown
    /// ground). Sampling detail off its own full-mip texture fixes it without disabling BC.
    detail_cache: HashMap<u32, (wgpu::TextureView, wgpu::Texture)>,
    /// BAKED base×detail composites, keyed by (base_tag, detail_tag, ratioX_bits,
    /// ratioY_bits, tint_packed). Matches the C# tool's TryBakeDetailIntoBase: opaque
    /// `shader` materials CPU-composite base × (detail × 4.59479) into ONE texture at load,
    /// so the grain lives at BASE tiling inside a proper mip chain and survives distance
    /// WITHOUT the runtime-detail aliasing (the elevated-camera "wood floor too large / grainy"
    /// look). Baked materials pass detail_view=None so the shader shows the baked base only.
    bake_cache: HashMap<u64, (wgpu::TextureView, wgpu::Texture)>,
    /// Memoized alpha-test classification per diffuse tag (true = foliage cutout).
    alpha_class: HashMap<u32, bool>,
    /// Per diffuse tag: does the diffuse alpha carry real transparent coverage?
    /// Gates the alpha_test_map material flag so spec-mask structure isn't over-discarded.
    alpha_coverage: HashMap<u32, bool>,
    glass_shader: HashMap<u32, bool>, // per-diffuse-tag "is this a glass shader" cache
    /// Per diffuse tag — is the alpha a REAL specular/gloss mask (BC2/BC3) vs no-alpha
    /// (BC1 → sampled a=1.0)? Gates the shader spec_mask so matte BC1 ground/walls don't
    /// reflect the blue sky as per-pixel sparkle ("rainbow"). Keyed by diffuse tag.
    spec_mask_tags: HashMap<u32, bool>,
    /// Decoded DM/SDM lightmap-atlas bitmaps keyed by (tag, submap), for the per-texel
    /// lightmap bake. None = decode failed (cached to avoid retry). Mutex so the
    /// parallel per-BSP geometry pre-decode can share it across rayon worker threads.
    // Arc the decoded atlas bitmaps so cache HITS clone a cheap pointer, not the
    // whole multi-MB Vec — instance-heavy BSPs (Ivory ~2131 meshes) were deep-cloning the
    // atlas per mesh (~176s of memcpy).
    atlas_cache: std::sync::Mutex<HashMap<(u32, u32), Option<std::sync::Arc<(Vec<u8>, u32, u32)>>>>,
    /// LOAD SPEED: per-(sbsp, cluster) PVL fetch cache. `cluster_pvl` is the dominant
    /// decode cost (PVLFETCH ~11s CPU-sum) and is called PER MESH, but many meshes share a cluster
    /// → almost all of it is redundant re-fetches of identical bytes. Fetch once per unique cluster
    /// (Arc-shared across the meshes that use it). Byte-identical (deterministic native fetch).
    pvl_cache: std::sync::Mutex<HashMap<(u32, u32), Option<std::sync::Arc<hms_native::ClusterPvl>>>>,
    /// Diffuse tag -> alpha COVERAGE (classify_diffuse.1), shared by the parallel decode so a
    /// blend-4/6 mesh that will be routed as a lit MARKING never gets the glass lobe lanes.
    cov_cache: std::sync::Mutex<HashMap<u32, bool>>,
    /// GPU lightmap: per-(tag,submap) raw-BC atlas texture, uploaded ONCE per BSP and
    /// shared across every mesh that samples that submap (each mesh makes a cheap view). None =
    /// upload failed (cached to skip retry). Cleared per BSP (dropping frees the GPU textures).
    lm_tex_cache: HashMap<(u32, u32), Option<wgpu::Texture>>,
    /// MAT-19: authored per-material `environment_map` cubes, keyed by bitmap tag. Many opaque
    /// materials share one cube (reflection_cubemap ×28) → build once (mip-major, HDR-in-alpha) and
    /// hand every sharing material a cheap view borrow. None = build failed (cached to skip retry).
    env_cube_cache: HashMap<u32, Option<(wgpu::Texture, wgpu::TextureView)>>,
    /// Geometry pre-decoded IN PARALLEL for the currently-open BSP, indexed by mesh
    /// index; the frame-spread loop `take()`s from here instead of decoding inline. The native
    /// vertex decode (the ~25s single-thread bottleneck on Forge) is thread-safe (the C# app
    /// runs it via Parallel.ForEach), so decoding a whole BSP's meshes across cores collapses it.
    decoded: Vec<Option<DecodedModel>>,
    /// Profiling accumulators (ns): time in GPU mesh upload vs texture decode/upload.
    upload_ns: u128,
    tex_ns: u128,
    picks: Vec<BspPick>,
    done_count: u32,
    total: u32,
    /// hyper-detailed per-material spot-check log (tiling / detail scale / roughness /
    /// spec / albedo tint / cutout / blend / bump / terrain layers / lighting). One line per
    /// unique BSP material_index; written to `hms_materials.log` next to the exe at load-done
    /// so tiling/scale/color/lighting bugs are inspectable without a debugger. `mat_logged`
    /// dedups so each material logs once.
    mat_logged: std::collections::HashSet<i32>,
    mat_log: Vec<String>,
    /// macro (tile) detail tags already re-decoded via decode_bitmap into detail_cache
    /// (the up_bc BC path garbles some of them). Dedups the re-decode to once per tag.
    macro_fixed: std::collections::HashSet<u32>,
    /// DISK CACHE capture: decoded texture bytes stashed during the prewarm (so the write at
    /// load-done can persist them) and each BSP's post-merge decoded meshes serialized to bytes.
    /// Empty when caching is off (already loaded FROM a cache, or HMS_NOCACHE_DISK).
    cap_tex: Vec<CachedTex>,
    cap_bsps: Vec<(u32, u32, Vec<u8>)>, // (sbsp_tag, mesh_count, serialized meshes)
    /// BSP self-illum textures uploaded ONCE per (sbsp, material) at decode time (see
    /// `EmisGpuCache`) instead of one decoded u8 + f16 copy held per MESH until its finalize.
    emis: EmisGpuCache,
    /// True when this load was populated FROM a disk cache — skip decode/prewarm/merge, and don't
    /// re-write the cache. Set by begin_bsp_load when a valid cache is found.
    from_cache: bool,
    /// RELOAD side: per-sbsp decoded+baked+merged meshes read back from the disk cache. The
    /// BSP-open block `remove`s the entry for the sbsp it opens (skipping par-decode/prewarm/merge).
    /// Empty on a cold load. `cap_tex` doubles as the reload texture list (uploaded verbatim).
    cache_meshes: std::collections::HashMap<u32, Vec<DecodedModel>>,
}

/// per-(sbsp, material_index) BSP self-illum state shared by every mesh of that material.
/// A material's emissive bytes are a pure function of its material index (same self_illum map,
/// colour, intensity, curve), but `decode_bsp_mesh` used to decode them PER MESH and hold both the
/// u8 and the f16 HDR copy until the serial finalize uploaded them: on Forge World 22 meshes held
/// 1.0 GB, on cato_nemodia 45 meshes held 3.0 GB, the whole BSP-phase peak. Now the first mesh of a
/// material decodes + uploads the HDR texture right away (`gpu`), records what it found (`done`),
/// and every mesh of that material carries only a dims-stub so `is_some()` routing, the area-light
/// radiance and the finalize are unchanged. Not used while the disk-cache capture needs the bytes.
#[derive(Default)]
struct EmisGpuCache {
    gpu: std::sync::Mutex<HashMap<(u32, i32), Option<(wgpu::TextureView, wgpu::Texture)>>>,
    /// (u8 dims, HDR dims, mean radiance) of a material whose HDR texture is in `gpu`.
    done: std::sync::Mutex<HashMap<(u32, i32), (Option<(u32, u32)>, Option<(u32, u32)>, Option<[f32; 3]>)>>,
}

/// HMS_MEMDIAG sub-phase report for the BSP load: process RSS + what `job.decoded` and the
/// job's decode caches hold right now. Print-only.
fn job_mem_diag(job: &LoadJob, native: &NativeDll, cache: CacheHandle, when: &str) {
    if ev("HMS_MEMDIAG").is_err() { return; }
    let mb = |b: usize| b as f64 / (1024.0 * 1024.0);
    let (rss, hwm, anon) = process_rss_mb();
    let page_cache = native.page_cache_bytes(cache) as usize;
    let (mut verts, mut idx, mut tex, mut n) = (0usize, 0usize, 0usize, 0usize);
    for d in job.decoded.iter().flatten() {
        n += 1;
        verts += d.verts.capacity() * std::mem::size_of::<MeshVertex>();
        idx += d.indices.capacity() * 4;
        for t in [&d.tex, &d.emissive, &d.emissive_hdr] { if let Some(t) = t { tex += t.0.capacity(); } }
    }
    let atlas: usize = job.atlas_cache.lock().map(|m| m.values().flatten().map(|a| a.0.capacity()).sum()).unwrap_or(0);
    let pvl: usize = job.pvl_cache.lock().map(|m| m.values().flatten().map(|p| p.bytes.capacity()).sum()).unwrap_or(0);
    let cap: usize = job.cap_tex.iter().map(|c| c.bytes.capacity()).sum::<usize>() + job.cap_bsps.iter().map(|b| b.2.capacity()).sum::<usize>();
    eprintln!("HMS_MEMDIAG [bsp:{when}] process: rss={rss:.0} MB peak={hwm:.0} MB anon={anon:.0} MB | job.decoded: {n} meshes verts {:.1} MB idx {:.1} MB tex {:.1} MB | atlas_cache {:.1} MB pvl_cache {:.1} MB disk-cache capture {:.1} MB | native page cache {:.0} MB{}",
        mb(verts), mb(idx), mb(tex), mb(atlas), mb(pvl), mb(cap), mb(page_cache), malloc_state_note());
}

/// (Linux, print-only): glibc allocator state -- bytes in use vs freed-but-retained in the
/// arenas vs served by mmap -- so a diag line can tell live data from allocator slack.
#[cfg(target_os = "linux")]
fn malloc_state_note() -> String {
    #[repr(C)]
    struct MallInfo2 { arena: usize, ordblks: usize, smblks: usize, hblks: usize, hblkhd: usize, usmblks: usize, fsmblks: usize, uordblks: usize, fordblks: usize, keepcost: usize }
    extern "C" { fn mallinfo2() -> MallInfo2; }
    let m = unsafe { mallinfo2() };
    let mb = |b: usize| b as f64 / (1024.0 * 1024.0);
    format!(" | malloc: in-use {:.0} MB free-retained {:.0} MB mmapped {:.0} MB", mb(m.uordblks), mb(m.fordblks), mb(m.hblkhd))
}
#[cfg(not(target_os = "linux"))]
fn malloc_state_note() -> String {
    String::new()
}

/// In-flight chunked decorator (foliage) build. Building every grass/leaf set in
/// one frame froze the window; this spreads the decode+upload over frames like the
/// BSP load. `pending` holds the current sbsp's decorator sets; `deco_i` the next
/// set to build.
struct DecoJob {
    sbsps: Vec<u32>,
    sbsp_i: usize,
    pending: Vec<hms_native::DecoratorMesh>,
    deco_i: usize,
    /// decoded+uploaded decorator card bitmaps keyed by bitmap tag. Many grass/leaf SETS
    /// share the same card; uploaded ONCE (sequentially in prebuild) then read IMMUTABLY by the
    /// parallel per-set build (&HashMap is Sync for reads → no Mutex needed).
    tex_cache: HashMap<u32, (wgpu::TextureView, wgpu::Texture)>,
    /// Decorator meshes BUILT IN PARALLEL (start_decorator_job builds every set across
    /// cores up front); decorator_step drains from here in chunks. The per-set build (airprobe
    /// tint + GPU upload) was the ~8.6s serial foliage phase.
    built: Vec<GpuMesh>,
    built_i: usize,
}

/// One chunk of a chunked load: meshes decoded this step + progress. `done` is
/// true on the final step (BSP geometry complete; caller does decorators/decals).
pub struct LoadStep {
    pub opaque: Vec<GpuMesh>,
    pub water: Vec<GpuMesh>,
    pub water_planes: Vec<hms_render::WaterPlane>,
    pub terrain: Vec<GpuMesh>,
    pub alphatest: Vec<GpuMesh>,
    pub blend: Vec<GpuMesh>,
    pub additive: Vec<GpuMesh>,
    pub done: bool,
    pub done_count: u32,
    pub total: u32,
}

/// Terrain-blend material as bitmap TAGS (not decoded bytes) + per-layer tiling.
/// Tags are resolved through the shared tag-keyed texture cache so each unique
/// bitmap is decoded+uploaded ONCE for the whole map — decoding the 4 base maps
/// + blend mask per-mesh (Forge World is nearly all terrain) was ~290ms/mesh.
/// Pod so the disk cache can serialize it as raw bytes (all fields are u32/f32).
#[derive(Clone, Copy, Pod, Zeroable)]
#[repr(C)]
struct TerrainTags {
    base: [u32; 4],
    detail: [u32; 4],
    blend: u32,
    tiles: [[f32; 2]; 4],       // base scale (base_map_m_N_xform.xy)
    base_offset: [[f32; 2]; 4], // base_map_m_N_xform.zw
    detail_tile: [[f32; 2]; 4], // detail_map_m_N_xform.xy
    detail_offset: [[f32; 2]; 4], // detail_map_m_N_xform.zw
    blend_xform: [f32; 4],      // blend_map_xform
    global_tint: [f32; 4],      // global_albedo_tint (rgb)
    active_mask: u32,           // bit n = layer n authored live (0 = unresolved)
    bump: [u32; 4],             // bump_map_m_N tags (normal maps)
    bump_tile: [[f32; 2]; 4],   // bump xform scale
    bump_offset: [[f32; 2]; 4], // bump xform offset
    // MAT-14: per-layer detail_bump_m_N (2nd normal map, added to bump when <4 layers).
    detail_bump: [u32; 4],
    detail_bump_tile: [[f32; 2]; 4],
    detail_bump_offset: [[f32; 2]; 4],
    // MAT-15: distance_blend_base far-distance base->target colour lerp.
    blend_type: u32,            // 0 morph (no-op), 1 distance_blend_base
    blend_slope: f32,
    blend_offset: f32,
    blend_target: [[f32; 4]; 4],// per-layer target colour rgba
    blend_max: [f32; 4],        // per-layer max blend amount
}

/// One pickable object's world-space AABB.
/// TerrainTags for an OBJECT model's rmtr shader (mirror of `bsp_terrain_layers` for BSP
/// materials): per-layer base/detail/bump/detail_bump bitmaps by usage + their xforms and the blend map
/// from the model shader constants. None when no base layer resolves.
fn build_model_terrain_tags(native: &NativeDll, model: hms_native::ModelHandle, sh: i32) -> Option<TerrainTags> {
    let valid = |t: u32| t != 0 && t != 0xFFFF_FFFF;
    let sc = native.model_shader_constants(model, sh);
    let xf = |name: &str| -> [f32; 4] {
        sc.as_ref().and_then(|c| c.real(name)).filter(|v| v.iter().all(|x| x.is_finite())).unwrap_or([1.0, 1.0, 0.0, 0.0])
    };
    let bm = |u: &str| native.model_shader_bitmap_by_usage(model, sh, u);
    let (mut base, mut detail, mut bump, mut dbump) = ([0xFFFF_FFFFu32; 4], [0xFFFF_FFFFu32; 4], [0xFFFF_FFFFu32; 4], [0xFFFF_FFFFu32; 4]);
    let (mut tiles, mut base_offset, mut detail_tile, mut detail_offset) = ([[1.0f32; 2]; 4], [[0.0f32; 2]; 4], [[1.0f32; 2]; 4], [[0.0f32; 2]; 4]);
    let (mut bump_tile, mut bump_offset, mut dbump_tile, mut dbump_offset) = ([[1.0f32; 2]; 4], [[0.0f32; 2]; 4], [[1.0f32; 2]; 4], [[0.0f32; 2]; 4]);
    for l in 0..4 {
        base[l] = bm(&format!("base_map_m_{l}"));
        detail[l] = bm(&format!("detail_map_m_{l}"));
        bump[l] = bm(&format!("bump_map_m_{l}"));
        dbump[l] = bm(&format!("detail_bump_m_{l}"));
        let x = xf(&format!("base_map_m_{l}")); tiles[l] = [x[0], x[1]]; base_offset[l] = [x[2], x[3]];
        let x = xf(&format!("detail_map_m_{l}")); detail_tile[l] = [x[0], x[1]]; detail_offset[l] = [x[2], x[3]];
        let x = xf(&format!("bump_map_m_{l}")); bump_tile[l] = [x[0], x[1]]; bump_offset[l] = [x[2], x[3]];
        let x = xf(&format!("detail_bump_m_{l}")); dbump_tile[l] = [x[0], x[1]]; dbump_offset[l] = [x[2], x[3]];
    }
    if !base.iter().any(|&t| valid(t)) { return None; }
    let active_mask = (0..4).filter(|&l| valid(base[l])).fold(0u32, |m, l| m | (1 << l));
    Some(TerrainTags {
        base, detail, blend: bm("blend_map"), tiles, base_offset, detail_tile, detail_offset,
        blend_xform: xf("blend_map"),
        global_tint: sc.as_ref().and_then(|c| c.real("global_albedo_tint")).unwrap_or([1.0; 4]),
        active_mask, bump, bump_tile, bump_offset,
        detail_bump: dbump, detail_bump_tile: dbump_tile, detail_bump_offset: dbump_offset,
        blend_type: 0, blend_slope: 0.0, blend_offset: 0.0, blend_target: [[0.0; 4]; 4], blend_max: [0.0; 4],
    })
}

#[derive(Clone, Copy)]
struct PickEntry {
    datum: u32,
    min: Vec3,
    max: Vec3,
    /// The object's render-model tag + world transform, so pick can refine an
    /// AABB hit to the ACTUAL mesh triangles (a large object's box front-face can be
    /// closer than a small marker's box → AABB picking selected the object behind).
    mode_tag: u32,
    xform: Mat4,
    /// For a HIDDEN BLOCKER (render model draws nothing in-game) the OBJECT tag
    /// whose collision/physics hull (`coll_cache` / `phmo_cache`) IS the object's shape. Every
    /// consumer -- click pick, box-select AABB, OBB for flush/mate/array, selection wireframe,
    /// magnet raycast -- uses that hull instead of the degenerate 0.1 wu render nub. None = normal
    /// object (render mesh).
    hull: Option<u32>,
    /// #wire-attach An ATTACHMENT entry: an hlmt model-variant CHILD object (a rocket Warthog's
    /// turret, a Revenant's plasma gun, a Shade's cannon) posed on its parent's marker. It carries
    /// the PARENT's datum and the CHILD's render-model tag, so clicking the turret selects the
    /// vehicle and the parent's bounds / oriented box / selection wireframe include it.
    att: bool,
}

/// BSP-baked airprobe SH grid + its mean ambient — the object-lighting analog
/// of the engine's per-position baked ambient. Port of the C# `LightProbeSampler`
/// (OBJECT_PROBE_RE): objects sample the nearest probe and tint their ambient by
/// `probe.ambient / gridMean`, so an object "sits" in the world (darker in
/// shadow pockets, brighter in open sun) instead of being flat-lit. Empty grid →
/// identity tint (never invents a probe).
/// OBJ-PROBE: blended dual-vMF probe for one object (see `LightProbeGrid::sample_vmf`).
#[derive(Clone, Copy, Debug)]
struct ProbeVmf {
    dom_dir: [f32; 3], dom_rgb: [f32; 3], fill_rgb: [f32; 3], bandwidth: f32, mask: f32,
    /// FILL lobe direction (airprobe blends carry one; lightmap texel / PVL samples = zero,
    /// which the engine merge treats as "lobe dir = dir0").
    fill_dir: [f32; 3],
    /// Bounce light from the ray-hit surface (doc 16 §3.3): dir = −N_hit, colour = 10·A·E.
    /// Zero when the sample came from airprobes or the hit material has no albedo.
    bounce_dir: [f32; 3],
    bounce_rgb: [f32; 3],
    /// Produced by the engine raycast pipeline → the shader does the lobes+sun merge and
    /// adds the bounce (packed `obj_light` lane). false = legacy 4-nearest sample (key = dominant lobe).
    engine: bool,
    /// Where the sample came from (diagnostic only, not a GPU lane): 0 unknown/legacy,
    /// 1 lightmap texel (per-pixel), 2 PVL lobes, 3 PVL colour, 4 instance single probe, 5 airprobes.
    src: u8,
    /// The chmt per-OBJECT-TYPE lighting variables that post-process this sample every frame
    /// (engine sub_1407E9430, doc 16 §2b): [min luminance, max contrast, max contrast distant, bounce to
    /// ambient, bounce scale]. Default (no chmt tag) = the engine's [-1, 0, 0, 2, 1]. Set by
    /// `object_probe_for_uncached` from the obje type; `ProbeVmf::default()` carries the engine defaults.
    chmt: [f32; 5],
    /// Datum of the placed object whose sample this one ADOPTED (the lighting ray hit that
    /// object before the BSP); u32::MAX = none. Drives the probe-cache dependency invalidation.
    parent: u32,
}
/// Engine defaults when the map has no chmt tag / the type is out of range
/// (sub_1407E9430: v7 = -1 min luminance, v9 = 0 max contrast, 2.0 bounce-to-ambient, 1.0 bounce scale).
const CHMT_DEFAULT: [f32; 5] = [-1.0, 0.0, 0.0, 2.0, 1.0];
impl Default for ProbeVmf {
    fn default() -> Self {
        ProbeVmf { dom_dir: [0.0; 3], dom_rgb: [0.0; 3], fill_rgb: [0.0; 3], bandwidth: 0.0, mask: 0.0, fill_dir: [0.0; 3],
            bounce_dir: [0.0; 3], bounce_rgb: [0.0; 3], engine: false, src: 0, chmt: CHMT_DEFAULT, parent: u32::MAX }
    }
}

/// A placed object as a ray target for other objects' lighting rays (doc 16 §1.4: the
/// engine's collision raycast hits objects; "hit another object -> copy that object's cached lighting").
struct ObjRayTarget {
    info: ObjectInfo,
    /// world -> model space (the placement matrix inverse; scale included)
    inv: Mat4,
    wmin: Vec3,
    wmax: Vec3,
}
/// obje types the engine's object-lighting ray can hit (collision object_flags 0x2181 >> 1 =
/// 0x10C0: 6 scenery, 7 machine, 12 giant). `None` (unreadable obje meta) = not a target.
fn obj_ray_target_type(ty: Option<u32>) -> bool { matches!(ty, Some(6) | Some(7) | Some(12)) }
/// Raw dual-vMF (16 halves -> f32) of an instance's single probe: Lbsp+0x60 instances[ord]
/// (12 B, probe index i16 @+4) -> Lbsp+0x6C probes[i] (36 B, terms @+0) — the layout the native
/// `ExtractInstanceProbeInner` evaluates. None = not single-probe / unreadable.
fn instance_probe_raw(native: &NativeDll, cache: CacheHandle, sbsp_tag: u32, ordinal: u32) -> Option<[f32; 16]> {
    if ordinal == 0xFFFF_FFFF { return None; }
    let lbsp = native.lbsp_active_tag(cache, sbsp_tag)?;
    let hdr = native.tag_meta(cache, lbsp, 0x60, 0x18)?;
    let rd = |o: usize| u32::from_le_bytes([hdr[o], hdr[o + 1], hdr[o + 2], hdr[o + 3]]);
    let (icnt, iptr) = (rd(0), rd(4));
    let (pcnt, pptr) = (rd(0xC), rd(0x10));
    if ordinal >= icnt || iptr == 0 || pcnt == 0 || pptr == 0 || icnt > 0x40000 || pcnt > 0x40000 { return None; }
    // raw tag pointers are compressed (expanded by the native side), so whole blocks are read and
    // indexed in bytes here rather than offsetting the raw pointer.
    let inst = native.tag_ptr_bytes(cache, iptr, icnt * 12)?;
    let io = ordinal as usize * 12;
    let pi = i16::from_le_bytes([inst[io + 4], inst[io + 5]]);
    if pi < 0 || pi as u32 >= pcnt { return None; }
    let probes = native.tag_ptr_bytes(cache, pptr, pcnt * 36)?;
    let po = pi as usize * 36;
    let mut t = [0f32; 16];
    for (k, v) in t.iter_mut().enumerate() { *v = half::f16::from_le_bytes([probes[po + k * 2], probes[po + k * 2 + 1]]).to_f32(); }
    if !t.iter().all(|v| v.is_finite()) { return None; }
    Some(t)
}
/// A raw 16-term dual-vMF (airprobe / instance probe / sh probe layout) as a `ProbeVmf`:
/// directions normalised (zero fill dir kept zero), masks clamped, bandwidth-0 guarded like the engine
/// blend output.
fn probe_vmf_from_terms(t: &[f32; 16]) -> ProbeVmf {
    let nrm = |v: [f32; 3], fallback: [f32; 3]| { let d = Vec3::from(v); if d.length() > 1e-4 { d.normalize().into() } else { fallback } };
    ProbeVmf {
        dom_dir: nrm([t[0], t[1], t[2]], [0.0, 0.0, 1.0]),
        dom_rgb: [t[4].max(0.0), t[5].max(0.0), t[6].max(0.0)],
        fill_rgb: [t[12].max(0.0), t[13].max(0.0), t[14].max(0.0)],
        bandwidth: if t[7] > 0.0 { t[7] } else { 1.0 },
        mask: t[3].clamp(0.0, 1.0),
        fill_dir: nrm([t[8], t[9], t[10]], [0.0, 0.0, 0.0]),
        engine: true, src: 4, ..Default::default()
    }
}
/// Pose hash of a placement for the probe-dependency bookkeeping (datum-independent).
fn obj_pose_hash(o: &ObjectInfo, scale: f32) -> u64 {
    let mut h = 0xcbf2_9ce4_8422_2325u64;
    let mut mix = |v: u64| { h ^= v; h = h.wrapping_mul(0x0100_0000_01b3); };
    mix(o.mode_tag as u64); mix(scale.to_bits() as u64);
    for c in o.pos { mix(c.to_bits() as u64); }
    for c in o.up { mix(c.to_bits() as u64); }
    for c in o.fwd { mix(c.to_bits() as u64); }
    h
}

/// One BSP's cluster cubemaps (see SceneController::cluster_cubes).
struct ClusterCubes {
    sbsp: u32,
    /// The `<scnr path>_<bsp basename>_cubemaps` bitmap tag (0 = none found).
    tag: u32,
    submaps: u32,
    /// (cluster index, world AABB min, max) over the cluster's render meshes.
    boxes: Vec<(u32, Vec3, Vec3)>,
}

/// What an object-lighting ray finds at a BSP hit (doc 16 §1.4) — per render mesh.
enum LmLight {
    /// Per-pixel lightmap: the NEAREST texel of the DM/SDM atlas submaps, decoded as HLSL DecompressVMF
    /// (fIntensity = exp2(−9·DM.r), dom = (s0 + 2·s1 − 1)·fInt, fill = s2·fInt, dir from the slice alphas,
    /// vis = DM.g) × hdr × K (K = Lbsp+0x18, the per-BSP compress constant).
    PerPixel { dm: (u32, u32), sdm: (u32, u32), hdr: f32, k: f32 },
    /// Per-vertex lighting: the nearest vertex's raw PVL lobes (bandwidth 1, mask = baked vis).
    Pvl,
    /// Per-vertex lighting whose raw lobes weren't captured (map-cache load): the nearest vertex's baked
    /// irradiance re-expressed as an isotropic fill lobe.
    PvlColor,
    /// Instance single probe: the raw dual-vMF terms when readable (the engine copies them
    /// into the sample), else its up-facing baked ambient as an isotropic fill lobe.
    Probe([f32; 3], Option<[f32; 16]>),
    /// No lighting data — the hit yields no sample (engine return 2/3 → next ray).
    None,
}
/// One run of PVL-lit vertices [start, start+count) whose lobes decode from `pvl` at vertex id
/// (i - start) with `scale`: the raw 6-byte-per-vertex lighting VB (Arc-shared with every mesh of the
/// same cluster) instead of 40 B of pre-decoded lobes per vertex. `decode_pvl_lobes` at lookup time
/// is the exact call the load used to make, so the sampled values are identical.
#[derive(Clone)]
struct PvlLobeSrc {
    start: u32,
    count: u32,
    pvl: std::sync::Arc<hms_native::ClusterPvl>,
    scale: f32,
}

fn pvl_src_len(src: &[PvlLobeSrc]) -> usize {
    src.iter().map(|s| s.count as usize).sum()
}

impl LmSampleMesh {
    /// The raw PVL lobes of vertex `i` (Pvl meshes only), decoded from the run that holds it --
    /// exactly what the load computed per vertex before.
    fn lobe(&self, i: usize) -> Option<crate::lightprobe::PvlLobe> {
        let s = self.lobe_src.iter().find(|s| i >= s.start as usize && i < (s.start + s.count) as usize)?;
        Some(crate::lightprobe::decode_pvl_lobes(&s.pvl.bytes, i - s.start as usize, s.pvl.pvb_offset, s.scale))
    }
}

struct LmSampleMesh {
    light: LmLight,
    /// Submap-local lightmap UV per vertex (PerPixel only).
    uv2: Vec<[f32; 2]>,
    /// Raw PVL lobe source runs (Pvl only) -- see `PvlLobeSrc`.
    lobe_src: Vec<PvlLobeSrc>,
    /// Baked vertex colours (PvlColor only).
    colors: Vec<[f32; 4]>,
    /// Bounce albedo sources: diffuse bitmap tag; terrain (base[4], detail[4], blend) when shader_terrain.
    diffuse: u32,
    terrain: Option<([u32; 4], [u32; 4], u32)>,
    /// Texture UV per vertex (terrain meshes only) so the bounce albedo is the blend
    /// AT THE HIT POINT (engine sub_1406BB900 samples blend_map + the layer base maps at the hit
    /// texcoord), not the blend-map mean of the whole material. Empty for non-terrain meshes.
    uv1: Vec<[f32; 2]>,
    /// (blend_map xform, per-layer base_map xform [tile.x, tile.y, off.x, off.y],
    /// authored active-layer mask) for the per-hit terrain sample. None when not terrain.
    terrain_xf: Option<([f32; 4], [[f32; 4]; 4], u32)>,
    /// The material's authored albedo_color.rgb (engine bounce albedo = base_map x
    /// albedo_color for non-terrain materials); [1,1,1] when unauthored / terrain.
    albedo_color: [f32; 3],
    /// The material's render_method tag (diag only: names the shader the ray hit).
    shader: u32,
}

/// Octahedral unit-vector encode (mirrors `oct_decode` in mesh.rs).
pub(crate) fn oct_encode(v: Vec3) -> [f32; 2] {
    let l = v.x.abs() + v.y.abs() + v.z.abs();
    if !(l > 1e-8) { return [0.0, 0.0]; }
    let mut p = [v.x / l, v.y / l];
    if v.z < 0.0 {
        let (x, y) = (p[0], p[1]);
        p[0] = (1.0 - y.abs()) * if x >= 0.0 { 1.0 } else { -1.0 };
        p[1] = (1.0 - x.abs()) * if y >= 0.0 { 1.0 } else { -1.0 };
    }
    p
}
/// Two f32 → one u32 of packed f16 (x = low half), the WGSL `unpack2x16float` layout.
pub(crate) fn pack_f16x2(x: f32, y: f32) -> u32 {
    let lo = half::f16::from_f32(x).to_bits() as u32;
    let hi = half::f16::from_f32(y).to_bits() as u32;
    lo | (hi << 16)
}
/// The per-instance GPU lanes for a probe: ([dom_dir, bandwidth, dom_rgb, mask], packed
/// obj_light lane). bandwidth ≤ 0 → all zero (no probe). Legacy (non-engine) probes leave the packed lane
/// zero so mesh_shade keeps the old key = dominant-lobe path.
/// Packed layout (mirrors `obj_engine` in mesh_shade):
///   .x = pack4x8snorm(oct(fill_dir).xy, oct(bounce_dir).xy)     (8-bit octahedral, ~0.5 deg)
///   .y = pack4x8unorm(bounce_to_ambient/4, bounce_scale, max_contrast/4, max_contrast_distant/4)
///   .z = f16x2(bounce.r, bounce.g)   RAW bounce (10·A·E), unscaled
///   .w = f16x2(bounce.b, flag) with flag = (1 | 2) + 4·round(max(min_lum,0)·500)   (2 = fill dir is ZERO)
fn probe_lanes(pv: &ProbeVmf) -> ([f32; 8], [u32; 4]) {
    if !(pv.bandwidth > 0.0) { return ([0.0; 8], [0; 4]); }
    let lane0 = [pv.dom_dir[0], pv.dom_dir[1], pv.dom_dir[2], pv.bandwidth, pv.dom_rgb[0], pv.dom_rgb[1], pv.dom_rgb[2], pv.mask];
    if !pv.engine { return (lane0, [0; 4]); }
    let fd = Vec3::from(pv.fill_dir);
    let has_fill_dir = fd.length_squared() > 1e-6;
    let od = oct_encode(if has_fill_dir { fd.normalize() } else { Vec3::Z });
    let bd = Vec3::from(pv.bounce_dir);
    let ob = oct_encode(if bd.length_squared() > 1e-6 { bd.normalize() } else { Vec3::Z });
    let base = if has_fill_dir { 1.0 } else { 2.0 }; // 2 = fill dir is ZERO (texel/PVL sample) → merge uses dir0
    let min_lum_code = (pv.chmt[0].max(0.0) * 500.0).round().min(2000.0);
    let flag = base + 4.0 * min_lum_code;
    let snorm8 = |v: f32| (((v.clamp(-1.0, 1.0) * 127.0).round() as i32) as u32) & 0xFF;
    let unorm8 = |v: f32| ((v.clamp(0.0, 1.0) * 255.0).round() as u32) & 0xFF;
    (lane0, [
        snorm8(od[0]) | (snorm8(od[1]) << 8) | (snorm8(ob[0]) << 16) | (snorm8(ob[1]) << 24),
        unorm8(pv.chmt[3] * 0.25) | (unorm8(pv.chmt[4]) << 8) | (unorm8(pv.chmt[1] * 0.25) << 16) | (unorm8(pv.chmt[2] * 0.25) << 24),
        pack_f16x2(pv.bounce_rgb[0].max(0.0), pv.bounce_rgb[1].max(0.0)),
        pack_f16x2(pv.bounce_rgb[2].max(0.0), flag),
    ])
}
/// One cell of `SceneController::light_bake_scan` — the light a Forge piece resting on
/// the ground at (x,y) would be shaded with. All colours are LINEAR HDR (renderer units, pre-exposure).
#[derive(Clone, Copy, Debug, Default)]
pub struct LightBakeCell {
    pub x: f32,
    pub y: f32,
    /// Ground height under the cell (the down-ray hit); only meaningful when `valid`.
    pub z: f32,
    /// false = no ground below the cell, or no lighting data at the hit (skybox / void / no probe).
    pub valid: bool,
    /// Merged KEY light (dominant lobe ⊕ analytical sun × sun mask, doc 16 §2): colour + direction.
    pub key_rgb: [f32; 3],
    pub key_dir: [f32; 3],
    /// Fill lobe colour incl. the ×2 surface bounce (what the shader adds as ambient).
    pub fill_rgb: [f32; 3],
    /// Object colour estimate for a flat, upward-facing white face: irradiance(+Z) + key·max(0,cosθ)/π.
    pub color: [f32; 3],
    /// Sun visibility mask at the sample (0 shadow … 1 full sun).
    pub mask: f32,
    /// Sample source: 0 none, 1 lightmap texel, 2 PVL lobes, 3 PVL colour, 4 instance probe, 5 airprobes.
    pub kind: u8,
}
impl LightBakeCell {
    pub fn lum(&self) -> f32 { self.color[0] * 0.299 + self.color[1] * 0.587 + self.color[2] * 0.114 }
    /// Display colour (0-255) = saturate(sqrt(colour × exposure)) — the renderer's gamma2 output op.
    pub fn display(&self, exposure: f32) -> [u8; 3] {
        let mut o = [0u8; 3];
        for k in 0..3 { o[k] = ((self.color[k] * exposure).max(0.0).sqrt().min(1.0) * 255.0 + 0.5) as u8; }
        o
    }
    pub fn kind_name(&self) -> &'static str {
        match self.kind { 1 => "lightmap", 2 => "pvl", 3 => "pvl-colour", 4 => "instance-probe", 5 => "airprobe", _ => "none" }
    }
}

/// A top-down grid of `LightBakeCell`s (see `SceneController::light_bake_scan`).
#[derive(Clone, Debug, Default)]
pub struct LightBakeScan {
    pub x0: f32,
    pub y0: f32,
    pub step: f32,
    pub nx: usize,
    pub ny: usize,
    /// Probe radius the cells were sampled with (object origin = ground + radius).
    pub radius: f32,
    /// Row-major, `cells[j * nx + i]` = (x0 + i·step, y0 + j·step).
    pub cells: Vec<LightBakeCell>,
    /// The scene's analytical sun colour (HDR) at scan time.
    pub sun_rgb: [f32; 3],
    /// Exposure used by `display()` / the PNG / `find` (auto key from the scan; override freely).
    pub exposure: f32,
    pub elapsed_ms: f32,
}
impl LightBakeScan {
    pub fn valid_count(&self) -> usize { self.cells.iter().filter(|c| c.valid).count() }
    /// CSV: x,y,z,r,g,b,mask,fill_r,fill_g,fill_b,kind[,lin_r,lin_g,lin_b,key_r,key_g,key_b] — r,g,b are the
    /// DISPLAY values (0-255, tonemapped with `exposure`); fill/lin/key are linear HDR. Invalid cells omitted.
    pub fn to_csv(&self) -> String {
        let mut s = String::with_capacity(self.cells.len() * 64);
        s.push_str("x,y,z,r,g,b,mask,fill_r,fill_g,fill_b,kind,lin_r,lin_g,lin_b,key_r,key_g,key_b\n");
        for c in self.cells.iter().filter(|c| c.valid) {
            let d = c.display(self.exposure);
            s.push_str(&format!("{:.2},{:.2},{:.3},{},{},{},{:.3},{:.4},{:.4},{:.4},{},{:.5},{:.5},{:.5},{:.4},{:.4},{:.4}\n",
                c.x, c.y, c.z, d[0], d[1], d[2], c.mask, c.fill_rgb[0], c.fill_rgb[1], c.fill_rgb[2], c.kind_name(),
                c.color[0], c.color[1], c.color[2], c.key_rgb[0], c.key_rgb[1], c.key_rgb[2]));
        }
        s
    }
    /// Top-down RGBA image: +x right, +y UP, `scale` px per cell, thin grid every `grid_wu` wu with
    /// axis labels in the margins and a legend strip at the bottom. `scale` 0 → auto (image ≥ ~560 px).
    pub fn render_image(&self, scale: usize, grid_wu: f32) -> LightBakeImage {
        let mut img = LightBakeImage::new_grid(self.nx, self.ny, scale);
        let (ml, mt, s) = (img.ox, img.oy, img.scale);
        // cells (row 0 at the top = y1)
        for j in 0..self.ny {
            for i in 0..self.nx {
                let c = &self.cells[j * self.nx + i];
                let col = if c.valid { let d = c.display(self.exposure); [d[0], d[1], d[2], 255] } else { [44, 0, 64, 255] };
                img.fill_rect(ml + i * s, mt + (self.ny - 1 - j) * s, s, s, col);
            }
        }
        let info = format!("EXPO {:.3} STEP {:.2} R {:.2} PURPLE=NO GROUND", self.exposure, self.step, self.radius);
        img.draw_frame(self.x0, self.y0, self.step, grid_wu, &info);
        img
    }
}

impl LightBakeImage {
    /// Allocate a framed top-down image for an `nx × ny` cell grid (`scale` 0 → auto, image ≥ ~560 px wide):
    /// margins for y labels (left), x labels + legend (bottom). Grid area starts at (ox, oy).
    fn new_grid(nx: usize, ny: usize, scale: usize) -> LightBakeImage {
        let fs = 2usize; // font pixel scale (glyph 6×10)
        let cw = 4 * fs; // char pitch
        let s = if scale == 0 { ((560 + nx.max(1) - 1) / nx.max(1)).clamp(1, 8) } else { scale.clamp(1, 16) };
        let (ml, mt, mr) = (6 * cw + 4, 4usize, 6usize);
        let (mb_labels, mb_legend) = (6 * fs + 6, 5 * fs * 2 + 14);
        let (gw, gh) = (nx * s, ny * s);
        let (w, h) = (ml + gw + mr, mt + gh + mb_labels + mb_legend);
        let mut img = LightBakeImage { w, h, rgba: vec![0u8; w * h * 4], ox: ml, oy: mt, scale: s, nx, ny };
        img.fill_rect(0, 0, w, h, [24, 24, 28, 255]);
        img
    }
    /// Grid lines every `grid_wu` wu (+x right, +y up; cell (0,0) at world (x0, y0)), axis labels, and the
    /// legend strip (display-luminance gradient + `info`).
    fn draw_frame(&mut self, x0: f32, y0: f32, step: f32, grid_wu: f32, info: &str) {
        let fs = 2usize;
        let cw = 4 * fs;
        let (ml, mt, s, w) = (self.ox, self.oy, self.scale, self.w);
        let (gw, gh) = (self.nx * s, self.ny * s);
        let mb_labels = 6 * fs + 6;
        let mr = 6usize;
        let grid = if grid_wu.is_finite() && grid_wu > 0.0 { grid_wu } else { 25.0 };
        let (x1, y1) = (x0 + (self.nx.max(1) - 1) as f32 * step, y0 + (self.ny.max(1) - 1) as f32 * step);
        let img = self;
        // label every k-th grid line so neighbouring labels never overlap (grid lines stay on every line)
        let grid_px = (grid / step * s as f32).max(1.0);
        let max_chars = [x0, x1, y0, y1].iter().map(|v| format!("{}", v.round() as i64).len()).max().unwrap_or(3);
        let kx = ((max_chars * cw + 6) as f32 / grid_px).ceil().max(1.0) as i64;
        let ky = ((5 * fs + 4) as f32 / grid_px).ceil().max(1.0) as i64;
        let mut gx = (x0 / grid).ceil() * grid;
        while gx <= x1 + 1e-3 {
            let px = ml + (((gx - x0) / step) * s as f32).round() as usize;
            if px < ml + gw {
                img.blend_col(px, mt, gh, [255, 255, 255], 0.35);
                if ((gx / grid).round() as i64).rem_euclid(kx) == 0 {
                    let label = format!("{}", gx.round() as i64);
                    let tx = px.saturating_sub(label.len() * cw / 2).max(ml).min(w.saturating_sub(label.len() * cw + 1));
                    img.text(tx, mt + gh + 3, &label, fs, [230, 230, 230]);
                }
            }
            gx += grid;
        }
        let mut gy = (y0 / grid).ceil() * grid;
        while gy <= y1 + 1e-3 {
            let py = mt + gh - 1 - (((gy - y0) / step) * s as f32).round() as usize;
            if py >= mt && py < mt + gh {
                img.blend_row(ml, py, gw, [255, 255, 255], 0.35);
                if ((gy / grid).round() as i64).rem_euclid(ky) == 0 {
                    let label = format!("{}", gy.round() as i64);
                    let tx = ml.saturating_sub(label.len() * cw + 3);
                    img.text(tx, py.saturating_sub(5 * fs / 2).max(mt), &label, fs, [230, 230, 230]);
                }
            }
            gy += grid;
        }
        img.text(ml + gw / 2, mt + gh + 3 + 6 * fs, "X", fs, [255, 200, 120]);
        img.text(2, mt + gh / 2, "Y", fs, [255, 200, 120]);
        // legend: display-luminance gradient + settings line
        let ly = mt + gh + mb_labels + 4;
        let lw = gw.min(w - ml - mr);
        for i in 0..lw {
            let v = (i as f32 / (lw.max(2) - 1) as f32 * 255.0) as u8;
            img.fill_rect(ml + i, ly, 1, 5 * fs, [v, v, v, 255]);
        }
        img.text(ml, ly + 5 * fs + 2, "DARK", fs, [200, 200, 200]);
        img.text(ml + lw.saturating_sub(6 * cw), ly + 5 * fs + 2, "BRIGHT", fs, [200, 200, 200]);
        img.text(ml + 7 * cw, ly + 5 * fs + 2, info, fs, [180, 200, 255]);
    }
}

/// Rendered scan (see `LightBakeScan::render_image`). `ox/oy/scale` map image pixels
/// back to cells: cell i = (px − ox)/scale, cell j = ny − 1 − (py − oy)/scale.
#[derive(Clone, Debug, Default)]
pub struct LightBakeImage {
    pub w: usize,
    pub h: usize,
    pub rgba: Vec<u8>,
    pub ox: usize,
    pub oy: usize,
    pub scale: usize,
    pub nx: usize,
    pub ny: usize,
}
impl LightBakeImage {
    /// Cell (i, j) under image pixel (px, py), if inside the grid area.
    pub fn cell_at(&self, px: f32, py: f32) -> Option<(usize, usize)> {
        if px < self.ox as f32 || py < self.oy as f32 || self.scale == 0 { return None; }
        let i = ((px - self.ox as f32) / self.scale as f32) as usize;
        let r = ((py - self.oy as f32) / self.scale as f32) as usize;
        if i < self.nx && r < self.ny { Some((i, self.ny - 1 - r)) } else { None }
    }
    /// Image pixel (centre) of cell (i, j).
    pub fn pixel_of(&self, i: usize, j: usize) -> (f32, f32) {
        ((self.ox + i * self.scale) as f32 + self.scale as f32 * 0.5, (self.oy + (self.ny.saturating_sub(1 + j)) * self.scale) as f32 + self.scale as f32 * 0.5)
    }
    fn fill_rect(&mut self, x: usize, y: usize, w: usize, h: usize, c: [u8; 4]) {
        for yy in y..(y + h).min(self.h) { for xx in x..(x + w).min(self.w) { let o = (yy * self.w + xx) * 4; self.rgba[o..o + 4].copy_from_slice(&c); } }
    }
    fn blend_px(&mut self, x: usize, y: usize, c: [u8; 3], a: f32) {
        if x >= self.w || y >= self.h { return; }
        let o = (y * self.w + x) * 4;
        for k in 0..3 { self.rgba[o + k] = (self.rgba[o + k] as f32 * (1.0 - a) + c[k] as f32 * a) as u8; }
    }
    fn blend_col(&mut self, x: usize, y: usize, h: usize, c: [u8; 3], a: f32) { for yy in y..y + h { self.blend_px(x, yy, c, a); } }
    fn blend_row(&mut self, x: usize, y: usize, w: usize, c: [u8; 3], a: f32) { for xx in x..x + w { self.blend_px(xx, y, c, a); } }
    /// Draw `text` with the embedded 3×5 font (upper-cased; unknown glyphs are blank) at pixel scale `fs`.
    pub fn text(&mut self, x: usize, y: usize, text: &str, fs: usize, c: [u8; 3]) {
        let mut cx = x;
        for ch in text.chars() {
            let g = glyph3x5(ch.to_ascii_uppercase());
            for (row, bits) in g.iter().enumerate() {
                for col in 0..3 {
                    if bits & (0b100 >> col) != 0 { self.fill_rect(cx + col * fs, y + row * fs, fs, fs, [c[0], c[1], c[2], 255]); }
                }
            }
            cx += 4 * fs;
        }
    }
}

/// 3×5 bitmap font (each row = 3 bits, MSB = left) for the scan image's axis labels.
fn glyph3x5(ch: char) -> [u8; 5] {
    match ch {
        '0' => [0b111, 0b101, 0b101, 0b101, 0b111], '1' => [0b010, 0b110, 0b010, 0b010, 0b111],
        '2' => [0b111, 0b001, 0b111, 0b100, 0b111], '3' => [0b111, 0b001, 0b111, 0b001, 0b111],
        '4' => [0b101, 0b101, 0b111, 0b001, 0b001], '5' => [0b111, 0b100, 0b111, 0b001, 0b111],
        '6' => [0b111, 0b100, 0b111, 0b101, 0b111], '7' => [0b111, 0b001, 0b001, 0b001, 0b001],
        '8' => [0b111, 0b101, 0b111, 0b101, 0b111], '9' => [0b111, 0b101, 0b111, 0b001, 0b111],
        'A' => [0b010, 0b101, 0b111, 0b101, 0b101], 'B' => [0b110, 0b101, 0b110, 0b101, 0b110],
        'C' => [0b111, 0b100, 0b100, 0b100, 0b111], 'D' => [0b110, 0b101, 0b101, 0b101, 0b110],
        'E' => [0b111, 0b100, 0b111, 0b100, 0b111], 'F' => [0b111, 0b100, 0b111, 0b100, 0b100],
        'G' => [0b111, 0b100, 0b101, 0b101, 0b111], 'H' => [0b101, 0b101, 0b111, 0b101, 0b101],
        'I' => [0b111, 0b010, 0b010, 0b010, 0b111], 'J' => [0b001, 0b001, 0b001, 0b101, 0b111],
        'K' => [0b101, 0b101, 0b110, 0b101, 0b101], 'L' => [0b100, 0b100, 0b100, 0b100, 0b111],
        'M' => [0b101, 0b111, 0b111, 0b101, 0b101], 'N' => [0b110, 0b101, 0b101, 0b101, 0b101],
        'O' => [0b111, 0b101, 0b101, 0b101, 0b111], 'P' => [0b111, 0b101, 0b111, 0b100, 0b100],
        'Q' => [0b111, 0b101, 0b101, 0b111, 0b001], 'R' => [0b110, 0b101, 0b110, 0b101, 0b101],
        'S' => [0b111, 0b100, 0b111, 0b001, 0b111], 'T' => [0b111, 0b010, 0b010, 0b010, 0b010],
        'U' => [0b101, 0b101, 0b101, 0b101, 0b111], 'V' => [0b101, 0b101, 0b101, 0b101, 0b010],
        'W' => [0b101, 0b101, 0b111, 0b111, 0b101], 'X' => [0b101, 0b101, 0b010, 0b101, 0b101],
        'Y' => [0b101, 0b101, 0b010, 0b010, 0b010], 'Z' => [0b111, 0b001, 0b010, 0b100, 0b111],
        '-' => [0b000, 0b000, 0b111, 0b000, 0b000], '.' => [0b000, 0b000, 0b000, 0b000, 0b010],
        ':' => [0b000, 0b010, 0b000, 0b010, 0b000], '+' => [0b000, 0b010, 0b111, 0b010, 0b000],
        '=' => [0b000, 0b111, 0b000, 0b111, 0b000], '/' => [0b001, 0b001, 0b010, 0b100, 0b100],
        _ => [0; 5],
    }
}

// ===================== Full colour enumeration + palette =====================

/// One enumerated baked-light sample: the object colour a Forge piece would receive at `pos` (a lightmap
/// texel / PVL vertex / instance probe / airprobe), see `SceneController::light_bake_enumerate`.
#[derive(Clone, Copy, Debug, Default)]
pub struct LightBakeSample {
    pub pos: [f32; 3],
    pub normal: [f32; 3],
    /// Linear HDR object colour (flat up-facing white face through the merge, incl. bounce).
    pub color_lin: [f32; 3],
    /// Display colour at the enumeration's exposure (saturate(sqrt(lin × exposure)) × 255).
    pub color_disp: [u8; 3],
    /// 1 lightmap texel, 2 PVL lobes, 3 PVL colour, 4 instance probe, 5 airprobe.
    pub kind: u8,
}
impl LightBakeSample {
    pub fn kind_name(&self) -> &'static str { lb_kind_name(self.kind) }
}
pub fn lb_kind_name(kind: u8) -> &'static str {
    match kind { 1 => "lightmap", 2 => "pvl", 3 => "pvl-colour", 4 => "instance-probe", 5 => "airprobe", _ => "none" }
}

/// Max positions kept per 4-bit display-colour bucket (spread ≥ LB_SPREAD_WU apart).
const LB_BUCKET_SAMPLES: usize = 48;
const LB_SPREAD_WU: f32 = 8.0;
/// Spatial cell size for a bucket's occurrence map (step 3: "where does this colour occur").
const LB_CELL_WU: f32 = 4.0;
const LB_BUCKET_CELLS: usize = 1024;
/// Top-down raster cell size for the "every baked colour on the map" image.
const LB_RASTER_WU: f32 = 2.0;

/// 12-bit bucket key: display colour at 4 bits per channel.
fn lb_bucket_key(d: [u8; 3]) -> u16 { (((d[0] >> 4) as u16) << 8) | (((d[1] >> 4) as u16) << 4) | ((d[2] >> 4) as u16) }

#[derive(Clone, Debug, Default)]
struct LbBucket {
    count: u64,
    kinds: [u64; 6],
    sum_lin: [f64; 3],
    samples: Vec<LightBakeSample>,
    occupied: std::collections::HashSet<(i32, i32)>,
    /// LB_CELL_WU occurrence cells → (count, Σpos).
    cells: std::collections::HashMap<(i32, i32), (u32, [f64; 3])>,
}
impl LbBucket {
    fn add(&mut self, s: &LightBakeSample) {
        self.count += 1;
        self.kinds[(s.kind as usize).min(5)] += 1;
        for k in 0..3 { self.sum_lin[k] += s.color_lin[k] as f64; }
        let sc = ((s.pos[0] / LB_SPREAD_WU).floor() as i32, (s.pos[1] / LB_SPREAD_WU).floor() as i32);
        if self.samples.len() < LB_BUCKET_SAMPLES && self.occupied.insert(sc) { self.samples.push(*s); }
        let cc = ((s.pos[0] / LB_CELL_WU).floor() as i32, (s.pos[1] / LB_CELL_WU).floor() as i32);
        if let Some(e) = self.cells.get_mut(&cc) {
            e.0 += 1; for k in 0..3 { e.1[k] += s.pos[k] as f64; }
        } else if self.cells.len() < LB_BUCKET_CELLS {
            self.cells.insert(cc, (1, [s.pos[0] as f64, s.pos[1] as f64, s.pos[2] as f64]));
        }
    }
    fn merge(&mut self, o: LbBucket) {
        self.count += o.count;
        for k in 0..6 { self.kinds[k] += o.kinds[k]; }
        for k in 0..3 { self.sum_lin[k] += o.sum_lin[k]; }
        for s in o.samples {
            let sc = ((s.pos[0] / LB_SPREAD_WU).floor() as i32, (s.pos[1] / LB_SPREAD_WU).floor() as i32);
            if self.samples.len() < LB_BUCKET_SAMPLES && self.occupied.insert(sc) { self.samples.push(s); }
        }
        for (cc, (n, sp)) in o.cells {
            if let Some(e) = self.cells.get_mut(&cc) { e.0 += n; for k in 0..3 { e.1[k] += sp[k]; } }
            else if self.cells.len() < LB_BUCKET_CELLS { self.cells.insert(cc, (n, sp)); }
        }
    }
    fn mean_lin(&self) -> [f32; 3] {
        let n = self.count.max(1) as f64;
        [(self.sum_lin[0] / n) as f32, (self.sum_lin[1] / n) as f32, (self.sum_lin[2] / n) as f32]
    }
}

#[derive(Clone, Copy, Debug)]
struct LbRasterCell { z: f32, key: u16, up: bool }
/// Top-down raster of the enumerated samples (highest up-facing sample per LB_RASTER_WU cell).
#[derive(Clone, Debug, Default)]
pub struct LightBakeRaster {
    pub x0: f32,
    pub y0: f32,
    pub step: f32,
    pub nx: usize,
    pub ny: usize,
    cells: Vec<LbRasterCell>,
}
impl LightBakeRaster {
    fn new(x0: f32, y0: f32, x1: f32, y1: f32, step: f32) -> Self {
        let nx = (((x1 - x0) / step).floor() as usize + 1).clamp(1, 2048);
        let ny = (((y1 - y0) / step).floor() as usize + 1).clamp(1, 2048);
        Self { x0, y0, step, nx, ny, cells: vec![LbRasterCell { z: f32::MIN, key: 0xFFFF, up: false }; nx * ny] }
    }
    fn add(&mut self, s: &LightBakeSample, key: u16) {
        let i = ((s.pos[0] - self.x0) / self.step).round();
        let j = ((s.pos[1] - self.y0) / self.step).round();
        if i < 0.0 || j < 0.0 || i as usize >= self.nx || j as usize >= self.ny { return; }
        let c = &mut self.cells[j as usize * self.nx + i as usize];
        let up = s.normal[2] > 0.3;
        let better = c.key == 0xFFFF || (up && !c.up) || (up == c.up && s.pos[2] > c.z);
        if better { *c = LbRasterCell { z: s.pos[2], key, up }; }
    }
    /// Splat a triangle's XY footprint (every raster cell whose centre lies inside it) with bucket `key`,
    /// so large flat triangles (sea plane, plateaus) with few texels still paint solid. z is interpolated.
    fn splat_tri(&mut self, tri: &[Vec3; 3], key: u16, up: bool) {
        let (x0, x1) = (tri.iter().map(|p| p.x).fold(f32::MAX, f32::min), tri.iter().map(|p| p.x).fold(f32::MIN, f32::max));
        let (y0, y1) = (tri.iter().map(|p| p.y).fold(f32::MAX, f32::min), tri.iter().map(|p| p.y).fold(f32::MIN, f32::max));
        let i0 = (((x0 - self.x0) / self.step).ceil().max(0.0)) as i64;
        let i1 = (((x1 - self.x0) / self.step).floor()).min(self.nx as f32 - 1.0) as i64;
        let j0 = (((y0 - self.y0) / self.step).ceil().max(0.0)) as i64;
        let j1 = (((y1 - self.y0) / self.step).floor()).min(self.ny as f32 - 1.0) as i64;
        if i1 < i0 || j1 < j0 { return; }
        if (i1 - i0 + 1) * (j1 - j0 + 1) > 1_000_000 { return; }
        let (a, b, c) = (tri[0], tri[1], tri[2]);
        let (v0, v1) = ([b.x - a.x, b.y - a.y], [c.x - a.x, c.y - a.y]);
        let den = v0[0] * v1[1] - v1[0] * v0[1];
        if den.abs() < 1e-8 { return; }
        for j in j0..=j1 {
            let py = self.y0 + j as f32 * self.step;
            for i in i0..=i1 {
                let px = self.x0 + i as f32 * self.step;
                let v2 = [px - a.x, py - a.y];
                let wb = (v2[0] * v1[1] - v1[0] * v2[1]) / den;
                let wc = (v0[0] * v2[1] - v2[0] * v0[1]) / den;
                let wa = 1.0 - wb - wc;
                if wa < -1e-4 || wb < -1e-4 || wc < -1e-4 { continue; }
                let z = a.z * wa + b.z * wb + c.z * wc;
                let cell = &mut self.cells[j as usize * self.nx + i as usize];
                let better = cell.key == 0xFFFF || (up && !cell.up) || (up == cell.up && z > cell.z);
                if better { *cell = LbRasterCell { z, key, up }; }
            }
        }
    }
    fn merge(&mut self, o: &LightBakeRaster) {
        for (c, oc) in self.cells.iter_mut().zip(o.cells.iter()) {
            if oc.key == 0xFFFF { continue; }
            let better = c.key == 0xFFFF || (oc.up && !c.up) || (oc.up == c.up && oc.z > c.z);
            if better { *c = *oc; }
        }
    }
    /// Bucket key + sample z at cell (i, j), if any sample landed there.
    pub fn at(&self, i: usize, j: usize) -> Option<(u16, f32)> {
        if i >= self.nx || j >= self.ny { return None; }
        let c = self.cells[j * self.nx + i];
        if c.key == 0xFFFF { None } else { Some((c.key, c.z)) }
    }
}

/// Per-thread accumulator for the enumeration (merged with `reduce`).
#[derive(Clone, Debug, Default)]
struct LbAccum {
    exposure: f32,
    buckets: std::collections::HashMap<u16, LbBucket>,
    raster: LightBakeRaster,
    counts: [u64; 6],
}
impl LbAccum {
    fn new(raster: &LightBakeRaster, exposure: f32) -> Self {
        Self { exposure, buckets: std::collections::HashMap::new(), raster: LightBakeRaster { cells: raster.cells.clone(), ..*raster }, counts: [0; 6] }
    }
    /// Returns the sample's bucket key.
    fn add(&mut self, mut s: LightBakeSample) -> u16 {
        s.color_disp = lb_display(s.color_lin, self.exposure);
        let key = lb_bucket_key(s.color_disp);
        self.counts[(s.kind as usize).min(5)] += 1;
        self.buckets.entry(key).or_default().add(&s);
        if s.kind != 5 { self.raster.add(&s, key); }
        key
    }
    fn merge(mut self, o: LbAccum) -> Self {
        for k in 0..6 { self.counts[k] += o.counts[k]; }
        for (key, b) in o.buckets { match self.buckets.get_mut(&key) { Some(e) => e.merge(b), None => { self.buckets.insert(key, b); } } }
        self.raster.merge(&o.raster);
        self
    }
}

/// Per-thread caches for `lb_tri_samples`.
#[derive(Default)]
struct LbTriCaches {
    atlas: std::collections::HashMap<usize, Option<LmAtlasImages>>,
    albedo: std::collections::HashMap<usize, [f32; 3]>,
    seen_verts: std::collections::HashSet<(u32, u32)>,
}

/// A palette swatch: one representative achievable baked colour + where it occurs.
#[derive(Clone, Debug, Default)]
pub struct LightBakeSwatch {
    pub disp: [u8; 3],
    pub lin: [f32; 3],
    pub population: u64,
    pub kinds: [u64; 6],
    /// Spread-out example samples (≤ 64, ≥ 8 wu apart).
    pub samples: Vec<LightBakeSample>,
    /// Occurrence cells (LB_CELL_WU grid): mean position + sample count, densest first.
    pub cells: Vec<([f32; 3], u32)>,
    pub hue: f32,
    pub lum: f32,
    pub chroma: f32,
}

/// The ground-truth set of every baked light colour an object can receive on the loaded map, bucketed by
/// display colour (4 bits/channel), plus the quantized palette (`build_palette`) and the top-down raster.
#[derive(Clone, Debug, Default)]
pub struct LightBakeColors {
    pub exposure: f32,
    pub sun_rgb: [f32; 3],
    /// Samples per kind (index = kind).
    pub counts: [u64; 6],
    pub total: u64,
    pub tris: usize,
    pub bucket_count: usize,
    buckets: std::collections::HashMap<u16, LbBucket>,
    pub raster: LightBakeRaster,
    pub swatches: Vec<LightBakeSwatch>,
    bucket_to_swatch: std::collections::HashMap<u16, u16>,
    pub elapsed_ms: f32,
}
fn lb_hue_lum_chroma(d: [u8; 3]) -> (f32, f32, f32) {
    let (r, g, b) = (d[0] as f32 / 255.0, d[1] as f32 / 255.0, d[2] as f32 / 255.0);
    let (mx, mn) = (r.max(g).max(b), r.min(g).min(b));
    let c = mx - mn;
    let hue = if c < 1e-6 { 0.0 } else if mx == r { 60.0 * (((g - b) / c) % 6.0 + 6.0) % 360.0 } else if mx == g { 60.0 * ((b - r) / c + 2.0) } else { 60.0 * ((r - g) / c + 4.0) };
    (hue, 0.299 * r + 0.587 * g + 0.114 * b, c)
}
impl LightBakeColors {
    /// Quantize the bucket set into `n` swatches: weighted k-means in display space (deterministic
    /// k-means++ seeding: heaviest bucket first, then argmax weight·dist²), ordered greys-by-luminance
    /// first, then by hue / luminance.
    fn build_palette(&mut self, n: usize) {
        let pts: Vec<(u16, [f32; 3], f64, [f32; 3])> = self.buckets.iter()
            .map(|(k, b)| { let d = lb_display(b.mean_lin(), self.exposure); (*k, [d[0] as f32, d[1] as f32, d[2] as f32], b.count as f64, b.mean_lin()) })
            .collect();
        self.swatches.clear();
        self.bucket_to_swatch.clear();
        if pts.is_empty() { return; }
        let k = n.clamp(1, pts.len());
        let d2 = |a: [f32; 3], b: [f32; 3]| { let mut s = 0f32; for i in 0..3 { let e = a[i] - b[i]; s += e * e; } s };
        let mut cents: Vec<[f32; 3]> = Vec::with_capacity(k);
        let heaviest = pts.iter().enumerate().max_by(|a, b| a.1 .2.partial_cmp(&b.1 .2).unwrap()).map(|(i, _)| i).unwrap_or(0);
        cents.push(pts[heaviest].1);
        let mut mind: Vec<f32> = pts.iter().map(|p| d2(p.1, cents[0])).collect();
        while cents.len() < k {
            let (bi, _) = pts.iter().enumerate().map(|(i, p)| (i, p.2 * mind[i] as f64)).max_by(|a, b| a.1.partial_cmp(&b.1).unwrap()).unwrap();
            if mind[bi] <= 0.0 { break; }
            cents.push(pts[bi].1);
            for (i, p) in pts.iter().enumerate() { mind[i] = mind[i].min(d2(p.1, pts[bi].1)); }
        }
        let k = cents.len();
        let mut assign = vec![0usize; pts.len()];
        for _it in 0..30 {
            let mut changed = false;
            for (i, p) in pts.iter().enumerate() {
                let mut best = 0; let mut bd = f32::MAX;
                for (c, ce) in cents.iter().enumerate() { let d = d2(p.1, *ce); if d < bd { bd = d; best = c; } }
                if assign[i] != best { assign[i] = best; changed = true; }
            }
            let mut sum = vec![[0f64; 4]; k];
            for (i, p) in pts.iter().enumerate() { let a = assign[i]; for c in 0..3 { sum[a][c] += p.1[c] as f64 * p.2; } sum[a][3] += p.2; }
            for c in 0..k {
                if sum[c][3] > 0.0 { cents[c] = [(sum[c][0] / sum[c][3]) as f32, (sum[c][1] / sum[c][3]) as f32, (sum[c][2] / sum[c][3]) as f32]; }
                else {
                    // empty cluster → re-seed at the point farthest (weighted) from its centre
                    let (bi, _) = pts.iter().enumerate().map(|(i, p)| (i, p.2 * d2(p.1, cents[assign[i]]) as f64)).max_by(|a, b| a.1.partial_cmp(&b.1).unwrap()).unwrap();
                    cents[c] = pts[bi].1; changed = true;
                }
            }
            if !changed { break; }
        }
        // swatches
        let mut sw: Vec<LightBakeSwatch> = (0..k).map(|_| LightBakeSwatch::default()).collect();
        let mut sum_lin = vec![[0f64; 3]; k];
        let mut members: Vec<Vec<u16>> = vec![Vec::new(); k];
        for (i, p) in pts.iter().enumerate() {
            let a = assign[i];
            members[a].push(p.0);
            let b = &self.buckets[&p.0];
            sw[a].population += b.count;
            for c in 0..6 { sw[a].kinds[c] += b.kinds[c]; }
            for c in 0..3 { sum_lin[a][c] += b.sum_lin[c]; }
        }
        for a in 0..k {
            let n = sw[a].population.max(1) as f64;
            sw[a].lin = [(sum_lin[a][0] / n) as f32, (sum_lin[a][1] / n) as f32, (sum_lin[a][2] / n) as f32];
            sw[a].disp = lb_display(sw[a].lin, self.exposure);
            let (h, l, c) = lb_hue_lum_chroma(sw[a].disp);
            sw[a].hue = h; sw[a].lum = l; sw[a].chroma = c;
            // spread-out samples + merged occurrence cells
            let mut occ: std::collections::HashSet<(i32, i32)> = std::collections::HashSet::new();
            let mut cells: std::collections::HashMap<(i32, i32), (u32, [f64; 3])> = std::collections::HashMap::new();
            let mut all: Vec<LightBakeSample> = Vec::new();
            for key in &members[a] {
                let b = &self.buckets[key];
                all.extend_from_slice(&b.samples);
                for (cc, (cnt, sp)) in &b.cells {
                    let e = cells.entry(*cc).or_insert((0, [0.0; 3]));
                    e.0 += cnt; for c in 0..3 { e.1[c] += sp[c]; }
                }
            }
            for s in all {
                let sc = ((s.pos[0] / LB_SPREAD_WU).floor() as i32, (s.pos[1] / LB_SPREAD_WU).floor() as i32);
                if sw[a].samples.len() < 64 && occ.insert(sc) { sw[a].samples.push(s); }
            }
            let mut cv: Vec<([f32; 3], u32)> = cells.into_iter().map(|(_, (cnt, sp))| ([(sp[0] / cnt as f64) as f32, (sp[1] / cnt as f64) as f32, (sp[2] / cnt as f64) as f32], cnt)).collect();
            cv.sort_by(|x, y| y.1.cmp(&x.1));
            cv.truncate(512);
            sw[a].cells = cv;
        }
        // order: greys by luminance, then hue / luminance
        let mut order: Vec<usize> = (0..k).filter(|&a| sw[a].population > 0).collect();
        order.sort_by(|&x, &y| {
            let (gx, gy) = (sw[x].chroma < 0.07, sw[y].chroma < 0.07);
            gy.cmp(&gx)
                .then_with(|| if gx && gy { sw[x].lum.partial_cmp(&sw[y].lum).unwrap() } else { (sw[x].hue / 20.0).floor().partial_cmp(&(sw[y].hue / 20.0).floor()).unwrap().then(sw[x].lum.partial_cmp(&sw[y].lum).unwrap()) })
        });
        let mut out = Vec::with_capacity(order.len());
        for (new_i, &a) in order.iter().enumerate() {
            for key in &members[a] { self.bucket_to_swatch.insert(*key, new_i as u16); }
            out.push(std::mem::take(&mut sw[a]));
        }
        self.swatches = out;
    }
    /// Swatch index a bucket key maps to.
    fn swatch_of_key(&self, key: u16) -> Option<usize> { self.bucket_to_swatch.get(&key).map(|v| *v as usize) }
    /// Swatch whose display colour is closest to `disp`.
    pub fn nearest_swatch(&self, disp: [u8; 3]) -> Option<usize> {
        self.swatches.iter().enumerate().min_by_key(|(_, s)| { let mut d = 0i64; for k in 0..3 { let e = s.disp[k] as i64 - disp[k] as i64; d += e * e; } d }).map(|(i, _)| i)
    }
    /// Swatch under raster cell (i, j).
    pub fn swatch_at_cell(&self, i: usize, j: usize) -> Option<(usize, f32)> {
        let (key, z) = self.raster.at(i, j)?;
        Some((self.swatch_of_key(key)?, z))
    }
    /// Top-down image painted from the enumerated samples: each raster cell = its swatch's colour; with
    /// `highlight` = Some(swatch) that swatch's cells stay full colour and everything else is dimmed.
    pub fn render_map(&self, scale: usize, grid_wu: f32, highlight: Option<usize>) -> LightBakeImage {
        let r = &self.raster;
        let mut img = LightBakeImage::new_grid(r.nx, r.ny, scale);
        let (ml, mt, s) = (img.ox, img.oy, img.scale);
        for j in 0..r.ny {
            for i in 0..r.nx {
                let col = match r.at(i, j).and_then(|(key, _)| self.swatch_of_key(key).map(|sw| (sw, key))) {
                    Some((sw, key)) => {
                        let d = self.swatches.get(sw).map(|w| w.disp).unwrap_or_else(|| lb_display(self.buckets[&key].mean_lin(), self.exposure));
                        match highlight {
                            Some(h) if h != sw => [(d[0] as f32 * 0.3) as u8, (d[1] as f32 * 0.3) as u8, (d[2] as f32 * 0.3) as u8, 255],
                            _ => [d[0], d[1], d[2], 255],
                        }
                    }
                    None => [30, 30, 34, 255],
                };
                img.fill_rect(ml + i * s, mt + (r.ny - 1 - j) * s, s, s, col);
            }
        }
        let info = match highlight {
            Some(h) => format!("EXPO {:.3} SWATCH {h} HIGHLIGHTED  {} SWATCHES", self.exposure, self.swatches.len()),
            None => format!("EXPO {:.3} {} SWATCHES {} BUCKETS {} SAMPLES", self.exposure, self.swatches.len(), self.bucket_count, self.total),
        };
        img.draw_frame(r.x0, r.y0, r.step, grid_wu, &info);
        img
    }
    /// Swatch strip: numbered tiles, 12 per row.
    pub fn render_palette(&self) -> LightBakeImage {
        let (tile, gap, cols, fs) = (40usize, 4usize, 12usize, 2usize);
        let rows = (self.swatches.len() + cols - 1) / cols.max(1);
        let (w, h) = (cols * (tile + gap) + gap, rows.max(1) * (tile + gap) + gap + 6 * fs);
        let mut img = LightBakeImage { w, h, rgba: vec![0u8; w * h * 4], ox: 0, oy: 0, scale: 1, nx: 0, ny: 0 };
        img.fill_rect(0, 0, w, h, [24, 24, 28, 255]);
        for (i, sw) in self.swatches.iter().enumerate() {
            let (x, y) = (gap + (i % cols) * (tile + gap), gap + (i / cols) * (tile + gap));
            img.fill_rect(x, y, tile, tile, [sw.disp[0], sw.disp[1], sw.disp[2], 255]);
            let txt = if sw.lum > 0.5 { [0, 0, 0] } else { [255, 255, 255] };
            img.text(x + 2, y + 2, &format!("{i}"), fs, txt);
        }
        img.text(gap, h - 6 * fs, &format!("EXPO {:.3}", self.exposure), fs, [180, 200, 255]);
        img
    }
    /// One line per swatch for the headless log.
    pub fn palette_text(&self) -> String {
        let mut s = String::new();
        for (i, sw) in self.swatches.iter().enumerate() {
            let ex = sw.samples.first().map(|e| format!("({:.1},{:.1},{:.1}) {}", e.pos[0], e.pos[1], e.pos[2], e.kind_name())).unwrap_or_default();
            s.push_str(&format!("  swatch {:>3}: rgb=({:>3},{:>3},{:>3}) lin=({:.4},{:.4},{:.4}) pop={:>9} (lm {} pvl {} probe {} air {}) cells={} e.g. {}\n",
                i, sw.disp[0], sw.disp[1], sw.disp[2], sw.lin[0], sw.lin[1], sw.lin[2], sw.population, sw.kinds[1], sw.kinds[2] + sw.kinds[3], sw.kinds[4], sw.kinds[5], sw.cells.len(), ex));
        }
        s
    }
}

/// A probed placement for a swatch (step 3): the real object-lighting sample at ground + radius.
#[derive(Clone, Copy, Debug, Default)]
pub struct LightBakePlacement {
    pub x: f32,
    pub y: f32,
    /// Ground z under the placement.
    pub z: f32,
    /// Object origin z = ground + probe radius.
    pub place_z: f32,
    pub color_lin: [f32; 3],
    pub disp: [u8; 3],
    /// Display-space distance to the swatch colour.
    pub dist: f32,
    pub mask: f32,
    pub kind: u8,
    /// The probe's merged key light and fill (incl. ×2 bounce) — for comparing with HMS_OBJPROBE_DIAG.
    pub key_rgb: [f32; 3],
    pub fill_rgb: [f32; 3],
}

/// The scenario's default area_screen_effect (see `SceneController::read_screen_fx`); the
/// elements themselves are decoded by `screenfx::decode_sefc`.
#[derive(Clone, Copy, Debug, Default)]
pub struct ScreenFx {
    pub tag: u32,
}

/// Decoded DM/SDM atlas submaps for one per-pixel lightmap mesh (see `SceneController::lm_atlas_images`).
#[derive(Clone)]
pub(crate) struct LmAtlasImages {
    dm: std::sync::Arc<(Vec<u8>, u32, u32)>,
    s0: std::sync::Arc<(Vec<u8>, u32, u32)>,
    s1: Option<std::sync::Arc<(Vec<u8>, u32, u32)>>,
    s2: Option<std::sync::Arc<(Vec<u8>, u32, u32)>>,
    dm_fmt: u32,
}
/// ENGINE per-pixel lightmap texel decode (doc 16 §1.4, HLSL DecompressVMF): POINT sample at floor(uv·size)
/// of the DM + the three SDM slices → dual-vMF (dom = (s0 + 2·s1 − 1)·s, fill = s2·s, s = hdr·K·exp2(−9·DM.r),
/// dir from the slice alphas, mask = DM visibility). Returns (probe, texel xy, DM.r, vis).
fn lm_texel_decode(imgs: &LmAtlasImages, hdr: f32, k: f32, uv: [f32; 2]) -> (ProbeVmf, (u32, u32), f32, f32) {
    // bitmap_2d_get_real_pixel: POINT sample, floor(uv·size), clamped — no bilinear.
    let texel = |img: &(Vec<u8>, u32, u32)| -> ([f32; 4], (u32, u32)) {
        let (ref px, w, h) = *img;
        let x = ((uv[0].clamp(0.0, 1.0) * w as f32).floor() as u32).min(w.saturating_sub(1));
        let y = ((uv[1].clamp(0.0, 1.0) * h as f32).floor() as u32).min(h.saturating_sub(1));
        let o = ((y * w + x) * 4) as usize;
        if o + 3 < px.len() { ([px[o + 2] as f32 / 255.0, px[o + 1] as f32 / 255.0, px[o] as f32 / 255.0, px[o + 3] as f32 / 255.0], (x, y)) } else { ([0.0, 0.0, 0.0, 0.5], (x, y)) }
    };
    let (d, txy) = texel(&imgs.dm);
    let vis = if imgs.dm_fmt == 44 { d[3] } else { d[1] };
    let (s0, _) = texel(&imgs.s0);
    let s1 = imgs.s1.as_ref().map(|i| texel(i).0).unwrap_or([0.5, 0.5, 0.5, 0.5]);
    let s2 = imgs.s2.as_ref().map(|i| texel(i).0).unwrap_or([0.0, 0.0, 0.0, 0.5]);
    let dir_raw = Vec3::new(s0[3] * 2.0 - 1.0, s1[3] * 2.0 - 1.0, s2[3] * 2.0 - 1.0);
    let bw = dir_raw.length();
    let dir = if bw > 1e-4 { dir_raw / bw } else { Vec3::Z };
    let f_int = (2.0f32).powf(-9.0 * d[0]); // exp(−6.238325·DM.r) ≡ exp2(−9·DM.r)
    let s = hdr * k * f_int;
    let pv = ProbeVmf {
        dom_dir: dir.into(),
        dom_rgb: [(s0[0] + s1[0] * 2.0 - 1.0) * s, (s0[1] + s1[1] * 2.0 - 1.0) * s, (s0[2] + s1[2] * 2.0 - 1.0) * s],
        fill_rgb: [s2[0] * s, s2[1] * s, s2[2] * s],
        bandwidth: bw.min(1.0).max(1e-3), mask: vis.clamp(0.0, 1.0), engine: true, src: 1, ..Default::default()
    };
    (pv, txy, d[0], vis)
}

/// One SHIPPED lightmap texel's decoded dual-vMF lobes (already × hdr·K), for the
/// bake-vs-shipped harness (`bake_compare.rs`). Thin public view over `lm_texel_decode`.
#[derive(Clone, Copy, Debug, Default)]
pub(crate) struct ShippedTexel {
    pub dom_dir: [f32; 3],
    pub dom_rgb: [f32; 3],
    pub fill_rgb: [f32; 3],
    pub bandwidth: f32,
    /// DM visibility (the engine's `vmf[0].w` analytical-sun gate).
    pub vis: f32,
}
pub(crate) fn shipped_lm_texel(imgs: &LmAtlasImages, hdr: f32, k: f32, uv: [f32; 2]) -> ShippedTexel {
    let (pv, _txy, _dm_r, vis) = lm_texel_decode(imgs, hdr, k, uv);
    ShippedTexel { dom_dir: pv.dom_dir, dom_rgb: pv.dom_rgb, fill_rgb: pv.fill_rgb, bandwidth: pv.bandwidth, vis }
}

/// §3.3 bounce light from a hit surface with albedo `a` and normal `n`: 10·A·E_dom/π.
/// NO sun term. The engine's E adds `mask0·max(0,N·L)·I` of the "directional light at the
/// object" (sample+108), but that slot is still zero when the bounce is built (filled by
/// `sub_140828FA0` after the geometry sample returns), so for a static sample only the dominant lobe
/// contributes. Capture-proven on Ivory Tower (object at (-32.9,-172.5,245.3), mask 0.83: engine bounce
/// (1.08,0.44,0.11) = the lobe-only prediction (1.27,0.47,0.13); with the sun term HMS gave (2.78,1.50,0.55)).
fn surface_bounce(a: [f32; 3], n: Vec3, pv: &ProbeVmf) -> [f32; 3] {
    let e0 = n.dot(Vec3::from(pv.dom_dir)).max(0.0);
    let inv_pi = 1.0 / std::f32::consts::PI;
    let mut bc = [0f32; 3];
    for k in 0..3 { bc[k] = 10.0 * a[k] * e0 * pv.dom_rgb[k] * inv_pi; }
    bc
}

/// The object colour estimate for a probe — CPU port of mesh_shade's object-light merge
/// (crates/hms-render/src/mesh.rs) for a flat, upward-facing (N = +Z), white face.
#[derive(Clone, Copy, Debug, Default)]
pub struct ObjColorEstimate {
    pub color: [f32; 3],
    pub key_rgb: [f32; 3],
    pub key_dir: [f32; 3],
    pub fill: [f32; 3],
}
fn object_color_from_probe(pv: &ProbeVmf, sun_rgb: [f32; 3], sun_dir: Vec3) -> ObjColorEstimate {
    let n = Vec3::Z;
    let mask = pv.mask.clamp(0.0, 1.0);
    let col0 = pv.dom_rgb;
    let col1 = [pv.fill_rgb[0].max(0.0), pv.fill_rgb[1].max(0.0), pv.fill_rgb[2].max(0.0)]; // i.tint
    let dir0 = { let d = Vec3::from(pv.dom_dir); if d.length_squared() > 1e-8 { d.normalize() } else { Vec3::Z } };
    let bounce = [pv.bounce_rgb[0].max(0.0), pv.bounce_rgb[1].max(0.0), pv.bounce_rgb[2].max(0.0)];
    let bdir = { let d = Vec3::from(pv.bounce_dir); if d.length_squared() > 1e-6 { d.normalize() } else { Vec3::Z } };
    let (key_dir, key_rgb, fill) = if pv.engine {
        let fd = Vec3::from(pv.fill_dir);
        let dir1 = if fd.length_squared() > 1e-6 { fd.normalize() } else { Vec3::ZERO }; // flag 2 → zero
        let l0 = col0[0] + col0[1] + col0[2];
        let l1 = col1[0] + col1[1] + col1[2];
        let tot = (l0 + l1).max(1e-5);
        let f0 = l0 / tot; let f1 = 1.0 - f0;
        let ls = (sun_rgb[0] + sun_rgb[1] + sun_rgb[2]) * mask;
        let mut b = mask;
        if tot + ls > 1e-4 { b = b.min(ls / (tot + ls)); }
        let ld = dir0 * f0 + dir1 * f1;
        let lobe_dir = if ld.length() > 1e-5 { ld / ld.length().max(1e-6) } else { dir0 };
        let ad = sun_dir * b + lobe_dir * (1.0 - b);
        let key = if ad.length() > 1e-5 { ad / ad.length().max(1e-6) } else { dir0 };
        // chmt bounce-to-ambient (2.0 bipeds..equipment, 0.5 scenery/crates on forge_halo)
        let bta = pv.chmt[3];
        let mut kc = [0f32; 3]; let mut fl = [0f32; 3];
        for k in 0..3 { kc[k] = b * sun_rgb[k] + (1.0 - b) * (f0 * col0[k] + f1 * col1[k]); fl[k] = col1[k] + bta * bounce[k]; }
        (key, kc, fl)
    } else {
        (dir0, [col0[0] * mask, col0[1] * mask, col0[2] * mask], col1)
    };
    // bake = (LUT(N·dir0, bw)·col0 + 0.25·fill + sat(N·bounce_dir)·bounce_scale·bounce) / π ; sun_term = key·sat(N·key)/π
    // (chmt bounce scale; the min-luminance / max-contrast per-frame terms need the exposure +
    // camera distance and are applied in mesh_shade only — this estimate is the crate/scenery case, where
    // forge_halo authors both off.)
    let pco = crate::lightprobe::vmf_diffuse_coeff(dir0.dot(n), pv.bandwidth.clamp(0.0, 1.0));
    let third = n.dot(bdir).max(0.0) * if pv.engine { pv.chmt[4] } else { 1.0 };
    let ndl = n.dot(key_dir).max(0.0);
    let inv_pi = 1.0 / std::f32::consts::PI;
    let mut color = [0f32; 3];
    for k in 0..3 {
        let bake = (pco * col0[k] + 0.25 * fill[k] + third * bounce[k]) * inv_pi;
        color[k] = (bake + key_rgb[k] * ndl * inv_pi).max(0.0);
    }
    ObjColorEstimate { color, key_rgb, key_dir: key_dir.into(), fill }
}

/// Display colour (0-255) of a linear colour: saturate(sqrt(colour × exposure)) — the renderer's gamma2 output op.
fn lb_display(color: [f32; 3], exposure: f32) -> [u8; 3] {
    let mut o = [0u8; 3];
    for k in 0..3 { o[k] = ((color[k] * exposure).max(0.0).sqrt().min(1.0) * 255.0 + 0.5) as u8; }
    o
}

#[derive(Default)]
struct LightProbeGrid {
    points: Vec<hms_native::AirprobePoint>,
    mean: [f32; 3],
    valid: bool,
    // Uniform spatial grid over probe positions. sample_absolute was an O(N_points) linear
    // scan run PER VERTEX (~O(N_verts × N_points)) — ~80s of a 90s Ivory Tower load. The grid makes
    // it a ring-expanding nearest-neighbor query that touches only nearby cells → effectively O(1).
    cell: f32,
    cell_min: (i32, i32, i32),
    cell_max: (i32, i32, i32),
    grid: std::collections::HashMap<(i32, i32, i32), Vec<u32>>,
}

impl LightProbeGrid {
    #[inline]
    fn cell_key(&self, p: Vec3) -> (i32, i32, i32) {
        ((p.x / self.cell).floor() as i32, (p.y / self.cell).floor() as i32, (p.z / self.cell).floor() as i32)
    }

    /// (re)build the spatial grid from `points`. Cell size ≈ average probe spacing
    /// (cbrt of bbox-volume / count), so the ring search for the nearest probe touches only a
    /// handful of cells. Called after every `add` (few sbsps, so a full rebuild is cheap).
    fn rebuild_grid(&mut self) {
        self.grid.clear();
        let fin: Vec<usize> = self.points.iter().enumerate()
            .filter(|(_, p)| p.pos.iter().all(|c| c.is_finite()))
            .map(|(i, _)| i).collect();
        if fin.is_empty() { self.cell = 0.0; return; }
        let (mut mn, mut mx) = ([f32::MAX; 3], [f32::MIN; 3]);
        for &i in &fin {
            let p = self.points[i].pos;
            for k in 0..3 { mn[k] = mn[k].min(p[k]); mx[k] = mx[k].max(p[k]); }
        }
        let ext = [(mx[0] - mn[0]).max(0.0), (mx[1] - mn[1]).max(0.0), (mx[2] - mn[2]).max(0.0)];
        // Cell ≈ largest-axis extent / n^(1/3). Using the LARGEST extent (not the bbox
        // volume) is robust to near-planar probe layouts: a thin axis would make a volume-based
        // cbrt(vol/n) collapse to a near-zero cell → millions of cells and a huge max_ring, so the
        // ring search scanned enormous empty shells per vertex (SLOWER than the linear scan it
        // replaced). Extent-based keeps the grid a few dozen cells per axis regardless of shape.
        let max_ext = ext[0].max(ext[1]).max(ext[2]).max(1.0);
        self.cell = (max_ext / (fin.len() as f32).cbrt()).max(1.0);
        for &i in &fin {
            let key = self.cell_key(Vec3::from(self.points[i].pos));
            self.grid.entry(key).or_default().push(i as u32);
        }
        self.cell_min = self.cell_key(Vec3::from(mn));
        self.cell_max = self.cell_key(Vec3::from(mx));
    }

    /// Merge one BSP's probe points and recompute the finite-guarded mean.
    fn add(&mut self, fresh: Vec<hms_native::AirprobePoint>) {
        if fresh.is_empty() {
            return;
        }
        self.points.extend(fresh);
        let (mut sr, mut sg, mut sb, mut n) = (0f64, 0f64, 0f64, 0u32);
        for p in &self.points {
            if p.ambient.iter().all(|c| c.is_finite()) {
                sr += p.ambient[0] as f64;
                sg += p.ambient[1] as f64;
                sb += p.ambient[2] as f64;
                n += 1;
            }
        }
        if n > 0 {
            // Floor away from zero so a near-black mean can't blow up the divide.
            self.mean = [
                (sr / n as f64).max(1e-3) as f32,
                (sg / n as f64).max(1e-3) as f32,
                (sb / n as f64).max(1e-3) as f32,
            ];
            self.valid = true;
        }
        self.rebuild_grid(); // Keep the nearest-neighbor grid in sync with points
    }

    /// Scene-global key/sun direction (TO the sun, world Z-up), derived from the
    /// baked airprobe dual-VMF dominant-lobe direction — the port of the C#
    /// `SceneController.FinalizeAnalyticalSun` (there is NO sun-direction field in any
    /// tag; both the engine and the C# reference recover it from the baked lightprobe
    /// data). Each probe contributes `dom_dir * weight`, weight = directional fraction
    /// (`dir_weight`) × ambient luminance (the dominant-lobe magnitude proxy). Returns
    /// None when the accumulator is degenerate so the caller keeps the (0.4,0.7,0.6)
    /// fallback both C# apps use for probe-less maps.
    fn scene_sun_dir(&self) -> Option<Vec3> {
        if !self.valid || self.points.is_empty() {
            return None;
        }
        let mut acc = Vec3::ZERO;
        for p in &self.points {
            if !p.dom_dir.iter().all(|c| c.is_finite())
                || !p.ambient.iter().all(|c| c.is_finite())
            {
                continue;
            }
            let d = Vec3::from(p.dom_dir);
            let dl = d.length();
            if dl < 1e-4 {
                continue; // no dominant direction on this probe
            }
            // Rec.709 luminance of the up-facing ambient as the lobe-magnitude proxy.
            let lum = 0.2126 * p.ambient[0] + 0.7152 * p.ambient[1] + 0.0722 * p.ambient[2];
            let dw = if p.dir_weight.is_finite() { p.dir_weight.max(0.0) } else { 0.0 };
            let w = lum.max(0.0) * dw;
            if w <= 0.0 {
                continue;
            }
            acc += (d / dl) * w;
        }
        let l = acc.length();
        if l.is_finite() && l > 1e-4 {
            Some(acc / l)
        } else {
            None
        }
    }

    /// luminance-weighted average airprobe directional fraction over the grid — the
    /// map's overall "how directional is the natural light" (bright sunny map → high; overcast
    /// / enclosed → low). Drives the dynamic-object dominant-lobe soft-shade strength so object
    /// shading contrast is per-map-accurate instead of a fixed constant. None if no grid.
    fn scene_dir_weight(&self) -> Option<f32> {
        if !self.valid || self.points.is_empty() {
            return None;
        }
        let (mut acc, mut wsum) = (0f32, 0f32);
        for p in &self.points {
            if !p.ambient.iter().all(|c| c.is_finite()) || !p.dir_weight.is_finite() {
                continue;
            }
            let lum = 0.2126 * p.ambient[0] + 0.7152 * p.ambient[1] + 0.0722 * p.ambient[2];
            let w = lum.max(0.0);
            acc += p.dir_weight.clamp(0.0, 1.0) * w;
            wsum += w;
        }
        if wsum > 1e-4 { Some(acc / wsum) } else { None }
    }

    /// Population of the airprobe grid's own sun-visibility masks. If an interior map's
    /// probes are nearly all "1", the probe mask cannot be the source of indoor sun occlusion.
    fn mask_hist(&self) -> (usize, f32, f32, f32) {
        let n = self.points.len();
        let mut sum = 0.0f32;
        let (mut lo, mut hi) = (0usize, 0usize);
        for p in &self.points {
            let m = if p.mask.is_finite() { p.mask.clamp(0.0, 1.0) } else { 1.0 };
            sum += m;
            if m < 0.05 { lo += 1 }
            if m > 0.95 { hi += 1 }
        }
        if n == 0 { return (0, 0.0, 0.0, 0.0) }
        (n, sum / n as f32, 100.0 * lo as f32 / n as f32, 100.0 * hi as f32 / n as f32)
    }

    fn sample_mask(&self, world: Vec3) -> f32 {
        if !self.valid || self.points.is_empty() {
            return 1.0;
        }
        let mut best = f32::MAX;
        let mut mask = 1.0f32;
        for p in &self.points {
            if !p.pos.iter().all(|c| c.is_finite()) {
                continue;
            }
            let d = (Vec3::from(p.pos) - world).length_squared();
            if d < best {
                best = d;
                mask = if p.mask.is_finite() { p.mask.clamp(0.0, 1.0) } else { 1.0 };
            }
        }
        mask
    }

    /// ABSOLUTE nearest-probe ambient (linear-HDR), NOT divided by the grid mean.
    /// This is the same magnitude space as the cluster PVL irradiance, so toning it
    /// (tone_irradiance) lands foliage in the terrain's absolute brightness range (a
    /// mean-relative tint could not be reconciled with terrain by any single scalar).
    /// Falls back to the grid mean, then a small neutral ambient when no grid is loaded.
    /// OBJ-PROBE: engine object lighting probe = blend of the ~4 nearest airprobes weighted 1/distance
    /// (doc 00 §4 `FUN_1406BAEA0`); returns the raw dual-vMF lobes for per-pixel evaluation.
    fn sample_vmf(&self, world: Vec3) -> Option<ProbeVmf> {
        if !self.valid || self.points.is_empty() { return None; }
        let mut best: Vec<(f32, u32)> = Vec::with_capacity(8);
        fn consider_pt(best: &mut Vec<(f32, u32)>, world: Vec3, i: u32, p: &hms_native::AirprobePoint) {
            let d = (Vec3::from(p.pos) - world).length();
            if best.len() < 4 { best.push((d, i)); best.sort_by(|a, b| a.0.partial_cmp(&b.0).unwrap()); }
            else if d < best[3].0 { best[3] = (d, i); best.sort_by(|a, b| a.0.partial_cmp(&b.0).unwrap()); }
        }
        if self.cell > 0.0 && !self.grid.is_empty() {
            let (cx, cy, cz) = self.cell_key(world);
            for r in 0..=3i32 {
                for x in (cx - r)..=(cx + r) { for y in (cy - r)..=(cy + r) { for z in (cz - r)..=(cz + r) {
                    if (x - cx).abs() != r && (y - cy).abs() != r && (z - cz).abs() != r { continue; }
                    if let Some(v) = self.grid.get(&(x, y, z)) { for &i in v { consider_pt(&mut best, world, i, &self.points[i as usize]); } }
                }}}
                if best.len() >= 4 && best[3].0 <= (r as f32) * self.cell { break; }
            }
        } else {
            for (i, p) in self.points.iter().enumerate() { consider_pt(&mut best, world, i as u32, p); }
        }
        if best.is_empty() { return None; }
        let mut acc = ProbeVmf::default(); let mut wsum = 0.0f32;
        for &(d, i) in &best {
            let p = &self.points[i as usize];
            let w = 1.0 / d.max(0.05);
            if !p.dom_rgb.iter().chain(p.fill_rgb.iter()).all(|c| c.is_finite()) { continue; }
            for k in 0..3 { acc.dom_dir[k] += p.dom_dir[k] * w; acc.dom_rgb[k] += p.dom_rgb[k] * w; acc.fill_rgb[k] += p.fill_rgb[k] * w; }
            acc.bandwidth += p.bandwidth * w; acc.mask += p.mask.clamp(0.0, 1.0) * w; wsum += w;
        }
        if wsum <= 0.0 { return None; }
        for k in 0..3 { acc.dom_rgb[k] /= wsum; acc.fill_rgb[k] /= wsum; }
        acc.bandwidth /= wsum; acc.mask /= wsum;
        let d = Vec3::from(acc.dom_dir);
        acc.dom_dir = if d.length() > 1e-4 { d.normalize().into() } else { [0.0, 0.0, 1.0] };
        Some(acc)
    }

    /// ENGINE nearest-airprobe blend (`sub_1406BAEA0`, doc 16 §1.1): every probe closer than
    /// `max_dist` is a candidate, at most 6 are kept (farthest evicted), weights 1/max(d,0.01)³ normalised,
    /// all 16 dual-vMF terms summed LINEARLY (both lobe directions renormalised afterwards). No cluster /
    /// visibility test. Returns (blend, distance to the nearest kept probe, probes kept); None if no probe
    /// lies within `max_dist`.
    fn sample_airprobes_engine(&self, world: Vec3, max_dist: f32) -> Option<(ProbeVmf, f32, usize)> {
        if !self.valid || self.points.is_empty() { return None; }
        const K_MAX: usize = 6;
        let mut kept: Vec<(f32, u32)> = Vec::with_capacity(K_MAX);
        let mut consider = |i: u32, p: &hms_native::AirprobePoint| {
            if !p.pos.iter().all(|c| c.is_finite()) { return; }
            let d = (Vec3::from(p.pos) - world).length();
            if d < max_dist {
                if kept.len() < K_MAX {
                    kept.push((d, i));
                } else {
                    let mut far = 0usize;
                    for j in 1..kept.len() { if kept[j].0 > kept[far].0 { far = j; } }
                    if kept[far].0 > d { kept[far] = (d, i); }
                }
            }
        };
        // Finite radius (the common "airprobes closer than the hit" query, a few wu): visit only the grid
        // cells the sphere touches — exact, since every probe within max_dist lies in one of them. Infinite
        // radius / huge spheres: the plain linear scan (identical result).
        let mut done = false;
        if max_dist.is_finite() && self.cell > 0.0 && !self.grid.is_empty() {
            let (k0, k1) = (self.cell_key(world - Vec3::splat(max_dist)), self.cell_key(world + Vec3::splat(max_dist)));
            let span = (k1.0 - k0.0 + 1) as i64 * (k1.1 - k0.1 + 1) as i64 * (k1.2 - k0.2 + 1) as i64;
            if span <= 4096 {
                for x in k0.0..=k1.0 { for y in k0.1..=k1.1 { for z in k0.2..=k1.2 {
                    if let Some(v) = self.grid.get(&(x, y, z)) { for &i in v { consider(i, &self.points[i as usize]); } }
                }}}
                done = true;
            }
        }
        if !done {
            for (i, p) in self.points.iter().enumerate() { consider(i as u32, p); }
        }
        if kept.is_empty() { return None; }
        let mut w: Vec<f32> = kept.iter().map(|(d, _)| 1.0 / d.max(0.01).powi(3)).collect();
        let sw: f32 = w.iter().sum();
        if sw > 1e-15 { for x in w.iter_mut() { *x /= sw; } } else { for (j, x) in w.iter_mut().enumerate() { *x = if j == 0 { 1.0 } else { 0.0 }; } }
        let mut acc = ProbeVmf::default();
        let mut min_d = f32::MAX;
        for ((d, i), wi) in kept.iter().zip(w.iter()) {
            let p = &self.points[*i as usize];
            min_d = min_d.min(*d);
            let ok = p.dom_rgb.iter().chain(p.fill_rgb.iter()).chain(p.dom_dir.iter()).chain(p.fill_dir.iter()).all(|c| c.is_finite());
            if !ok { continue; }
            for k in 0..3 {
                acc.dom_dir[k] += p.dom_dir[k] * wi;
                acc.fill_dir[k] += p.fill_dir[k] * wi;
                acc.dom_rgb[k] += p.dom_rgb[k] * wi;
                acc.fill_rgb[k] += p.fill_rgb[k] * wi;
            }
            acc.bandwidth += (if p.bandwidth.is_finite() { p.bandwidth } else { 1.0 }) * wi;
            acc.mask += (if p.mask.is_finite() { p.mask.clamp(0.0, 1.0) } else { 1.0 }) * wi;
        }
        let d = Vec3::from(acc.dom_dir);
        acc.dom_dir = if d.length() > 1e-4 { d.normalize().into() } else { [0.0, 0.0, 1.0] };
        let f = Vec3::from(acc.fill_dir);
        acc.fill_dir = if f.length() > 1e-4 { f.normalize().into() } else { [0.0, 0.0, 0.0] };
        if !(acc.bandwidth > 0.0) { acc.bandwidth = 1.0; }
        acc.engine = true;
        Some((acc, min_d, kept.len()))
    }
    fn sample_absolute(&self, world: Vec3) -> [f32; 3] {
        if !self.valid || self.points.is_empty() {
            // Ground truth (RE): the engine has NO grey ambient floor — a missing probe
            // means the VMF fill lobe (~0), not a 0.35 neutral lift that brightens every
            // unlit/dark area. Keep a tiny value to avoid pure black where no grid exists.
            return [0.03, 0.03, 0.03];
        }
        // grid-accelerated nearest-probe lookup (was an O(N_points) linear scan run per
        // vertex → ~80s of the BSP load). Returns the EXACT same nearest probe as the old scan:
        // expand cell rings from the query cell and stop only once the best hit is provably closer
        // than any point in the next ring (min distance to ring r+1 ≥ r·cell). Falls back to the
        // linear scan if the grid is unbuilt (cell==0), so behaviour is identical either way.
        if self.cell > 0.0 && !self.grid.is_empty() {
            let cell = self.cell;
            let (cx, cy, cz) = self.cell_key(world);
            // Rings needed to guarantee full coverage (so a query outside the grid still finds the
            // global nearest, matching the linear scan) — the span from the query cell to the grid
            // bbox extremes on each axis.
            let max_ring = [
                (cx - self.cell_min.0).abs().max((cx - self.cell_max.0).abs()),
                (cy - self.cell_min.1).abs().max((cy - self.cell_max.1).abs()),
                (cz - self.cell_min.2).abs().max((cz - self.cell_max.2).abs()),
            ].into_iter().max().unwrap_or(0);
            // Safety cap: with the extent-based cell the nearest is found within a couple of rings
            // for any in-bounds query, so if the ring search runs long (a vertex far outside the
            // probe volume, or a very sparse region) bail to the exact linear scan below rather than
            // scan huge empty shells. Keeps the worst case O(N) like before, never worse.
            const RING_CAP: i32 = 12;
            let mut best = f32::MAX;
            let mut amb: Option<[f32; 3]> = None;
            let mut r = 0i32;
            let mut give_up = false;
            loop {
                for x in (cx - r)..=(cx + r) {
                    for y in (cy - r)..=(cy + r) {
                        for z in (cz - r)..=(cz + r) {
                            // Only the SHELL at Chebyshev distance exactly r (inner cells already done).
                            if (x - cx).abs() != r && (y - cy).abs() != r && (z - cz).abs() != r {
                                continue;
                            }
                            if let Some(v) = self.grid.get(&(x, y, z)) {
                                for &i in v {
                                    let p = &self.points[i as usize];
                                    let d = (Vec3::from(p.pos) - world).length_squared();
                                    if d < best { best = d; amb = Some(p.ambient); }
                                }
                            }
                        }
                    }
                }
                // A point in ring r+1 is at least r·cell away; stop once best beats that.
                if amb.is_some() && best.sqrt() <= (r as f32) * cell {
                    break;
                }
                if r >= max_ring {
                    break;
                }
                if r >= RING_CAP {
                    give_up = true;
                    break;
                }
                r += 1;
            }
            if !give_up {
                return match amb {
                    Some(a) if a.iter().all(|c| c.is_finite()) => a,
                    _ => self.mean,
                };
            }
            // else fall through to the exact linear scan (rare).
        }
        // Fallback: linear scan (grid unbuilt).
        let mut best = f32::MAX;
        let mut amb = None;
        for p in &self.points {
            if !p.pos.iter().all(|c| c.is_finite()) {
                continue;
            }
            let d = (Vec3::from(p.pos) - world).length_squared();
            if d < best {
                best = d;
                amb = Some(p.ambient);
            }
        }
        match amb {
            Some(a) if a.iter().all(|c| c.is_finite()) => a,
            _ => self.mean,
        }
    }
}

/// One scenario `structure_bsps` element (scnr, 172-B elements) joined with its sbsp's
/// authored world bounds. `flags` is the element's `scenario_structure_bsp_reference_flags` word
/// (+0x50); bit 10 = "not a normally playable space in an MP map (check this on shared BSPs)" —
/// the engine's network position encoding clamps object positions to the union of the PLAYABLE
/// BSPs' bounding boxes, which is what pushes objects placed out there back inside the map.
/// Layout evidence: reach_tag_test.exe field table (`scenario_structure_bsp_reference_block`:
/// 4 tag refs, long enum, 3 reals, word flags @+0x50, 14 bits) + forge_halo's block bytes
/// (element 1 `forge_halo_shared` = 0x0E00: no-pathfinding | not-playable | shared).
#[derive(Clone, Debug, PartialEq)]
pub struct StructureBspInfo {
    /// Index in the scenario's structure_bsps block (the engine's bsp index).
    pub index: usize,
    /// sbsp tag id (0xFFFF_FFFF when the reference is null).
    pub tag: u32,
    pub name: String,
    /// Raw `scenario_structure_bsp_reference_flags` word.
    pub flags: u16,
    /// sbsp `world bounds x/y/z` (sbsp+0xF0, three real bounds). Zero-sized when unread.
    pub min: Vec3,
    pub max: Vec3,
}

impl StructureBspInfo {
    /// Bit 10 of the reference flags (bit 11 = shared BSP).
    const FLAG_NOT_PLAYABLE: u16 = 1 << 10;
    pub fn non_playable(&self) -> bool { self.flags & Self::FLAG_NOT_PLAYABLE != 0 }
    pub fn has_bounds(&self) -> bool { (self.max - self.min).min_element() > 0.0 }
    pub fn contains(&self, p: Vec3) -> bool {
        self.has_bounds() && p.cmpge(self.min).all() && p.cmple(self.max).all()
    }
    pub fn volume(&self) -> f32 {
        let e = (self.max - self.min).max(Vec3::ZERO);
        e.x * e.y * e.z
    }
    /// Human-readable flag names (the 14 bits of the tag-test definition, in bit order).
    fn flag_names(&self) -> Vec<&'static str> {
        const NAMES: [&str; 14] = [
            "default sky enabled", "per vertex only lightmap", "never lightmap",
            "generate fake small lightmaps", "ray trace adjacent bsps on sky hits",
            "lightmaps use conservative subcharts", "lightmaps reduce stretch hack",
            "lightmaps use extended gathering", "lightmaps final gather ignores backfacing hits",
            "no pathfinding", "NOT NORMALLY PLAYABLE SPACE IN MP", "shared bsp",
            "dont use extra lighting bsps for cubemaps", "custom gravity scale",
        ];
        (0..14).filter(|b| self.flags & (1 << b) != 0).map(|b| NAMES[b]).collect()
    }
}

/// Pure decode of the scnr `structure_bsps` element bytes (172 B each) into
/// (sbsp datum, reference flags). Validates every element's tag-ref class at +0 is `sbsp`
/// (fourcc bytes "psbs" little-endian) so a wrong block offset yields None, not garbage.
fn decode_structure_bsp_elems(elems: &[u8], count: usize) -> Option<Vec<(u32, u16)>> {
    const ELEM: usize = 172;
    if count == 0 || count > 16 || elems.len() < count * ELEM { return None; }
    let mut out = Vec::with_capacity(count);
    for i in 0..count {
        let e = &elems[i * ELEM..(i + 1) * ELEM];
        if &e[0..4] != b"psbs" { return None; }
        let datum = u32::from_le_bytes([e[12], e[13], e[14], e[15]]);
        let flags = u16::from_le_bytes([e[0x50], e[0x51]]);
        out.push((datum, flags));
    }
    Some(out)
}

#[cfg(test)]
mod bsp_warn_tests {
    use super::*;

    /// forge_halo's scnr structure_bsps block, captured with HMS_PTRDUMP=5e804069:158 (2 × 172 B).
    const FORGE_HALO_STRUCTURE_BSPS: &[&str] = &[
        "70736273000000000000000056300ca6ffffffff0000000000000000ffffffff696c747300000000000000000a0080e1",
        "ffffffff0000000000000000ffffffff060000000000000000000000000000000002ffff000000006d74696200000000",
        "000000000b0081e1646e697700000000000000000c0082e1000000000000803f00008040000080410000804200000043",
        "0000804300000044000000000000803f00000000020000000000803f707362730000000000000000573bd9a6ffffffff",
        "0000000000000000ffffffff696c747300000000000000000e0084e1ffffffff0000000000000000ffffffff01000000",
        "000000000000000000000000000effff00000000ffffffff0000000000000000ffffffffffffffff0000000000000000",
        "ffffffff000000000000803f000080400000804100008042000000430000804300000044000000000000803f00000000",
        "010000000000803f",
    ];

    fn unhex(parts: &[&str]) -> Vec<u8> {
        let s: String = parts.concat();
        (0..s.len() / 2).map(|i| u8::from_str_radix(&s[i * 2..i * 2 + 2], 16).unwrap()).collect()
    }

    #[test]
    fn forge_halo_shared_bsp_is_flagged_not_playable() {
        let bytes = unhex(FORGE_HALO_STRUCTURE_BSPS);
        assert_eq!(bytes.len(), 2 * 172);
        let d = decode_structure_bsp_elems(&bytes, 2).expect("valid sbsp refs");
        assert_eq!(d[0].0 & 0xFFFF, 0x3056, "forge_halo sbsp");
        assert_eq!(d[1].0 & 0xFFFF, 0x3b57, "forge_halo_shared sbsp");
        assert_eq!(d[0].1, 0x0200); // no pathfinding only
        assert_eq!(d[1].1, 0x0E00); // no pathfinding | NOT PLAYABLE | shared
        let mk = |index, flags| StructureBspInfo { index, tag: 0, name: String::new(), flags, min: Vec3::ZERO, max: Vec3::ZERO };
        assert!(!mk(0, d[0].1).non_playable());
        assert!(mk(1, d[1].1).non_playable());
        assert!(mk(1, d[1].1).flag_names().contains(&"shared bsp"));
    }

    #[test]
    fn wrong_block_offset_is_rejected() {
        let bytes = unhex(FORGE_HALO_STRUCTURE_BSPS);
        // Sliced mid-element the tag-ref class no longer reads "sbsp".
        assert!(decode_structure_bsp_elems(&bytes[16..], 1).is_none());
        assert!(decode_structure_bsp_elems(&bytes, 3).is_none());
        assert!(decode_structure_bsp_elems(&bytes, 0).is_none());
    }

    #[test]
    fn tightest_containing_bsp_wins() {
        // Forge World shape: a playable main BSP nested inside a huge non-playable shared BSP.
        let main = StructureBspInfo { index: 0, tag: 0x3056, name: "forge_halo".into(), flags: 0x0200,
            min: Vec3::new(-203.6, -360.8, -25.0), max: Vec3::new(277.7, 324.9, 117.8) };
        let shared = StructureBspInfo { index: 1, tag: 0x3b57, name: "forge_halo_shared".into(), flags: 0x0E00,
            min: Vec3::new(-4783.4, -5289.7, -2.8), max: Vec3::new(4243.4, 3737.1, 1201.0) };
        let pick = |p: Vec3| [&main, &shared].iter().filter(|b| b.contains(p))
            .min_by(|a, b| a.volume().partial_cmp(&b.volume()).unwrap()).map(|b| b.index);
        assert_eq!(pick(Vec3::new(0.0, 0.0, 10.0)), Some(0));
        assert_eq!(pick(Vec3::new(1000.0, 0.0, 10.0)), Some(1));
        assert_eq!(pick(Vec3::new(0.0, 0.0, -100.0)), None);
    }
}

pub struct SceneController {
    native: Arc<NativeDll>,
    cache: Option<CacheHandle>,
    geom_cache: HashMap<u32, Option<DecodedModel>>,
    /// Perf: uploaded object textures cached by (mode_tag, part_index, kind 0=diffuse
    /// 1=emissive). A rebuild triggered by an object MOVE/duplicate reused to change only the
    /// instance transforms — without this, every rebuild recreated every part's texture (with
    /// mipmaps), which made dragging/duplicating lock the window for ~1s. wgpu handles are
    /// Arc-backed, so the cached TextureView is cheap to clone into each frame's bind group.
    obj_tex_cache: HashMap<(u32, usize, u8), (wgpu::TextureView, wgpu::Texture)>,
    /// The same uploaded textures keyed by their CPU SOURCE (SharedTex Arc pointer, upload
    /// kind) so parts/models that share one decoded texture share ONE GPU texture instead of
    /// uploading a copy per (tag, part, slot). The Arc stays alive (its bytes are released after the
    /// upload, see `release_uploaded_textures`), so the pointer key can never be reused.
    obj_tex_by_src: HashMap<(usize, u8), (wgpu::TextureView, wgpu::Texture)>,
    /// Variant models being decoded on a background thread (see `start_background_predecode`):
    /// the receiver of finished (mode_tag, model) pairs and the tags still in flight (the per-frame
    /// inline decode skips those instead of decoding them a second time on the UI thread).
    /// (Mutex only so the scene stays Sync for the existing rayon closures over &self.)
    predecode_rx: std::sync::Mutex<Option<std::sync::mpsc::Receiver<(u32, Option<DecodedModel>)>>>,
    predecode_tx: Option<std::sync::mpsc::Sender<(u32, Option<DecodedModel>)>>,
    predecode_inflight: std::collections::HashSet<u32>,
    /// Terrain layer textures (base/detail/bump/detail_bump/blend) for rmtr OBJECT models.
    obj_terrain_tex: HashMap<u32, (wgpu::TextureView, wgpu::Texture)>,
    /// Object detail / bump / bump_detail maps by bitmap tag (BC raw where possible;
    /// Linear-curve colour maps pre-encoded). Cleared with the object caches on map switch.
    obj_mat_tex: HashMap<u32, (wgpu::TextureView, wgpu::Texture)>,
    /// Model tags whose terrain textures/meshes were built at least once (GPU-budget bookkeeping).
    obj_terrain_ready: std::collections::HashSet<u32>,
    /// Authored env cubes for OBJECT glass, per bitmap tag (None = failed to build).
    obj_env_cube_cache: HashMap<u32, Option<(wgpu::Texture, wgpu::TextureView)>>,
    /// The engine's "dynamic" environment map is NOT a runtime capture -- it is the per-CLUSTER
    /// baked cubemap bitmap (`<scnr>_<bsp>_cubemaps`, one submap per cluster, decoded (4rgb)^2*(4a) per
    /// environment_mapping.hlsl_include:130-144). Per BSP: (cubemaps bitmap tag, per-cluster world AABBs
    /// accumulated from the cluster meshes) so an object can pick the cube of the cluster it sits in.
    cluster_cubes: Vec<ClusterCubes>,
    /// Decoded cluster cubes (HDR, alpha 1) keyed by (bitmap tag, submap); None = failed.
    cluster_cube_cache: HashMap<(u32, u32), Option<(wgpu::Texture, wgpu::TextureView)>>,
    /// The scenario's structure_bsps (index, tag, reference flags, world bounds),
    /// decoded once per map open; drives the "outside playable space" warnings.
    structure_bsps: Vec<StructureBspInfo>,
    /// per-datum visual scale multiplier for offline objects (forge "scale" label →
    /// X330 spawn_seq). Applied in maybe_rebuild's object matrix; default 1.0 when absent.
    obj_scales: HashMap<u32, f32>,
    /// Datums FORCED into the sun shadow map (per-object SHADOW pseudo-flag / the
    /// green+scale gametype rule, after the global "Shadow casters (Forge)" switch). Only ADDS
    /// casters: engine-default casters (obje lightmap_shadow_mode: vehicles etc.) always cast.
    obj_casters: std::collections::HashSet<u32>,
    /// Perf: cached object geometry buffers (wgpu buffers are Arc-backed → clone is
    /// cheap). vbuf per tag (dec.verts shared across parts), ibuf per (tag, part). A
    /// transform rebuild reuses these instead of re-uploading vertices/indices every frame —
    /// the two create_buffer_init calls were ~2/3 of the per-mesh cost, so this is what makes
    /// live dragging of a whole variant smooth.
    obj_vbuf_cache: HashMap<u32, wgpu::Buffer>,
    obj_ibuf_cache: HashMap<(u32, usize), (wgpu::Buffer, u32)>,
    picks: Vec<PickEntry>,
    bsp_picks: Vec<BspPick>,
    last_signature: u64,
    /// True when maybe_rebuild decoded only SOME of the object models this frame
    /// (per-frame decode budget) and must run again next frame to finish the rest — this
    /// spreads the main-thread model decode across frames so a large forge-object set pops
    /// in progressively instead of FREEZING the window while every model decodes at once.
    rebuild_pending: bool,
    /// Baked airprobe grid + per-BSP scene brightness (primed on map load).
    probe: LightProbeGrid,
    /// Global fallback brightness (for objects, which aren't tied to one BSP).
    /// FIRST authored non-neutral wins (was last-wins, which let a secondary/shared BSP
    /// darken the whole scene on multi-BSP maps like Forge World).
    brightness: f32,
    /// Per-sbsp authored Brightness (lBSP+0x18). BSP surface PVL uses its OWN
    /// BSP's Brightness, not one global "last-wins" scalar — a shared/sky BSP no longer
    /// darkens the main structure on multi-BSP maps.
    bsp_brightness: std::collections::HashMap<u32, f32>,
    /// World-space BSP triangle soup (opaque + terrain), built during load. Decals
    /// are clipped/conformed against this so they lie ON the receiving surface instead of
    /// floating as a flat quad.
    bsp_soup: crate::decal_projector::TriSoup,
    /// Retained per-mesh lightmap geometry (world verts + uv2 + atlas ids), captured
    /// during BSP load so the path-traced lightmapper can re-light the map without re-decoding.
    bsp_lm_geom: Vec<BspLmMesh>,
    /// self-illum EMITTER triangles (world verts + unclamped HDR radiance), gathered from
    /// BSP meshes whose material self-illuminates. The GPU tracer treats these as area lights (NEE),
    /// so light fixtures actually illuminate their rooms in the bake. Cleared per map load.
    emissive_tris: Vec<([Vec3; 3], [f32; 3])>,
    /// The tracer's OCCLUDER set — the BSP soup MINUS glass (rmgl) surfaces, so glass
    /// windows TRANSMIT light into interiors (daylight/sun/sky pass through) instead of shadowing them
    /// like an opaque wall. Built alongside the soup; the bake BVH is built from this, not bsp_soup.
    /// Stored as INDICES into `bsp_soup` (4 B/tri) and materialised by `bake_occluder_tris`
    /// when a bake starts, instead of a second 36 B/tri copy of the soup held for the whole session.
    bake_occluder_tri: Vec<u32>,
    /// `obj_lm_meshes` index of each `bake_occluder_tri` triangle (material/albedo/flags lookup).
    bake_occluder_mesh: Vec<u32>,
    /// Per `obj_lm_meshes` index, the mesh's mean self-illum radiance (HDR, unclamped).
    bake_occluder_emis: HashMap<u32, [f32; 3]>,
    /// `obj_lm_meshes` index of each `emissive_tris` entry (to drop sky-backdrop emitters from NEE).
    emissive_mesh: Vec<u32>,
    /// Per `obj_lm_meshes` index, the BSP material's blend mode when NOT opaque (translucent occluders).
    bake_occluder_blend: HashMap<u32, u32>,
    /// Per BSP render mesh (cluster + instance, world space), the lightmap data an object's
    /// lighting ray samples at its hit (doc 16 §1.4). Indexed by `obj_soup_owner[tri][0]`.
    obj_lm_meshes: Vec<LmSampleMesh>,
    /// Per `bsp_soup` triangle → [obj_lm_meshes index, i0, i1, i2] (mesh-local vertex ids),
    /// so a soup ray hit resolves to its mesh + barycentric vertex data. Built alongside the soup.
    obj_soup_owner: Vec<[u32; 4]>,
    /// CPU copies of the DM/SDM atlas submaps for the nearest-texel sample, keyed by
    /// (tag, submap | slice<<28) (slice 0 = keep-alpha decode, 1/2 = SDM volume slices). Lazy, small.
    obj_atlas_cpu: std::sync::Mutex<HashMap<(u32, u32), Option<std::sync::Arc<(Vec<u8>, u32, u32)>>>>,
    /// Bitmap tag → mean LINEAR colour (bounce albedo estimate), lazily decoded at a small mip.
    obj_albedo_cache: std::sync::Mutex<HashMap<u32, Option<[f32; 3]>>>,
    /// Bitmap tag -> small-mip CPU copy (BGRA, w, h) for the per-hit bounce albedo
    /// point sample (blend map at <=256 px, layer base maps at <=32 px). Lazy, small.
    obj_albedo_tex: std::sync::Mutex<HashMap<(u32, u32), Option<std::sync::Arc<(Vec<u8>, u32, u32)>>>>,
    /// Per lightmap-mesh "is foliage" (placement ground search steps through canopies).
    obj_foliage_cache: std::sync::Mutex<HashMap<usize, u8>>,
    /// obje tag → (object type @0, flags @4, bounding radius @0x0C).
    obj_meta_cache: std::sync::Mutex<HashMap<u32, Option<(u32, u32, f32)>>>,
    /// Every placed object with a decoded render model, as a ray target for the OTHER
    /// objects' lighting rays (the engine's collision raycast hits objects too, and the child adopts the
    /// hit object's cached lighting sample). Rebuilt at the top of every maybe_rebuild object pass.
    obj_ray_targets: Vec<ObjRayTarget>,
    /// Child probe-cache key -> the parent object (datum) whose sample it adopted, so a moved
    /// parent invalidates its children (their own key only covers their own pose).
    obj_probe_deps: std::sync::Mutex<HashMap<u64, u32>>,
    /// per-object pose hash of the previous probe pass (datum -> hash) + the ray-target
    /// count it was computed with; drives the dependency invalidation above.
    obj_pose_sig: HashMap<u32, u64>,
    obj_ray_targets_seen: usize,
    /// The map's `chocolate_mountain_new` (chmt) per-object-type lighting variables
    /// [min luminance, max contrast, max contrast distant, bounce to ambient, bounce scale] x 14 object
    /// types. Outer None = not scanned yet; inner None = the cache has no chmt tag (engine defaults).
    chmt_cache: std::sync::Mutex<Option<Option<Vec<[f32; 5]>>>>,
    /// `bitmap_mean` results by (tag, linear) — the bounce albedo of every object-lighting
    /// sample decoded up to 8 bitmaps per object per rebuild (dlc_medium: 441 objects = 3.4 s per pass).
    bitmap_mean_cache: std::sync::Mutex<HashMap<(u32, bool), Option<[f32; 4]>>>,
    /// Engine object-lighting sample per (datum, tags, pose, scale) — unchanged objects are
    /// not re-raycast on every rebuild pass (a rebuild runs per frame while GPU uploads drain, and on
    /// every object move).
    obj_probe_cache: std::sync::Mutex<HashMap<u64, Option<ProbeVmf>>>,
    /// SWAP: when true, load_step builds each BSP mesh's LightmapInputs from `baked_atlas`
    /// (our path-traced DM/SDM) instead of the shipped raw-BC atlas — the "ignore the map's lightmaps"
    /// toggle. Set by `set_pathtraced_bake`; consumed on the next BSP (re)load.
    pathtraced_enabled: bool,
    /// SWAP: baked dual-VMF atlas per DM submap (tag,sub) → encoded RGBA8 (dm/sdm0/1/2) + dims + k.
    baked_atlas: std::collections::HashMap<(u32, u32), BakedAtlas>,
    /// Per render-model phmo geometry (model-space flat xyz verts + tri indices),
    /// resolved+cached lazily. None = the mode has no resolvable physics_model. Used to overlay the
    /// walkable/physics volume of HIDDEN forge blocks (render model present but yields no visible
    /// geometry → invisible in-game, e.g. ff_cex_rock_blocker / the "hidden" structure blocks).
    phmo_cache: std::collections::HashMap<u32, Option<(Vec<f32>, Vec<u32>)>>,
    /// Per OBJECT-tag collision_model geometry (the WALKABLE surface), cached.
    coll_cache: std::collections::HashMap<u32, Option<(Vec<f32>, Vec<u32>)>>,
    /// world-space overlay geometry for hidden blocks, rebuilt in build_object_meshes.
    /// Solid translucent triangles (pos, rgba) + edge outline segments (a, b, rgb). Always-on.
    blocker_tris: Vec<([f32; 3], [f32; 4])>,
    blocker_lines: Vec<([f32; 3], [f32; 3], [f32; 3])>,
    /// Scenario-configured global exposure gain (g_exposure = pow(2, stops)),
    /// applied in the post/tonemap pass. 1.0 = neutral / unauthored.
    exposure: f32,
    /// tag-driven auto-exposure band from the cfxs camera_fx_settings — (key/target,
    /// min EV, max EV) in log2. None = map authors no camera_fx → keep the default post band.
    autoexposure_band: Option<(f32, f32, f32)>,
    /// (bloom point, inherent bloom, bloom intensity) from the map's cfxs tag.
    bloom_curve: Option<(f32, f32, f32)>,
    /// cfxs self-illum exposure (P = preferred exposure stops, s = exposure change scale),
    /// use-default resolved against the globals default cfxs (engine sub_1407E89C0 @0xBC / @0xCC).
    illum_exposure: Option<(f32, f32)>,
    /// cfxs BLOOM LARGE/MEDIUM/SMALL COLOR (1/64, 1/16, 1/4 levels), use-default resolved.
    bloom_colors: Option<[[f32; 3]; 3]>,
    /// The scenario's default area_screen_effect (sefc) — see `ScreenFx`.
    screen_fx: Option<ScreenFx>,
    /// per-scenario sceg colour-grade tints (sun, ambient). [1,1,1] = unauthored.
    sun_tint: [f32; 3],
    ambient_tint: [f32; 3],
    /// Analytical sky light (real per-map outdoor sun dir/colour + natural ambient),
    /// read from the sky render_model on load. None when the map authors no resolvable sky.
    sky_light: Option<hms_native::ZhSkyLight>,
    /// The scenario tag id resolved from the cache (drives sbsp enumeration).
    scnr: u32,
    /// In-flight chunked BSP load (None when idle).
    load_job: Option<LoadJob>,
    /// In-flight chunked decorator (foliage) build (None when idle/complete).
    deco_job: Option<DecoJob>,
    /// Disk cache: path + mtime of the currently-open `.map`, so begin_bsp_load can look up /
    /// write `<map>.hmscache`. mtime invalidates the cache when the map is re-cooked.
    map_path: Option<std::path::PathBuf>,
    map_mtime: u64,
    /// Forge palette NAME per resolved render_model tag (mode_tag → e.g. "spawning_kill",
    /// "obj_hill_marker", "jet_pack"). Lets the object classifier apply per-object colour/holo
    /// rules (kill=red, safe=green, hill=blue, armor abilities=hologram) by the stable palette
    /// name. Built once from the scenario forge palette on the first rebuild after a map loads.
    palette_names: HashMap<u32, String>,
    /// Placed forge LIGHT fixtures (ff_light_*) as dynamic point lights — (world pos, linear
    /// colour, radius). Collected during the object build; the app packs the nearest-N each frame
    /// into the SimpleLights uniform so forge lights ILLUMINATE nearby surfaces (not just self-glow).
    /// Every entry is now the object's real attached `ligh` (attenuation
    /// start/end + colour/intensity functions), evaluated at pack time so flash lights animate.
    forge_lights: Vec<ForgeLight>,
    /// hlmt attachment cache — obj_tag → [(child render_model tag, child MODEL-SPACE
    /// matrix, hlmt-variant Name sid, is_default_variant, child OBJECT tag)] for EVERY variant
    /// (turrets etc.). Built lazily; a parent instance draws each child at `parent_world * child_local`,
    /// filtered to the placement's variant (rocket warthog → rocket turret). Empty = enumerated, no
    /// attachments. The child obje tag is what decode_model needs for the child's own
    /// object type (engine material lane), default change colours and resting variant mask.
    attach_cache: HashMap<u32, Vec<(u32, Mat4, u32, bool, u32)>>,
    /// Per obj tag, the object's DEFAULT MODEL VARIANT sid (obje +0x60; 0 = hlmt variant 0).
    obj_default_variant_cache: HashMap<u32, u32>,
    /// Per obj_tag decoded lift/man-cannon effect chain (obje attachments → effe → ltvl
    /// light volumes + ligh dynamic light). None = object has no light-volume attachment. Cached.
    lift_fx_cache: HashMap<u32, Option<LiftFx>>,
    /// Decoded `lens` tags (None = unreadable), the placed lens flares of the object set
    /// (rebuilt with the object meshes) and of the effect_scenery placements (once per map).
    lens_def_cache: HashMap<u32, Option<std::sync::Arc<hms_render::LensFlareDef>>>,
    lens_sources_obj: Vec<hms_render::LensFlareInstance>,
    lens_sources_efsc: Option<Vec<hms_render::LensFlareInstance>>,
    /// 1×1 white texture bound to the untextured light-volume ribbons (fs_holo mode 4
    /// ignores the sampler but the mesh material needs a base view).
    lift_white_tex: Option<(wgpu::TextureView, wgpu::Texture)>,
    /// Decoded particle systems per effe tag / prt3 definitions / uploaded particle bitmaps.
    effe_particle_cache: HashMap<u32, std::sync::Arc<Vec<ParticleSystemDef>>>,
    prt3_cache: HashMap<u32, Option<std::sync::Arc<ParticleDef>>>,
    particle_tex_cache: HashMap<u32, Option<std::sync::Arc<(wgpu::TextureView, wgpu::Texture)>>>,
    /// Placed object effects (rebuilt with the object meshes) and effect_scenery effects
    /// (once per map) whose particle systems are simulated every frame by `build_particle_meshes`.
    particle_sources_obj: Vec<ParticleSource>,
    particle_sources_efsc: Option<Vec<ParticleSource>>,
    particle_warned: std::collections::HashSet<u32>,
    /// Emission accumulators keyed by emitter seed
    particle_emit_state: HashMap<u64, EmitState>,
    /// Per placed-effect event state machines keyed by the source seed
    particle_event_clocks: HashMap<u64, EventClock>,
    /// per-stli-light world offsets applied to the REAL-TIME tracer only
    light_offsets: HashMap<u32, [f32; 3]>,
}

/// A Guerilla mapping function (function_definition_data blob), the engine's
/// function.fx `evaluate` (docs/hrek_re/15_effect_particles.md §1.4). Blob: +0 type (0 identity, 1 constant, 2 transition, 3 periodic, 4 linear,
/// 7 spline, 8 multi, 9 exponent, 10 spline2), +1 flags (bit0 RANGED = a second sub-list lerped by
/// the property's `range` state; bit2 clamped; bit3 exclusion), +2 output kind (0 scalar → range
/// lo/hi @+4/+8; 1/2 colour → argb8 c0..c3 @+4..+0x10), +0x14/+0x18 exclusion min/max, +0x1C sub
/// list byte size, type 8: +0x20 count then {type u8, pad 3, domain_max f32, innards (VARIABLE:
/// constant 4, linear 8, spline 16, exponent 12, transition 12, periodic 20, spline2 32)}; a RANGED
/// blob carries a second {count, subs} list right after the first. Output = lerp(lo, hi, f).
#[derive(Clone, Debug)]
pub struct FnSub { pub ty: u8, pub dmax: f32, pub inn: [f32; 8] }

#[derive(Clone, Debug)]
pub enum MapFn {
    Const(f32),
    /// type 1 with the RANGED flag: f = range state (per-particle random) → lerp(lo, hi, r).
    RangedConst { lo: f32, hi: f32 },
    Identity { lo: f32, hi: f32 },
    /// type 8 multi: `subs` (domain-split), optional RANGED second list `subs_b` (lerped by the range
    /// state), `clamp` = flags bit2 (saturate the intermediate), `excl` = (min,max) when bit3.
    Multi { subs: Vec<FnSub>, subs_b: Vec<FnSub>, lo: f32, hi: f32, clamp: bool, excl: Option<(f32, f32)> },
}

/// Bytes of innards after the 8-byte sub header, per sub type (function.fx innards structs;
/// linear/spline/constant verified on the forge_halo blobs, the rest from the struct field counts).
fn mapfn_innards_size(ty: u8) -> usize {
    match ty { 0 => 0, 1 => 4, 2 => 12, 3 => 20, 4 => 8, 7 => 16, 9 => 12, 10 => 32, _ => 16 }
}

impl MapFn {
    fn sub_eval(ty: u8, inn: &[f32; 8], u: f32) -> f32 {
        match ty {
            0 => u,
            1 => inn[0],
            4 => inn[0] * u + inn[1],
            7 => ((inn[0] * u + inn[1]) * u + inn[2]) * u + inn[3],
            9 => u.max(0.0).powf(inn[2]) * (inn[1] - inn[0]) + inn[0],
            2 => {
                // transition: [function index, amplitude min, amplitude max]
                let t = match inn[0] as i32 { 0 => u, 1 => u.max(0.0).sqrt(), 2 => u.max(0.0).sqrt().sqrt(), 3 => u * u, 4 => u * u * u * u, 5 => (std::f32::consts::TAU * (u + 1.0)).cos(), 6 => 1.0, _ => 0.0 };
                t * (inn[2] - inn[1]) + inn[1]
            }
            3 => {
                // periodic: [function index, frequency, phase, amplitude min, amplitude max]
                let x = (u * inn[1] + inn[2]).fract();
                // function.hlsl `evaluate_periodic_internal`: 0 one, 1 zero, 2/3 cosine, 4/5 diagonal wave,
                // 6/7 slide, 8 noise = frac(2^x·10000), 9 jitter, 10 wander (sum-of-cosines), 11 spark (= x).
                let tau = std::f32::consts::TAU;
                let t = match inn[0] as i32 {
                    0 => 1.0, 1 => 0.0,
                    2 | 3 => 0.5 * ((tau * x).cos() + 1.0),
                    4 | 5 => if x < 0.5 { 2.0 * x } else { 2.0 - 2.0 * x },
                    8 => ((2f64.powf(x as f64) * 10000.0).fract()) as f32,
                    9 => 0.5 * ((tau * x / 4.0).cos() * (tau * x / 2.0).sin() + (tau * x / 7.0).cos() * (4.0 * tau * x).cos() + (tau * x / 4.0).sin() * (7.0 * tau * x).cos()) + 1.0,
                    10 => 0.5 * ((tau * x).cos() * (tau * x / 2.0).sin() + 0.5 * (tau * x / 7.0).cos() * (4.0 * tau * x).cos() + 0.5 * (tau * x / 4.0).sin() * (7.0 * tau * x).cos()) + 1.0,
                    _ => x,
                };
                t * (inn[4] - inn[3]) + inn[3]
            }
            10 => {
                // spline2: basis[4], left_x, width, bias
                let (lx, w, bias) = (inn[4], inn[5], inn[6]);
                let x = bias.signum() * ((u - lx) / if w.abs() > 1e-6 { w } else { 1.0 }).abs().powf(bias);
                ((inn[0] * x + inn[1]) * x + inn[2]) * x + inn[3]
            }
            _ => u,
        }
    }
    fn eval_subs(subs: &[FnSub], u: f32) -> f32 {
        // function.fx `evaluate`: the first sub that is a constant or whose domain_max >= input wins.
        match subs.iter().find(|s| s.ty == 1 || u <= s.dmax).or_else(|| subs.last()) {
            Some(s) => Self::sub_eval(s.ty, &s.inn, u),
            None => u,
        }
    }
    pub fn eval(&self, u: f32) -> f32 { self.eval2(u, 0.0) }
    /// Evaluate with the input `u` and the RANGED interpolant `r` (the property's range state).
    fn eval2(&self, u: f32, r: f32) -> f32 {
        let u = u.max(0.0);
        let (f, lo, hi) = match self {
            MapFn::Const(v) => return *v,
            MapFn::RangedConst { lo, hi } => (r.clamp(0.0, 1.0), *lo, *hi),
            MapFn::Identity { lo, hi } => (u, *lo, *hi),
            MapFn::Multi { subs, subs_b, lo, hi, clamp, excl } => {
                let mut f = Self::eval_subs(subs, u);
                if !subs_b.is_empty() { f += (Self::eval_subs(subs_b, u) - f) * r.clamp(0.0, 1.0); }
                if let Some((emin, emax)) = excl { if f > *emin { f += emax - emin; } }
                if *clamp { f = f.clamp(0.0, 1.0); }
                (f, *lo, *hi)
            }
        };
        let f = if f.is_finite() { f } else { 0.0 };
        lo + (hi - lo) * f
    }
    /// Decode a scalar function blob; a COLOUR blob (byte2 != 0) decodes with lo=0, hi=1 so the
    /// output is the c0→c3 ramp interpolant (see `decode_color_ramp`).
    pub fn decode(b: &[u8]) -> Option<MapFn> {
        if b.len() < 0x0c { return None; }
        let rdf = |o: usize| if o + 4 <= b.len() { f32::from_le_bytes([b[o], b[o + 1], b[o + 2], b[o + 3]]) } else { 0.0 };
        let rd32 = |o: usize| if o + 4 <= b.len() { u32::from_le_bytes([b[o], b[o + 1], b[o + 2], b[o + 3]]) } else { 0 };
        let sane = |v: f32| if v.is_finite() && v.abs() < 1.0e6 { v } else { 0.0 };
        let is_color = b[2] != 0;
        let (lo, hi) = if is_color { (0.0, 1.0) } else { (sane(rdf(4)), sane(rdf(8))) };
        let flags = b[1];
        let ranged = flags & 1 != 0;
        Some(match b[0] {
            1 => if ranged { MapFn::RangedConst { lo, hi } } else { MapFn::Const(lo) },
            0 => MapFn::Identity { lo, hi },
            8 => {
                if b.len() < 0x24 { return Some(MapFn::Identity { lo, hi }); }
                let parse_list = |o0: usize| -> (Vec<FnSub>, usize) {
                    let mut o = o0;
                    let n = rd32(o) as usize; o += 4;
                    let mut subs = Vec::new();
                    for _ in 0..n.min(8) {
                        if o + 8 > b.len() { break; }
                        let ty = b[o];
                        let dmax = rdf(o + 4);
                        let sz = mapfn_innards_size(ty);
                        let mut inn = [0f32; 8];
                        // transition / periodic innards lead with the function index as a u8
                        let k0 = if ty == 2 || ty == 3 { inn[0] = b.get(o + 8).copied().unwrap_or(0) as f32; 1 } else { 0 };
                        for k in k0..(sz / 4).min(8) { inn[k] = sane(rdf(o + 8 + k * 4)); }
                        subs.push(FnSub { ty, dmax: if dmax.is_finite() { dmax } else { f32::MAX }, inn });
                        o += 8 + sz;
                    }
                    (subs, o)
                };
                let (subs, o) = parse_list(0x20);
                let subs_b = if ranged && o + 4 <= b.len() { parse_list(o).0 } else { Vec::new() };
                if subs.is_empty() { return Some(MapFn::Identity { lo, hi }); }
                let excl = if flags & 8 != 0 { Some((sane(rdf(0x14)), sane(rdf(0x18)))) } else { None };
                MapFn::Multi { subs, subs_b, lo, hi, clamp: flags & 4 != 0, excl }
            }
            // single-function blobs (types 2 transition, 3 periodic, 4 linear, 7 spline, 9 exponent,
            // 10 spline2) carry ONE innards record at 0x20 (same 0x20 header as type 8; @0x1C = its byte size).
            // Verified on Boardwalk's blowing_paper emission rate: `03 14 .. range 0..12 .. @1C 0x14 @20 08 cd cd cd
            // 0.05 0 -2.0 1.2` = periodic NOISE (function index u8 @0x20 + 3 uninitialised bytes, then
            // frequency, phase, amplitude min/max), clamped output (flag bit2). It was previously decoded as
            // Identity (a 0→12 ramp of game time → unbounded emission).
            2 | 3 | 4 | 7 | 9 | 10 => {
                let sz = mapfn_innards_size(b[0]);
                if b.len() < 0x20 + sz { return Some(MapFn::Identity { lo, hi }); }
                let mut inn = [0f32; 8];
                let n = (sz / 4).min(8);
                if b[0] == 2 || b[0] == 3 {
                    inn[0] = b[0x20] as f32;
                    for k in 1..n { inn[k] = sane(rdf(0x20 + k * 4)); }
                } else {
                    for k in 0..n { inn[k] = sane(rdf(0x20 + k * 4)); }
                }
                let excl = if flags & 8 != 0 { Some((sane(rdf(0x14)), sane(rdf(0x18)))) } else { None };
                MapFn::Multi { subs: vec![FnSub { ty: b[0], dmax: f32::MAX, inn }], subs_b: Vec::new(), lo, hi, clamp: flags & 4 != 0, excl }
            }
            _ => MapFn::Identity { lo, hi },
        })
    }
    /// Colour output (byte2 != 0): the first argb8 colour slot @+0x04 (constant colour functions).
    fn decode_color(b: &[u8]) -> Option<[f32; 3]> {
        if b.len() < 8 || b[2] == 0 { return None; }
        let v = u32::from_le_bytes([b[4], b[5], b[6], b[7]]);
        Some([((v >> 16) & 0xff) as f32 / 255.0, ((v >> 8) & 0xff) as f32 / 255.0, (v & 0xff) as f32 / 255.0])
    }
    /// The ENGINE's colour evaluation of a colour blob at f (reach_tag_test.exe
    /// function_evaluate_color 0x1403F6CA0, IDA): byte +2 = colour count kind: 1 = c0
    /// constant; 2 = lerp(c0 @+4, c3 @+0x10, f); 3 = two segments over c0, c1 @+8, c3 (seg = floor(2f));
    /// 4 = three segments over the consecutive c0..c3 (seg = floor(3f), clamped to 2). Slots are packed
    /// argb8 (low byte = blue), /255 = the linear value. None for scalar blobs.
    fn decode_color_at(b: &[u8], f: f32) -> Option<[f32; 3]> {
        if b.len() < 0x14 || b[2] == 0 { return None; }
        let argb = |o: usize| { let v = u32::from_le_bytes([b[o], b[o + 1], b[o + 2], b[o + 3]]); [((v >> 16) & 0xff) as f32 / 255.0, ((v >> 8) & 0xff) as f32 / 255.0, (v & 0xff) as f32 / 255.0] };
        let f = if f.is_finite() { f.clamp(0.0, 1.0) } else { 0.0 };
        let mix = |a: [f32; 3], c: [f32; 3], t: f32| [a[0] + (c[0] - a[0]) * t, a[1] + (c[1] - a[1]) * t, a[2] + (c[2] - a[2]) * t];
        Some(match b[2] {
            1 => argb(4),
            2 => mix(argb(4), argb(0x10), f),
            3 => { let s = (f * 2.0).floor().min(1.0) as usize; let t = if f >= 1.0 { 1.0 } else { f * 2.0 - s as f32 }; if s == 0 { mix(argb(4), argb(8), t) } else { mix(argb(8), argb(0x10), t) } }
            _ => { let s = (f * 3.0).floor().min(2.0) as usize; let t = if f >= 1.0 { 1.0 } else { f * 3.0 - s as f32 }; mix(argb(4 + 4 * s), argb(8 + 4 * s), t) }
        })
    }
    /// Colour ramp ends of a colour blob: (c0 = output at f=0, c3 = output at f=1). Slot 1/2 may hold
    /// stale floats (spec §1.4) so only the outer slots are read.
    fn decode_color_ramp(b: &[u8]) -> Option<([f32; 3], [f32; 3])> {
        if b.len() < 0x14 || b[2] == 0 { return None; }
        let argb = |o: usize| { let v = u32::from_le_bytes([b[o], b[o + 1], b[o + 2], b[o + 3]]); [((v >> 16) & 0xff) as f32 / 255.0, ((v >> 8) & 0xff) as f32 / 255.0, (v & 0xff) as f32 / 255.0] };
        Some((argb(4), argb(0x10)))
    }
}

/// One light_volume of an object's attached effect, in MODEL space.
#[derive(Clone, Debug)]
pub struct LiftBeam {
    pub origin: Vec3,
    pub axis: Vec3,
    pub length: f32,
    pub offset: f32,
    pub density: f32,
    pub profile_length: f32,
    pub thickness: MapFn,
    pub alpha: MapFn,
    pub intensity: MapFn,
    pub color: [f32; 3],
    pub brightness: f32,
    pub center_offset: f32,
    pub falloff: f32,
    pub depth_fade: f32,
    pub lvtl_tag: u32,
    pub marker_sid: u32,
    /// obje attachment `primary scale` string id — non-zero = the effect's intensity is driven by an
    /// object function (muzzle flashes, firing lights); 0 = always on.
    pub scale_sid: u32,
    /// The effect has a loop start event (persistent), vs a one-shot (non-looping) effect.
    pub looping: bool,
}

/// The attached `ligh` dynamic light (model space).
#[derive(Clone, Debug)]
pub struct LiftLight {
    pub pos: Vec3,
    /// Colour function output at t=0 (linear, not yet × intensity).
    pub color: [f32; 3],
    /// Intensity function output at t=0.
    pub intensity: f32,
    /// `ligh` +0x08 "attenuation end distance" (wu) = the engine's
    /// LIGHT_FAR_ATTENUATION_END and its simple-light cull radius (bounding radius² = end²).
    pub radius: f32,
    /// `ligh` +0x0C "attenuation start distance" (wu): the engine packs
    /// LIGHT_FAR_ATTENUATION_RATIO = 1 / max(end - start, 1e-4) (reach_tag_test.exe sub_14082B6B0),
    /// and simple_lights.hlsl_include evaluates falloff = saturate((end - d) * ratio)².
    pub atten_start: f32,
    /// `ligh` +0x00 light method (0 screenspace, 1 inline, 2 re-render) and
    /// +0x02 word flags, for diagnostics.
    pub method: u8,
    pub flags: u16,
    /// The raw colour (+0x48) / intensity (+0x6C) function blobs so ANIMATED
    /// lights (ff_light_flash_*: periodic colour + intensity in game seconds — light_update
    /// sub_140D61E60 feeds game time as the function input) can be evaluated per frame with
    /// `LiftLight::radiance_at`. Empty for constants.
    pub color_blob: Vec<u8>,
    pub intensity_blob: Vec<u8>,
    pub light_tag: u32,
    pub marker_sid: u32,
    pub scale_sid: u32,
}

impl LiftLight {
    /// Engine light colour = colour_fn(t) × intensity_fn(t) (reach_tag_test.exe
    /// light_update sub_140D61E60: `sub_14040E100(color_fn_out, intensity_fn_out, light+180)`), the
    /// value the simple-light packer uploads as LIGHT_COLOR. `t` = seconds (game time).
    fn radiance_at(&self, t: f32) -> [f32; 3] {
        let color = if self.color_blob.len() >= 0x14 {
            MapFn::decode(&self.color_blob)
                .and_then(|f| MapFn::decode_color_at(&self.color_blob, f.eval(t)))
                .unwrap_or(self.color)
        } else {
            self.color
        };
        let intensity = if self.intensity_blob.len() >= 0x0c {
            MapFn::decode(&self.intensity_blob).map(|f| f.eval(t)).filter(|v| v.is_finite()).map(|v| v.max(0.0)).unwrap_or(self.intensity)
        } else {
            self.intensity
        };
        [color[0] * intensity, color[1] * intensity, color[2] * intensity]
    }
}

#[derive(Clone, Debug, Default)]
pub struct LiftFx {
    pub beams: Vec<LiftBeam>,
    pub lights: Vec<LiftLight>,
}

/// One placed dynamic point light (a Forge ff_light_*, a grav lift,...): the
/// attached `ligh` decoded in model space plus the instance's WORLD position.
#[derive(Clone, Debug)]
pub struct ForgeLight {
    pub pos: Vec3,
    pub light: LiftLight,
}

#[cfg(test)]
mod forge_light_radius_tests {
    use super::*;
    fn blob(hex: &str) -> Vec<u8> { (0..hex.len()).step_by(2).map(|i| u8::from_str_radix(&hex[i..i + 2], 16).unwrap()).collect() }
    fn light(color_blob: Vec<u8>, intensity_blob: Vec<u8>, end: f32, start: f32) -> LiftLight {
        let color = MapFn::decode_color(&color_blob).unwrap_or([1.0, 1.0, 1.0]);
        let intensity = MapFn::decode(&intensity_blob).map(|f| f.eval(0.0)).unwrap_or(1.0);
        LiftLight { pos: Vec3::ZERO, color, intensity, radius: end, atten_start: start, method: 1, flags: 0, color_blob, intensity_blob, light_tag: 0, marker_sid: 0, scale_sid: 0 }
    }
    // Exact blobs from forge_halo (HMS_LIFTFX_DIAG=1d95,1dcd): ff_light_red ligh 0x1d9c colour =
    // constant (1, 0.153, 0.043), intensity = constant 5; ff_light_flash_red ligh 0x1dd4 colour = periodic
    // cosine black -> red, frequency 0.25 (period 4 s), intensity constant 5.
    const RED_COLOR: &str = "013401000b27ff00000000000000000000ff00006f12833a6f12033b00000000";
    const FLASH_COLOR: &str = "033402000b27ff000000000000000000000000ff6f12833a6f12033b14000000020000000000803e00000000000000000000803f";
    const INTENSITY_5: &str = "013400000000a0400000a04000000000000000006f12833a6f12033b00000000";

    #[test]
    fn constant_forge_light_radiance_is_colour_times_intensity() {
        let l = light(blob(RED_COLOR), blob(INTENSITY_5), 11.0, 0.1);
        let r = l.radiance_at(0.0);
        assert!((r[0] - 5.0).abs() < 1e-3 && (r[1] - 5.0 * 39.0 / 255.0).abs() < 1e-3 && (r[2] - 5.0 * 11.0 / 255.0).abs() < 1e-3, "{r:?}");
        // time-invariant
        let r2 = l.radiance_at(7.3);
        assert!((r[0] - r2[0]).abs() < 1e-6 && (r[1] - r2[1]).abs() < 1e-6);
    }

    #[test]
    fn flash_light_cycles_black_to_full_over_four_seconds() {
        let l = light(blob(FLASH_COLOR), blob(INTENSITY_5), 5.0, 0.1);
        let r0 = l.radiance_at(0.0);
        let r1 = l.radiance_at(1.0);
        let r2 = l.radiance_at(2.0);
        let r4 = l.radiance_at(4.0);
        assert!(r0[0].abs() < 1e-3, "t=0 black: {r0:?}");
        assert!((r1[0] - 2.5).abs() < 0.05, "t=1 half: {r1:?}");
        assert!((r2[0] - 5.0).abs() < 1e-2, "t=2 full: {r2:?}");
        assert!(r4[0].abs() < 1e-3, "t=4 black again: {r4:?}");
    }

    #[test]
    fn engine_falloff_reaches_exactly_the_attenuation_end() {
        // simple_lights.hlsl_include: falloff = saturate((end - d) * ratio)^2, ratio = 1/(end - start)
        let (end, start) = (11.0f32, 0.1f32);
        let ratio = 1.0 / (end - start);
        let f = |d: f32| ((end - d) * ratio).clamp(0.0, 1.0).powi(2);
        assert!((f(0.1) - 1.0).abs() < 1e-6);
        assert!(f(11.0) == 0.0 && f(12.0) == 0.0);
        assert!((f(5.55) - 0.25).abs() < 1e-3, "{}", f(5.55));
    }
}

/// One 0x20 tag property — `input`/`range`/modifier state indices (particle_state_list:
/// 0 age, 1 system age, 2 particle random, 3 system random, 4-7 correlation 1-4 (= m_random.xyzw),
/// 10 emit time, 11 location lod, 12 game time, 15 rotation, 16 location random, 17 distance from
/// emitter, 20 |velocity|·0.1, 22-25 random seed 5-8 (= m_random2.xyzw), 26/27 system seed 3/4) plus
/// the decoded function. `ramp` is set for COLOUR properties (c0 at f=0 → c3 at f=1).
#[derive(Clone, Debug)]
pub struct PropFn {
    pub input: u8,
    pub range: u8,
    pub modifier: u8,
    pub mod_input: u8,
    pub f: MapFn,
    pub ramp: Option<([f32; 3], [f32; 3])>,
    pub rc: f32,
}

const PSTATE_N: usize = 28;

impl PropFn {
    fn st(st: &[f32; PSTATE_N], i: u8) -> f32 { st.get(i as usize).copied().unwrap_or(0.0) }
    /// particle_common.fx `particle_evaluate`.
    pub fn eval(&self, st: &[f32; PSTATE_N]) -> f32 {
        let mut o = self.f.eval2(Self::st(st, self.input), Self::st(st, self.range));
        match self.modifier { 1 => o += Self::st(st, self.mod_input), 2 => o *= Self::st(st, self.mod_input), _ => {} }
        if o.is_finite() { o } else { 0.0 }
    }
    /// Colour property: the c0→c3 ramp at the function output (white when the blob had no colours).
    fn eval_color(&self, st: &[f32; PSTATE_N]) -> [f32; 3] {
        match self.ramp {
            Some((c0, c3)) => { let f = self.eval(st).clamp(0.0, 1.0); [c0[0] + (c3[0] - c0[0]) * f, c0[1] + (c3[1] - c0[1]) * f, c0[2] + (c3[2] - c0[2]) * f] }
            None => [1.0, 1.0, 1.0],
        }
    }
    /// Max of the scalar output over the unit input × range square (bounds a lifespan/size).
    fn max_over_unit(&self) -> f32 {
        let mut m = f32::MIN;
        let mut st = [0f32; PSTATE_N]; st[11] = 1.0;
        for i in 0..=10 { for r in 0..=4 {
            st[self.input as usize % PSTATE_N] = i as f32 / 10.0;
            st[self.range as usize % PSTATE_N] = r as f32 / 4.0;
            m = m.max(self.eval(&st));
        } }
        m
    }
}

